    // DATA: CHANGES array (all countries)
    const CHANGES = [
      {country:'lithuania',flag:'🇱🇹',name:'Lithuania',section:'lt-tax',title:'Three-tier progressive income tax (20%/25%/32%) tied to the average wage',effective:'2026-01-01',added:'2026-09-08',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'From 1 January 2026 employment income is taxed progressively: 20% on combined annual income up to 36 times the average monthly salary (VDU, preliminarily approx. EUR 82,962), 25% between 36 and 60 VDU (approx. EUR 82,962 to EUR 138,270), and 32% above 60 VDU.',employer:['Load the 2026 three-tier withholding rates and VDU-based thresholds into payroll software.'],employee:['Higher earners now pass through a new 25% middle band before reaching the 32% rate.'],note:'Thresholds are indexed to the VDU and move annually.',example:'',sourceUrl:'https://kpmg.com/lt/en/insights/2025/10/changes-in-taxation-of-personal-income-as-of-2026.html',sourceLabel:'Source: KPMG Lithuania - Changes in taxation of personal income as of 2026'}},
      {country:'lithuania',flag:'🇱🇹',name:'Lithuania',section:'lt-minimum-wage',title:'MMA rises to €1,153 a month',effective:'2026-01-01',added:'2026-09-30',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'For 2026 the minimum monthly wage (MMA) is EUR 1,153 and the minimum hourly rate is EUR 7.05.',employer:['Raise any employee paid below EUR 1,153 a month (or EUR 7.05 an hour) from the January 2026 pay run.'],employee:['Minimum-wage workers receive the higher MMA automatically from January 2026.'],note:'',example:'',sourceUrl:'https://www.vmi.lt/evmi/gyventoju-pajamu-mokescio-pakeitimai-nuo-2026-m.',sourceLabel:'Source: VMI - Gyventojų pajamų mokesčio pakeitimai nuo 2026 m.'}},
      {country:'luxembourg',flag:'🇱🇺',name:'Luxembourg',section:'lu-index',title:'Index tranche triggers 2.5% increase in wages and social parameters',effective:'2026-06-01',added:'2026-09-30',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'From 1 June 2026 the sliding wage scale index moved to 992.24 (from 968.04), triggering a 2.5% increase in the minimum and maximum contributory amounts and other social parameters.',employer:['Apply the 2.5% index adjustment to wages and update contribution floors and ceilings from the June 2026 pay run.'],employee:['Wages and social parameters rise by 2.5% under the automatic indexation.'],note:'',example:'',sourceUrl:'https://gouvernement.lu/fr/actualites/toutes_actualites/communiques/2026/06-juin/04-parametres-sociaux.html',sourceLabel:'Source: Gouvernement du Luxembourg - Paramètres sociaux au 1er juin 2026'}},
      {country:'luxembourg',flag:'🇱🇺',name:'Luxembourg',section:'lu-minimum-wage',title:'Social minimum wage rises to €2,771.33 (unqualified)',effective:'2026-06-01',added:'2026-09-30',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'From 1 June 2026 the monthly social minimum wage is EUR 2,771.33 for unqualified workers aged 18+ and EUR 3,325.59 for qualified workers (120%); EUR 2,217.06 applies at 17-18 (80%) and EUR 2,078.49 at 15-17 (75%).',employer:['Raise any employee below the new rates from the June 2026 pay run.'],employee:['Minimum-wage workers receive the indexed rate automatically.'],note:'',example:'',sourceUrl:'https://www.gtai.de/de/trade/luxemburg/recht/anpassung-des-luxemburgischen-mindestlohnes-995946',sourceLabel:'Source: Germany Trade & Invest - Anpassung des luxemburgischen Mindestlohnes'}},
      {country:'malta',flag:'🇲🇹',name:'Malta',section:'mt-cola',title:'2026 cost-of-living adjustment of €4.66 a week',effective:'2026',added:'2026-09-30',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'Budget 2026 set the cost of living adjustment (COLA) for 2026 at EUR 4.66 a week.',employer:['Add the EUR 4.66 weekly COLA to employee pay for 2026.'],employee:['Weekly pay rises by EUR 4.66 through the COLA.'],note:'',example:'Annual COLA effect: 4.66 x 52 = EUR 242.32.',sourceUrl:'https://www.bdo.com.mt/en-gb/insights/malta-budget-highlights/malta-budget-2026-highlights',sourceLabel:'Source: BDO Malta - Malta Budget 2026: Key Highlights'}},
      {country:'malta',flag:'🇲🇹',name:'Malta',section:'mt-leave',title:'Paid miscarriage leave and parental bereavement leave of 7 working days',effective:'2026-01-01',added:'2026-09-30',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'From 1 January 2026, L.N. 274 of 2025 gives every worker seven working days of miscarriage leave without loss of wages, and L.N. 275 of 2025 introduces seven working days of paid parental bereavement leave after the death of a child under 18.',employer:['Record the new leave types in payroll; employers can claim reimbursement from the Department of Social Security within three months of the leave.'],employee:['Workers are entitled to seven paid working days in each case.'],note:'',example:'',sourceUrl:'https://gvzh.mt/insights/new-employment-laws-malta-2026/',sourceLabel:'Source: GVZH Advocates - New employment laws Malta 2026'}},
      {country:'netherlands',flag:'🇳🇱',name:'Netherlands',section:'nl-tax',title:'Three-bracket box 1 scale and tax credits for 2026',effective:'2026-01-01',added:'2026-09-08',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'Box 1 rates for 2026 (below AOW age): 35.75% up to €38,883, 37.56% from €38,883 to €78,426, and 49.50% above €78,426. The algemene heffingskorting is up to €3,115 and the arbeidskorting peaks at €5,685 at €45,592 of income.',employer:['Use the Belastingdienst 2026 wage tax tables from the first January pay run.'],employee:['Tax credits are applied through payroll withholding.'],note:'',example:'',sourceUrl:'https://www.belastingdienst.nl/wps/wcm/connect/nl/voorlopige-aanslag/content/voorlopige-aanslag-tarieven-en-heffingskortingen',sourceLabel:'Source: Belastingdienst - Voorlopige aanslag 2026: gebruikte tarieven en heffingskortingen'}},
      {country:'netherlands',flag:'🇳🇱',name:'Netherlands',section:'nl-minimum-wage',title:'Minimum wage rises to €14.99 an hour from 1 July 2026',effective:'2026-07-01',added:'2026-09-30',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'The statutory minimum wage for workers aged 21 and over was €14.71 an hour from 1 January 2026 and rose to €14.99 an hour from 1 July 2026.',employer:['Raise any worker aged 21+ below €14.99 an hour from the July 2026 pay run.'],employee:['Minimum-wage workers receive the increase automatically.'],note:'',example:'',sourceUrl:'https://www.rijksoverheid.nl/themas/werk/minimumloon/bedragen-minimumloon/bedragen-minimumloon-2026',sourceLabel:'Source: Rijksoverheid - Bedragen minimumloon 2026'}},
      {country:'norway',flag:'🇳🇴',name:'Norway',section:'no-tax',title:'2026 bracket tax (trinnskatt), personal allowance and trygdeavgift',effective:'2026-01-01',added:'2026-09-08',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'For 2026 trinnskatt applies at 1.7% above 226,100 kr, 4.0% above 318,300 kr, 13.7% above 725,050 kr, 16.8% above 980,100 kr and 17.8% above 1,467,200 kr. The class 1 personal allowance is 114,540 kr and trygdeavgift on wage income is 7.6%.',employer:['Retrieve updated 2026 tax cards and load the 2026 tables before the first pay run.'],employee:['Tax cards are issued automatically by Skatteetaten.'],note:'',example:'',sourceUrl:'https://www.skatteetaten.no/en/rettskilder/type/uttalelser/uttalelser/forskuddsutskrivingen-2026/',sourceLabel:'Source: Skatteetaten - Forskuddsutskrivingen 2026'}},
      {country:'norway',flag:'🇳🇴',name:'Norway',section:'no-employer-ni',title:'Employer NI zone rates and boundaries unchanged for 2026',badge:'Confirmed for 2026',effective:'2026',added:'2026-09-08',updated:'2026-10-04',category:'payroll',impact:'low',upcoming:false,detail:{lead:'Skatteetaten confirmed no changes to zones or rates from 2025 to 2026: 14.1% (zone I), 10.6% (II), 6.4% (III), 5.1% (IV), 7.9% (IVa) and 0% (V). Zone Ia is 10.6% up to an exemption amount of 850,000 kr, then 14.1%.',employer:['Confirm each employee\'s zone in the a-melding remains correct.'],employee:['Employer NI is an employer cost and does not reduce net pay.'],note:'',example:'700,000 kr of wages in zone III: 700,000 x 6.4% = 44,800 kr; in zone I: 700,000 x 14.1% = 98,700 kr.',sourceUrl:'https://www.skatteetaten.no/rettskilder/type/skattedirektoratets-meldinger/arbeidsgiveravgift-til-folketrygden-for-2026/',sourceLabel:'Source: Skatteetaten - Arbeidsgiveravgift til folketrygden for 2026'}},
      {country:'norway',flag:'🇳🇴',name:'Norway',section:'no-benefits',title:'Grunnbeløp rises 4.91% from 1 May 2026',effective:'2026-05-01',added:'2026-09-08',category:'payroll',impact:'low',upcoming:false,detail:{lead:'The National Insurance basic amount (G) rose from 130,160 kr to 136,549 kr from 1 May 2026, an increase of 6,389 kr or 4.91%.',employer:['Update any G-based thresholds used in payroll or HR systems from May 2026.'],employee:['Benefits expressed as multiples of G are adjusted upward.'],note:'',example:'A 6G benefit cap: 6 x 136,549 = 819,294 kr a year.',sourceUrl:'https://www.nav.no/regulering-2026',sourceLabel:'Source: NAV - Regulering 2026'}},
      {country:'poland',flag:'🇵🇱',name:'Poland',section:'pl-minimum-wage',title:'Minimum wage rises to 4,806 zł',effective:'2026-01-01',added:'2026-09-30',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'Under the Council of Ministers regulation of 11 September 2025, the minimum monthly wage from 1 January 2026 is 4,806 zł and the minimum hourly rate is 31.40 zł.',employer:['Raise any employee below 4,806 zł a month (or 31.40 zł an hour where the hourly minimum applies) from January 2026.'],employee:['Minimum-wage workers receive the increase automatically.'],note:'',example:'',sourceUrl:'https://zielonalinia.gov.pl/wynagrodzenie-minimalne-w-2026-1/',sourceLabel:'Source: Zielona Linia (gov.pl) - Wynagrodzenie minimalne w 2026'}},
      {country:'poland',flag:'🇵🇱',name:'Poland',section:'pl-pay-transparency',title:'Recruitment pay transparency in force; full pay transparency law not before 2027',effective:'2025-12-24',added:'2026-09-30',category:'reporting',impact:'high',upcoming:false,detail:{lead:'Labour Code recruitment transparency requirements have applied since 24 December 2025. The full law implementing Directive 2023/970 (revised draft of 4 May 2026) will enter into force 6 months after publication, no earlier than early 2027.',employer:['Apply recruitment-stage pay transparency rules now and prepare pay structures and gender pay gap reporting for 2027.'],employee:[],note:'',example:'',sourceUrl:'https://www.sdworx.pl/pl-pl/blog/place-benefity/jawnosc-wynagrodzen-dopiero-od-2027-roku-nowy-projekt-ustawy',sourceLabel:'Source: SD Worx - Jawność wynagrodzeń dopiero od 2027 roku'}},
      {country:'finland',flag:'🇫🇮',name:'Finland',section:'fi-tax',title:'State tax scale indexed, top marginal rate cut to 52%, earned-income credit raised',effective:'2026-01-01',added:'2026-09-08',updated:'2026-10-04',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'For 2026 the lower thresholds of the state income tax scale were indexed by about 3.5%, and the top marginal tax rate was lowered to 52% (previously about 59%); this is the overall marginal rate as stated by Vero, not the state scale\'s top band (37.50%, before municipal and church tax). The maximum earned-income tax credit (työtulovähennys) rose by €205 to €3,430, and its child supplement rose by €55 to €105 per child.',employer:['Withholding is driven by each employee\'s tax card - make sure 2026 tax cards from Vero are loaded for the first 2026 pay run.'],employee:['Most earners see lower withholding in 2026; higher earners benefit most from the top marginal rate cut.'],note:'',example:'',sourceUrl:'https://www.vero.fi/tietoa-verohallinnosta/tilastot/verotulojen-kehitys/muutokset-veroperusteisiin-verovuosittain/2026/',sourceLabel:'Source: Vero (Finnish Tax Administration) - Muutokset veroperusteisiin 2026'}},
      {country:'finland',flag:'🇫🇮',name:'Finland',section:'fi-pay-transparency',title:'Pay transparency bill: pay-gap reporting via the Incomes Register',badge:'Proposed from 1 Jan 2027',effective:'2027-01-01',added:'2026-09-30',category:'reporting',impact:'high',upcoming:true,draft:true,detail:{lead:'On 9 July 2026 the government proposed amendments to equal-pay legislation implementing the EU pay transparency directive, with entry into force proposed for 1 January 2027. Employers regularly employing at least 100 workers would report gender pay-gap data through the Incomes Register.',employer:['If you regularly employ 100+ workers, prepare to report pay-gap data through the Incomes Register.'],employee:['Pay-gap information on your employer becomes available through the new reporting.'],note:'Government proposal - subject to parliamentary approval.',example:'',sourceUrl:'https://valtioneuvosto.fi/-/1271139/hallitus-esittaa-lakimuutoksia-palkkauksen-lapinakyvyyden-vahvistamiseksi',sourceLabel:'Source: Finnish Government - Hallitus esittää lakimuutoksia palkkauksen läpinäkyvyyden vahvistamiseksi'}},
      {country:'france',flag:'🇫🇷',name:'France',section:'fr-pmss',title:'Social security ceiling (PMSS) rises 2% to €4,005 a month',effective:'2026-01-01',added:'2026-09-30',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'The monthly social security ceiling rises to €4,005 (from €3,925 in 2025), a 2% increase; the annual ceiling (PASS) is €48,060. It is the base for capped contributions and for maximum social security benefits.',employer:['Update the PMSS/PASS in payroll from the January 2026 pay run so capped contributions are calculated on €4,005.'],employee:['Capped contributions and maximum daily sick-pay benefits rise with the ceiling.'],note:'',example:'€4,005 × 12 = €48,060 annual ceiling.',sourceUrl:'https://www.service-public.gouv.fr/particuliers/actualites/A15386',sourceLabel:'Source: Service-Public.fr - Plafond de la sécurité sociale 2026'}},
      {country:'france',flag:'🇫🇷',name:'France',section:'fr-smic',title:'SMIC revalued twice: 1 January and 1 June 2026',badge:'Effective 1 Jan and 1 Jun 2026',effective:'2026-06-01',added:'2026-09-30',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'The SMIC was €12.02 gross an hour from 1 January 2026 (€1,823.03 a month on a 35-hour week), then a further 2.41% on 1 June 2026 to €12.31 an hour (€1,867.02 a month).',employer:['Raise any pay below €12.31/hour from June 2026 and review minimum-linked calculations.'],employee:['Minimum-wage earners received two increases in 2026.'],note:'',example:'',sourceUrl:'https://www.service-public.gouv.fr/particuliers/actualites/A18916',sourceLabel:'Source: Service-Public.fr - Salaire minimum au 1er juin 2026'}},
      {country:'germany',flag:'🇩🇪',name:'Germany',section:'de-employment-law',title:'Mindestlohn rises to €13.90; Minijob limit to €603',effective:'2026-01-01',added:'2026-09-08',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'The statutory minimum wage has been €13.90 gross per hour since 1 January 2026 and will rise to €14.60 in 2027. The Minijob earnings limit rose accordingly to €603 a month from 1 January 2026 and rises to €633 in 2027.',employer:['Check hourly rates and Minijob hours so pay stays at or above €13.90 and within the €603 limit.'],employee:['Minimum-wage workers receive a raise; a further increase to €14.60 follows in 2027.'],note:'',example:'',sourceUrl:'https://www.bundesregierung.de/breg-de/aktuelles/mindestlohn-steigt-2391010',sourceLabel:'Source: Bundesregierung - Mindestlohn steigt'}},
      {country:'germany',flag:'🇩🇪',name:'Germany',section:'de-employer-costs',title:'Social insurance contribution ceilings raised for 2026',effective:'2026-01-01',added:'2026-09-08',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'The 2026 contribution assessment ceiling for pension insurance is €8,450 a month; for statutory health insurance it is €69,750 a year (€5,812.50 a month). The compulsory insurance threshold for health and long-term care insurance is €6,450 a month (€77,400 a year). The values reflect 5.16% wage growth in 2024.',employer:['Update ceilings in payroll so contributions are calculated up to the new limits.'],employee:['Higher earners pay contributions on a larger share of salary.'],note:'',example:'',sourceUrl:'https://www.deutsche-rentenversicherung.de/DRV/DE/Ueber-uns-und-Presse/Presse/Meldungen/2025/250910-sv-rechengroessen-vo-2026',sourceLabel:'Source: Deutsche Rentenversicherung - Rechengrößen der Sozialversicherung 2026'}},
      {country:'greece',flag:'🇬🇷',name:'Greece',section:'gr-tax',title:'New 2026 income tax scale with lower middle rates',badge:'Effective income year 2026',effective:'2026',added:'2026-09-08',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'For a taxpayer over 30 without children, the 2026 scale is 9% up to €10,000, 20% from €10,000 to €20,000, 26% from €20,000 to €30,000, 34% from €30,000 to €40,000, 39% from €40,000 to €60,000, and 44% above €60,000. Separate scales apply by age and number of children.',employer:['Load the new 2026 scales (including age- and child-based variants) into payroll withholding.'],employee:['Most employees see lower withholding compared with 2025.'],note:'',example:'',sourceUrl:'https://www.taxheaven.gr/news/71602/oi-nees-analytikes-klimakes-forologias-2026-sygkrish-2025-2026',sourceLabel:'Source: Taxheaven - Οι νέες αναλυτικές κλίμακες φορολογίας 2026'}},
      {country:'greece',flag:'🇬🇷',name:'Greece',section:'gr-employment-law',title:'Minimum wage rises to €920',effective:'2026-04-01',added:'2026-09-08',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'From 1 April 2026 the minimum monthly wage rises from €880 to €920, the sixth consecutive increase. The government targets €950 by 2027.',employer:['Raise pay for employees at the minimum and review seniority scales and allowances tied to the minimum wage.'],employee:['Minimum-wage workers receive €40 more a month.'],note:'',example:'€920 - €880 = €40 a month increase.',sourceUrl:'https://www.taxheaven.gr/news/73185/katwtatos-misoos-sta-920-eyrw-apo-1h-aprilioy',sourceLabel:'Source: Taxheaven - Κατώτατος μισθός στα 920 ευρώ από 1η Απριλίου'}},
      {country:'hungary',flag:'🇭🇺',name:'Hungary',section:'hu-employment-law',title:'Minimum wage rises 11%, guaranteed wage minimum 7%',effective:'2026-01-01',added:'2026-09-08',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'From 1 January 2026 the minimálbér rises 11% to 322,800 Ft a month (1,856 Ft/hour) and the garantált bérminimum rises 7% to 373,200 Ft a month (2,145 Ft/hour), following agreement with employer and employee representatives.',employer:['Raise pay for affected employees from the January 2026 pay run.'],employee:['Minimum-wage and guaranteed-minimum earners receive raises.'],note:'',example:'',sourceUrl:'https://www.bdo.hu/hu-hu/aktualitasok-blog/blog/minimalber-es-garantalt-berminimum-2026-minden-fontos-tudnivalo-egy-helyen',sourceLabel:'Source: BDO Hungary - Minimálbér és garantált bérminimum 2026'}},
      {country:'hungary',flag:'🇭🇺',name:'Hungary',section:'hu-employer-costs',title:'Entrepreneurs\' minimum szocho base cut to 100% of minimum wage',effective:'2026-01-01',added:'2026-09-08',category:'payroll',impact:'low',upcoming:false,detail:{lead:'From 1 January 2026 the 112.5% multiplier for primary-occupation sole and corporate entrepreneurs is removed: their monthly social contribution tax (szocho) base is at least 100% of the minimum wage or guaranteed wage minimum. Sole entrepreneurs taxed on business income may now file quarterly.',employer:['Entrepreneurs should update their minimum szocho base.'],employee:['No change to employee deductions from this measure.'],note:'',example:'',sourceUrl:'https://nav.gov.hu/ado/szocialis_hozzajarulasi_ado/Csokken_a_szocialis_hozzajarulasi_ado_alapja_es_valtozik_az_egyeni_vallalkozok_bevallasi_gyakorisaga',sourceLabel:'Source: NAV (Hungarian Tax Administration) - Csökken a szociális hozzájárulási adó alapja'}},
      {country:'ireland',flag:'🇮🇪',name:'Ireland',section:'ie-tax',title:'Tax credits unchanged; USC 2% band widens; PRSI rises from October',effective:'2026-01-01',added:'2026-09-08',updated:'2026-10-03',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'Budget 2026 keeps the personal, employee and earned-income tax credits at €2,000. From 1 January 2026 the 2% USC band increases by €1,318 to €28,700. Employer and employee PRSI rates rise by 0.15% from 1 October 2026.',employer:['Apply the new USC band from January and the PRSI increase from October 2026.'],employee:['Slight USC saving; small PRSI increase from October 2026.'],note:'',example:'',sourceUrl:'https://kpmg.com/ie/en/insights/tax/budget-2026/personal-tax.html',sourceLabel:'Source: KPMG Ireland - Budget 2026 personal tax'}},
      {country:'ireland',flag:'🇮🇪',name:'Ireland',section:'ie-employment-law',title:'National Minimum Wage rises to €14.15',effective:'2026-01-01',added:'2026-09-08',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'The National Minimum Wage increases by 65c to €14.15 per hour from 1 January 2026.',employer:['Raise any pay below €14.15/hour from the January 2026 pay run.'],employee:['Minimum-wage workers receive 65c more per hour.'],note:'',example:'',sourceUrl:'https://kpmg.com/ie/en/insights/tax/budget-2026/personal-tax.html',sourceLabel:'Source: KPMG Ireland - Budget 2026 personal tax'}},
      {country:'italy',flag:'🇮🇹',name:'Italy',section:'it-tax',title:'IRPEF middle rate set at 33% for 2026',badge:'Effective income year 2026',effective:'2026-01-01',added:'2026-09-08',updated:'2026-10-03',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'For 2026 IRPEF is 23% up to €28,000, 33% from €28,001 to €50,000 and 43% above €50,000.',employer:['Update withholding tables for the 33% middle bracket.'],employee:['Middle earners pay less IRPEF.'],note:'',example:'',sourceUrl:'https://taxsummaries.pwc.com/italy/individual/taxes-on-personal-income',sourceLabel:'Source: PwC Worldwide Tax Summaries - Italy, taxes on personal income'}},
      {country:'italy',flag:'🇮🇹',name:'Italy',section:'it-pay-transparency',title:'Pay transparency decree in force',effective:'2026-06-07',added:'2026-09-30',category:'reporting',impact:'high',upcoming:false,detail:{lead:'Legislative Decree 7 May 2026, No. 96, published on 1 June 2026, implements EU Directive 2023/970 on pay transparency and entered into force on 7 June 2026.',employer:['Review recruitment, pay-structure and reporting processes against the decree\'s transparency obligations.'],employee:['New rights to pay transparency under the decree.'],note:'',example:'',sourceUrl:'https://www.normattiva.it/eli/id/2026/06/01/26G00112/ORIGINAL',sourceLabel:'Source: Normattiva - D.Lgs. 7 maggio 2026, n. 96'}},
      {country:'latvia',flag:'🇱🇻',name:'Latvia',section:'lv-employment-law',title:'Minimum wage rises to €780',effective:'2026-01-01',added:'2026-09-08',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'The minimum monthly wage within normal working hours rises from €740 to €780 from 1 January 2026.',employer:['Raise pay for employees below €780 from the January 2026 pay run.'],employee:['Minimum-wage workers receive €40 more a month.'],note:'',example:'€780 - €740 = €40.',sourceUrl:'https://lvportals.lv/norises/383027-minimala-alga-2026-gada-bus-780-eiro-2025',sourceLabel:'Source: LV portāls - Minimālā alga 2026. gadā būs 780 eiro'}},
      {country:'latvia',flag:'🇱🇻',name:'Latvia',section:'lv-tax',title:'Non-taxable minimum rises to €550 a month',effective:'2026-01-01',added:'2026-09-08',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'The fixed monthly non-taxable minimum rises from €510 to €550 in 2026. IIN rates remain 25.5% on annual income up to €105,300 and 33% above, with an additional 3% on annual income over €200,000.',employer:['Apply the €550 non-taxable minimum in monthly withholding for employees who submitted a tax booklet.'],employee:['Slightly lower withholding for employees.'],note:'',example:'',sourceUrl:'https://ifinanses.lv/raksti/aktuali/vid-informacija/lv-lielaks-neapliekamais-minimums-un-citas-izmainas-iin-joma/30884',sourceLabel:'Source: iFinanses (VID information) - Lielāks neapliekamais minimums un citas izmaiņas IIN jomā'}},
      {country:'portugal',flag:'🇵🇹',name:'Portugal',section:'pt-tax',title:'Withholding tables updated 3.51%; rates on brackets 2–5 cut 0.3 points',effective:'2026-01-01',added:'2026-09-08',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'The 2026 IRS withholding tables for employment income and pensions raise the bracket thresholds by 3.51% and cut the marginal rates on the 2nd to 5th brackets by 0.3 percentage points versus 2025. Monthly income up to €920 - aligned with the new national minimum wage - is exempt from withholding, and the minimum subsistence threshold rises to €12,880 a year, extending full or partial IRS exemption to more low earners and pensioners.',employer:['Confirm payroll software has loaded the 2026 withholding tables published in the Diário da República before the first January pay run.','No separate filing is needed - the marginal-rate model (in force since 2023) applies each bracket only to the income exceeding the prior threshold, computed automatically.'],employee:['An employee earning at or near the minimum wage now has no IRS withheld at all; most other employees see a small net pay increase from the 0.3-point rate cuts on brackets 2–5.'],note:'',example:'',sourceUrl:'https://www.oe.gov.pt/noticias/publicadas-as-tabelas-de-retencao-na-fonte-do-irs-para-2026/',sourceLabel:'Source: Orçamento do Estado - Tabelas de retenção na fonte do IRS para 2026'}},
{country:'portugal',flag:'🇵🇹',name:'Portugal',section:'pt-employment-law',title:'Guaranteed monthly minimum wage (RMMG) rises 5.7% to €920',effective:'2026-01-01',added:'2026-09-08',updated:'2026-10-04',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'Decree-Law 139/2025 of 29 December sets the guaranteed monthly minimum wage (retribuição mínima mensal garantida, RMMG) at €920 from 1 January 2026, an increase of 5.7%.',employer:['Raise any employee paid below €920 a month to at least €920 from 1 January 2026.'],employee:['Workers on the minimum wage are entitled to at least €920 a month from 1 January 2026.'],note:'',example:'',sourceUrl:'https://www.dgert.gov.pt/retribuicao-minima-mensal-garantida-para-2026',sourceLabel:'Source: DGERT - Retribuição mínima mensal garantida para 2026'}},
      {country:'portugal',flag:'🇵🇹',name:'Portugal',section:'pt-reporting',title:'New Segurança Social contribution model replaces self-filed DMR',badge:'Optional during 2026; mandatory 1 Jan 2027',effective:'2026-01-01',added:'2026-09-08',updated:'2026-10-03',category:'reporting',impact:'high',upcoming:false,detail:{lead:'Decreto-Lei 127/2025 of 9 December introduces a new model in which Segurança Social calculates the monthly declaration from data the employer communicates. The employer confirms or corrects it by the 20th of the following month (currently the 10th), silence counts as acceptance, and contributions are paid between the 1st and 25th of the following month. Changes to permanent pay must be communicated by the 10th of the following month via Segurança Social Direta or the Plataforma de Serviços de Interoperabilidade. Employers may opt in at any time during 2026; from 1 January 2027 the model is mandatory for all employers.',employer:['Once you opt in, the DMR can no longer be sent in the current format - plan the switch with your payroll provider.','Set up processes to communicate changes to permanent pay by the 10th of the following month, and to review the pre-calculated declaration by the 20th.','Prepare for mandatory use from 1 January 2027.'],employee:['No direct payslip impact; new hires must be communicated through Segurança Social Direta, including NISS and permanent remuneration.'],note:'',example:'',sourceUrl:'https://www.littler.pt/novo-modelo-comunicacao-seguranca-social/',sourceLabel:'Source: Littler Portugal - Novo modelo de comunicação à Segurança Social'}},
{country:'romania',flag:'🇷🇴',name:'Romania',section:'ro-employment-law',title:'Minimum wage set at 4,325 lei from 1 July 2026',effective:'2026-07-01',added:'2026-09-08',updated:'2026-10-04',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'Government Decision (HG) 146/2026 of 12 March 2026 sets the guaranteed gross minimum basic salary at 4,325 lei a month from 1 July 2026, for a normal average of 166.667 working hours a month (25.949 lei an hour). It repeals HG 1506/2024 from that date.',employer:['Pay at least 4,325 lei gross a month (25.949 lei an hour) for the normal working programme from 1 July 2026; the amount is stated in money and excludes bonuses and other additions.'],employee:['Employees on the minimum wage are entitled to a gross basic salary of at least 4,325 lei a month from 1 July 2026.'],note:'',example:'',sourceUrl:'https://static.anaf.ro/static/10/Anaf/legislatie/HG_146_2026.pdf',sourceLabel:'Source: Guvernul Romaniei - Hotararea nr. 146/2026 (Monitorul Oficial 196/13.03.2026)'}},
      {country:'romania',flag:'🇷🇴',name:'Romania',section:'ro-reporting',title:'New Declaration 112 form from July 2026 income',badge:'Effective 25 Aug 2026 filing',effective:'2026-08-25',added:'2026-09-08',category:'reporting',impact:'medium',upcoming:false,detail:{lead:'ANAF Order 605/2026 introduces a new version of Declaration 112 (the combined tax and contributions return), used for July 2026 income filed by 25 August 2026. It reflects the reduction of the non-taxable minimum-wage allowance from 300 lei to 200 lei a month for July-December 2026 (under OUG 89/2025), changes to medical-leave reporting, and an updated nomenclature for categories of insured persons.',employer:['Update Declaration 112 filing software to the new version before filing July 2026 income by 25 August 2026.','Remap payroll codes to the updated insured-person nomenclature and medical-leave fields.'],employee:['No direct impact beyond the smaller 200 lei non-taxable allowance for minimum-wage earners.'],note:'',example:'',sourceUrl:'https://www.lugera.ro/blog/declaratia-112-2026-noul-formular-aduce-modificari-pentru-salariul-minim-netaxabil-si-concediile-medicale/',sourceLabel:'Source: Lugera - Declarația 112 2026: ce trebuie să știe angajatorii'}},
      {country:'slovakia',flag:'🇸🇰',name:'Slovakia',section:'sk-tax',title:'Income tax moves to four bands: 19%, 25%, 30% and 35%',effective:'2026-01-01',added:'2026-09-08',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'From 1 January 2026, the progressive personal income tax on employment income uses four bands: 19% up to €43,983.32, 25% from €43,983.33 to €60,349.21, 30% from €60,349.22 to €75,010.32, and 35% above €75,010.32.',employer:['Confirm payroll software has loaded the new four-band structure before the first January pay run.'],employee:['Employees with annual income above €43,983.32 face marginal rates of 25%, 30% or 35% on the portion above each threshold.'],note:'',example:'',sourceUrl:'https://www.podnikajte.sk/dan-z-prijmov/progresivne-zdanenie-prijmov-fyzickych-osob-od-2026',sourceLabel:'Source: Podnikajte.sk - Progresívne zdanenie príjmov fyzických osôb od roku 2026'}},
      {country:'slovakia',flag:'🇸🇰',name:'Slovakia',section:'sk-employer-costs',title:'Employee health insurance rate rises from 4% to 5%',effective:'2026-01-01',added:'2026-09-08',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'From January 2026 the employee health insurance contribution rises by 1 percentage point, from 4% to 5% of gross pay (from 2% to 2.5% for employees with disabilities). The employer health insurance rate stays at 11%. Total employee contributions reach 14.4% of gross pay, while total employer contributions are 36.2%.',employer:['Update payroll with the 5% employee health insurance rate (2.5% for employees with disabilities); the employer rate is unchanged at 11%.'],employee:['Take-home pay falls slightly at an unchanged salary, since the employee health insurance rate rises from 4% to 5%.'],note:'',example:'',sourceUrl:'https://kryptomagazin.sk/odvody-zamestnanca-a-zamestnavatela-v-roku-2026/',sourceLabel:'Source: Kryptomagazín - Odvody zamestnanca a zamestnávateľa v roku 2026'}},
      {country:'slovakia',flag:'🇸🇰',name:'Slovakia',section:'sk-employment-law',title:'Minimum wage rises €99 to €915',effective:'2026-01-01',added:'2026-09-08',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'The minimum wage is €915 a month from 1 January 2026, €99 more than in 2025 - a historic increase. It is set automatically at 60% of the average wage, and night and weekend work surcharges rise with it.',employer:['Raise any employee paid below €915/month from the January 2026 pay run, and re-check minimum wage-linked surcharges for night and weekend work.'],employee:['Workers on the minimum wage get the largest automatic increase in the wage\'s history from January 2026.'],note:'',example:'',sourceUrl:'https://www.employment.gov.sk/sk/uvodna-stranka/informacie-media/aktuality/historicky-narast-minimalnej-mzdy-je-realitou-roku-2026-je-minimalna-mzda-vo-vyske-915-eur.html',sourceLabel:'Source: MPSVR SR - Historický nárast minimálnej mzdy 2026'}},
      {country:'slovenia',flag:'🇸🇮',name:'Slovenia',section:'si-tax',title:'Tax brackets shift up; rates unchanged at 16/26/33/39/50%',effective:'2026-01-01',added:'2026-09-08',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'The five dohodnina rates stay at 16%, 26%, 33%, 39%, and 50% for 2026, but each bracket threshold moves up - for example, the upper limit of the 39% bracket (above which 50% applies) rises from €78,016.32 to €82,346.23. The general annual tax relief (splošna olajšava) rises by €291.93 a year, or €24.33 a month.',employer:['Confirm payroll software has loaded the 2026 bracket thresholds and increased general relief before the first January pay run.'],employee:['Take-home pay rises slightly at an unchanged salary, since more income now falls into lower brackets and the general relief is larger.'],note:'',example:'',sourceUrl:'https://www.minimax.si/sl-si/dohodninska-lestvica-2026-kaj-se-spreminja',sourceLabel:'Source: Minimax - Dohodninska lestvica 2026'}},
      {country:'slovenia',flag:'🇸🇮',name:'Slovenia',section:'si-employment-law',title:'Minimum wage rises to €1,481.88',effective:'2026-01-01',added:'2026-09-08',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'Minister Luka Mesec set the minimum wage for work performed from 1 January 2026 at €1,481.88 gross (about €1,000 net). Under the Minimum Wage Act it must equal minimum living costs (newly calculated at €791.07) increased by 20%, plus taxes and employee social contributions, and was adjusted for 2.7% December-on-December price growth.',employer:['Raise any employee paid below €1,481.88 gross to the new minimum for work from January 2026.'],employee:['Minimum-wage workers receive about €1,000 net a month.'],note:'',example:'',sourceUrl:'https://www.gov.si/novice/2026-01-28-dolocen-znesek-minimalne-place-za-2026/',sourceLabel:'Source: GOV.SI - Določen znesek minimalne plače za 2026'}},
      {country:'spain',flag:'🇪🇸',name:'Spain',section:'es-employer-costs',title:'Base máxima €5,101.20; MEI rate 0.90%',effective:'2026-01-01',added:'2026-09-08',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'For 2026 the maximum contribution base (base máxima de cotización) is €5,101.20 a month. The Mecanismo de Equidad Intergeneracional (MEI) contribution from 1 January 2026 is 0.9% of the common-contingencies base, of which 0.75% is paid by the employer and 0.15% by the employee.',employer:['Update payroll with the 2026 base máxima of €5,101.20 and the 0.75% employer MEI share.'],employee:['Employees pay 0.15% MEI on their common-contingencies base.'],note:'',example:'At a €5,101.20 monthly base, MEI is €45.91 (employer €38.26, employee €7.65).',sourceUrl:'https://www.seg-social.es/wps/portal/wss/internet/Trabajadores/CotizacionRecaudacionTrabajadores/36537',sourceLabel:'Source: Seguridad Social - Bases y tipos de cotización 2026'}},
      {country:'spain',flag:'🇪🇸',name:'Spain',section:'es-employment-law',title:'SMI rises 3.1% to €1,221 a month, payable from 1 January 2026',badge:'Effective 1 Jan 2026 (retroactive)',effective:'2026-01-01',added:'2026-09-08',updated:'2026-10-04',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'Royal Decree 126/2026 sets the Spanish minimum wage (SMI) for 2026 at €1,221 a month or €40.70 a day, 3.1% more than in 2025. In annual terms the SMI is never taken as less than €17,094. The decree came into force on 20 February 2026 and the SMI is payable with effect from 1 January 2026.',employer:['Pay at least €1,221 a month (or €40.70 a day, if pay is set by the day) for the full legal working time, and pro rata for shorter hours, with effect from 1 January 2026.','Compare annual pay with the SMI plus the salary supplements named in article 2, never taking less than €17,094. Pay that falls below that annual total must be raised to it (article 3).','Workers hired for up to 120 days by the same employer: minimum €57.82 per working day. Domestic workers paid by the hour: €9.55 per hour worked.'],employee:['Workers paid by the month are entitled to at least €1,221, or at least €40.70 per day if pay is set by the day, with effect from 1 January 2026.','Only pay in money counts towards the SMI; pay in kind cannot reduce the amount due in money.'],note:'',example:'',sourceUrl:'https://www.boe.es/buscar/act.php?id=BOE-A-2026-3815',sourceLabel:'Source: BOE - Real Decreto 126/2026, por el que se fija el salario mínimo interprofesional para 2026'}},
      {country:'spain',flag:'🇪🇸',name:'Spain',section:'es-reporting',title:'TGSS reverses itself: notice-in-lieu pay now subject to social security contributions',badge:'Criterion change: 14 Jul 2026',effective:'2026-07-14',added:'2026-09-08',category:'reporting',impact:'medium',upcoming:false,detail:{lead:'The Tesorería General de la Seguridad Social (TGSS) reversed its own prior criterion: amounts paid to an employee for an employer\'s failure to give notice on an objective dismissal (Article 53 ET) must now be included in the social security contribution base, where they were previously excluded. Employers who paid notice-in-lieu under the old criterion need to file a complementary settlement using CRA code 0054.',employer:['Include notice-in-lieu payments on objective dismissals in the contribution base going forward.','File a complementary settlement (CRA code 0054) for any notice-in-lieu payments made under the old, excluded criterion.'],employee:['Notice-in-lieu payments on an objective dismissal are now included in the social security contribution base.'],note:'',example:'',sourceUrl:'https://www.iberley.es/noticias/bnr-8-2026-cambios-cotizacion-falta-preaviso-despido-objetivo-36754',sourceLabel:'Source: Iberley - BNR 8/2026: cambios en la cotización por falta de preaviso'}},
      {country:'sweden',flag:'🇸🇪',name:'Sweden',section:'se-tax',title:'State tax threshold 643,000 kr; prisbasbelopp 59,200 kr',effective:'2026-01-01',added:'2026-09-08',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'For 2026 the skiktgräns - the taxable income above which the 20% state income tax applies - is 643,000 kr. The brytpunkt is 660,400 kr, or 760,500 kr for those aged 66 and over. The prisbasbelopp is 59,200 kr.',employer:['Confirm payroll software has loaded Skatteverket\'s 2026 skattetabeller before the first January pay run.','No separate action for the skiktgräns increase itself - withholding tables already reflect it.'],employee:['An employee aged 66+ has a higher brytpunkt (760,500 kr vs 660,400 kr).'],note:'',example:'Taxable income of 650,000 kr: 20% state tax on the 7,000 kr above 643,000 kr = 1,400 kr.',sourceUrl:'https://www.skatteverket.se/privat/skatter/beloppochprocent/2026.4.1522bf3f19aea8075ba21.html',sourceLabel:'Source: Skatteverket - Belopp och procent inkomstår 2026'}},
      {country:'sweden',flag:'🇸🇪',name:'Sweden',section:'se-employer-costs',title:'Standard rate holds at 31.42%, with new relief for young and older workers',badge:'Effective through 2026',effective:'2026-01-01',added:'2026-09-08',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'The standard arbetsgivaravgift stays at 31.42% for employees born 1959 or later. From 1 April 2026 to 30 September 2027, a temporary reduced rate of 20.81% applies to employees born 2003–2007, on pay up to 25,000 kr a month. Separately, from 1 January 2026, employers pay only the 10.21% old-age pension contribution - not the full rate - on pay to employees born 1938–1958.',employer:['Flag employees born 2003–2007 in payroll so the reduced 20.81% rate applies correctly on their first 25,000 kr of monthly pay from April 2026.','Apply the 10.21% pension-only rate to employees born 1938–1958.'],employee:['Arbetsgivaravgift is paid entirely by the employer and does not appear on a payslip or reduce net pay - though the youth relief is designed to make employers more willing to hire younger staff.'],note:'',example:'On a 22-year-old employee (born 2004) earning 24,000 kr a month from April 2026, the employer pays 24,000 × 20.81% ≈ 4,994 kr in arbetsgivaravgift instead of the standard 24,000 × 31.42% ≈ 7,541 kr - a saving of roughly 2,547 kr a month on that one employee.',sourceUrl:'https://www.skatteverket.se/foretag/arbetsgivare/arbetsgivaravgifterochskatteavdrag/arbetsgivaravgifter.4.233f91f71260075abe8800020817.html',sourceLabel:'Source: Skatteverket - Arbetsgivaravgifter'}},
      {country:'sweden',flag:'🇸🇪',name:'Sweden',section:'se-benefits',title:'Sick pay and parental pay ceiling rises to 592,000 kr',effective:'2026-01-01',added:'2026-09-08',category:'payroll',impact:'low',upcoming:false,detail:{lead:'The maximum SGI - the income base for sjukpenning (sickness benefit) and föräldrapenning (parental benefit) - is 10 times the prisbasbelopp. With the prisbasbelopp at 59,200 kr in 2026, the maximum SGI is 592,000 kr a year.',employer:['Update any internal top-up scheme that references the SGI ceiling.'],employee:['Sickness and parental benefits are calculated on income capped at 592,000 kr for 2026.'],note:'',example:'',sourceUrl:'https://www.forsakringskassan.se/privatperson/e-tjanster-blanketter-och-informationsmaterial/aktuella-belopp',sourceLabel:'Source: Försäkringskassan - Aktuella belopp'}},
      {country:'sweden',flag:'🇸🇪',name:'Sweden',section:'se-reporting',title:'Växa-stöd becomes a claim-back relief',effective:'2026-01-01',added:'2026-09-08',category:'reporting',impact:'medium',upcoming:false,detail:{lead:'From 1 January 2026 the växa-stöd employer-contribution relief for a business\'s first hires changes from a reduced rate at source to a reimbursement model: employers pay the full arbetsgivaravgift and then request repayment retroactively from Skatteverket.',employer:['If claiming växa-stöd, pay the full arbetsgivaravgift and file a reimbursement request with Skatteverket.'],employee:['No direct impact - this changes employer reporting mechanics, not payslip figures.'],note:'',example:'',sourceUrl:'https://www.grantthornton.se/insikt/tipsochrad/redo-2026-nyheter-att-ha-koll-pa-som-arbetsgivare/',sourceLabel:'Source: Grant Thornton Sweden - Nya regler för arbetsgivare 2026'}},
      {country:'uk',flag:'🇬🇧',name:'United Kingdom',section:'uk-tax',title:'Income tax and NI thresholds frozen until April 2031',badge:'Confirmed for 2026/27',effective:'2026-04-06',added:'2026-09-08',category:'payroll',impact:'low',upcoming:false,detail:{lead:'The Personal Allowance (£12,570) and higher-rate threshold (£50,270) are maintained until April 2031, and the additional-rate threshold stays at £125,140. The NI primary threshold (£12,570), upper earnings limit (£50,270) and employer secondary threshold (£5,000) are also held until April 2031.',employer:['No new threshold changes for 2026/27 - existing PAYE and NI tables carry over.','Employer NI continues to apply above the £5,000 secondary threshold.'],employee:['A pay rise this year pushes proportionally more income into higher tax and NI bands than it would if thresholds moved with inflation - this is the continuing "fiscal drag" effect of the freeze.'],note:'',example:'',sourceUrl:'https://taxscape.deloitte.com/measures-autumn-budget-2025/key-income-tax-and-national-insurance-thresholds-to-remain-frozen.aspx',sourceLabel:'Source: Deloitte Tax Scape - Income tax and NI thresholds frozen'}},
      {country:'uk',flag:'🇬🇧',name:'United Kingdom',section:'uk-employment-law',title:'National Living Wage rises to £12.71 an hour',effective:'2026-04-01',added:'2026-09-08',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'From April 2026 the National Living Wage (age 21+) is £12.71 an hour. The 18-20 rate is £10.85, and the under-18 and apprentice rates are £8.',employer:['Raise any worker paid below the new April 2026 rate for their age band.'],employee:['Workers on the National Living Wage or National Minimum Wage get an automatic increase from the April 2026 pay run.'],note:'',example:'',sourceUrl:'https://www.gov.uk/national-minimum-wage-rates',sourceLabel:'Source: GOV.UK - National Minimum Wage and National Living Wage rates'}},
      {country:'uk',flag:'🇬🇧',name:'United Kingdom',section:'uk-sick-pay',title:'Day-one statutory sick pay and paternity leave; Fair Work Agency established',effective:'2026-04',added:'2026-09-30',category:'payroll',impact:'high',upcoming:false,detail:{lead:'From April 2026, the Employment Rights Act 2025 removes the previous 3-day waiting period for Statutory Sick Pay, making it payable from the first day of absence, and abolishes the Lower Earnings Limit so all employees qualify regardless of how little they earn. Paternity leave also becomes a day-one right. The new Fair Work Agency, consolidating several existing enforcement bodies, is established from the same date.',employer:['Update sick pay policies and payroll rules to pay SSP from day one, not day four, and remove any earnings-based exclusion for low earners.','Confirm paternity leave requests are no longer refused for lack of qualifying service.'],employee:['SSP is now payable from the very first day of illness, and low earners who previously fell below the Lower Earnings Limit now qualify.','Paternity leave can be taken from day one of employment, with no minimum service requirement.'],note:'',example:'',sourceUrl:'https://www.pinsentmasons.com/out-law/guides/employment-rights-bill-timeline-2026-beyond',sourceLabel:'Source: Pinsent Masons - Employment Rights Act implementation timeline'}},
      {country:'uk',flag:'🇬🇧',name:'United Kingdom',section:'uk-benefits',title:'SSP and family statutory pay rates uprated',effective:'2026-04',added:'2026-09-08',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'The weekly rate of Statutory Sick Pay rises from £118.75 to £123.25. Statutory maternity, paternity, shared parental, adoption, parental bereavement and neonatal care pay rise from £187.18 to £194.32 a week.',employer:['Update payroll software with the new SSP and family statutory pay rates for April 2026.'],employee:['Anyone on statutory sick pay or statutory family pay from April 2026 receives the higher weekly rate automatically.'],note:'',example:'',sourceUrl:'https://acuitylaw.com/updated-statutory-sick-pay-and-parental-pay-rates-from-april-2026/',sourceLabel:'Source: Acuity Law - Updated statutory sick pay and parental pay rates'}},
      {country:'uk',flag:'🇬🇧',name:'United Kingdom',section:'uk-upcoming',title:'Unfair dismissal qualifying period cut to six months',effective:'2027-01',added:'2026-09-08',category:'payroll',impact:'low',upcoming:true,detail:{lead:'Under the Employment Rights Act timetable, the unfair dismissal qualifying period is reduced to six months, and the cap on the compensatory award is removed, from January 2027. The reduced qualifying period applies to dismissals taking place from that date.',employer:['Review probationary and early-termination processes now - a much larger share of the workforce will gain unfair dismissal rights after six months\' service.','Note the date applies to when a dismissal happens, not when someone started - an employee hired in 2026 could already be covered by January 2027.'],employee:['Unfair dismissal protection will apply after six months of service for dismissals from January 2027.'],note:'',example:'',sourceUrl:'https://www.davidsonmorris.com/employment-rights-act-timeline/',sourceLabel:'Source: Davidson Morris - Employment Rights Act timeline'}},
      {country:'uk',flag:'🇬🇧',name:'United Kingdom',section:'uk-reporting-upcoming',title:'Mandatory payrolling of benefits in kind, phased from April 2027',badge:'Phase 1: 6 Apr 2027',effective:'2027-04-06',added:'2026-09-08',category:'reporting',impact:'high',upcoming:true,detail:{lead:'Payrolling of benefits in kind becomes mandatory in phases. From 6 April 2027 the most common benefits - company cars, car and van fuel, vans and medical benefit - must be reported and taxed in real time through RTI payroll software. From 6 April 2028 most remaining benefits in kind are mandated, except employer-provided loans and accommodation.',employer:['Do not treat benefits-in-kind payrolling as mandatory yet - continue filing P11D/P11D(b) as normal until Phase 1 takes effect in April 2027.','If providing company cars, fuel, vans, or medical benefits, start planning payroll software changes ahead of the April 2027 Phase 1 date.'],employee:['None yet - benefit-in-kind tax continues to be handled via the annual P11D process until the phased rollout begins.'],note:'',example:'',sourceUrl:'https://www.gov.uk/government/publications/changes-to-reporting-of-benefits-in-kind-from-april-2027/mandatory-reporting-of-benefits-in-kind-in-real-time-information-rti-from-april-2027',sourceLabel:'Source: GOV.UK - Mandatory payrolling of benefits in kind from April 2027'}},
      {country:'austria',flag:'🇦🇹',name:'Austria',section:'at-tax',title:'Tariff brackets indexed by two-thirds of inflation',effective:'2026-01-01',added:'2026-09-08',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'The Inflationsanpassungsverordnung 2026, published on 30 August 2025 (BGBl. II Nr. 191/2025), raises the inflation-linked income-tax thresholds and deduction amounts by 1.733% - two-thirds of the inflation rate. Income up to €13,539 is now taxed at 0% (previously €13,308), and the 50% rate now applies above €104,859 (previously €103,072).',employer:['Confirm payroll software has loaded the 2026 Lohnsteuer tariff stages before the first January pay run.','No separate filing is needed - the indexed brackets apply automatically via the standard payroll calculation.'],employee:['Only two-thirds of inflation is offset by the indexation, leaving some residual cold progression on an inflation-matching pay rise.'],note:'',example:'',sourceUrl:'https://www.ey.com/de_at/technical/steuernachrichten/inflationsanpassungsverordnung-2026',sourceLabel:'Source: EY Austria - Inflationsanpassungsverordnung 2026'}},
      {country:'austria',flag:'🇦🇹',name:'Austria',section:'at-employer-costs',title:'Höchstbeitragsgrundlage rises to €6,930 a month',effective:'2026',added:'2026-09-08',updated:'2026-10-03',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'The official 2026 ASVG maximum contribution base (Höchstbeitragsgrundlage) is €6,930 gross a month (€231 a day).',employer:['Update the contribution ceiling in payroll software for 2026.'],employee:['Income above the Höchstbeitragsgrundlage is not subject to further social insurance contributions.'],note:'',example:'',sourceUrl:'https://www.oesterreich.gv.at/de/lexicon/H/Seite.991498',sourceLabel:'Source: oesterreich.gv.at - Höchstbeitragsgrundlage'}},
      {country:'austria',flag:'🇦🇹',name:'Austria',section:'at-employment-law',title:'Gewerbe, Handwerk und Dienstleistung minimums rise 2.70%',effective:'2026-01-01',added:'2026-09-08',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'Under the 2026 collective agreement for trade, craft and services (Gewerbe, Handwerk und Dienstleistung), monthly minimum basic salaries rise by 2.70% in all employment groups from 1 January 2026, and apprentice pay rises 3.0% in all four apprenticeship years. Other sectors have their own Kollektivvertrag increases.',employer:['Apply the specific sector Kollektivvertrag increase relevant to the business - there is no single national minimum wage.','An increase in the agreed minimum automatically affects only staff paid at the old minimum; above-minimum pay depends on the agreement\'s own terms.'],employee:['Employees paid at the collectively agreed minimum in this sector receive a 2.70% increase from January 2026.'],note:'',example:'',sourceUrl:'https://www.wko.at/kollektivvertrag/kollektivvertrag-gewerbe-handwerk-und-dienstleistung-2026',sourceLabel:'Source: WKO - Kollektivvertrag Gewerbe, Handwerk und Dienstleistung 2026'}},
      {country:'austria',flag:'🇦🇹',name:'Austria',section:'at-reporting',title:'Working hours mandatory on social insurance registration',effective:'2026-01-01',added:'2026-09-08',category:'reporting',impact:'medium',upcoming:false,detail:{lead:'From 1 January 2026, employers must always state working hours when registering an employee with social insurance, and must report all relevant changes - such as working hours, pay or contract terms - immediately as part of their ongoing ELDA reports.',employer:['Capture and submit working hours at the point of social insurance registration.','Build a process to report changes to hours, pay or contract terms via ELDA as they occur.'],employee:['Contract changes are documented more clearly in social insurance records.'],note:'',example:'',sourceUrl:'https://www.remm-steuerberatung.at/news/angabe-der-arbeitszeit-bei-anmeldung-zur-sozialversicherung-ab-01-01-26-verpflichtend',sourceLabel:'Source: Remm Steuerberatung - Angabe der Arbeitszeit bei Anmeldung ab 1.1.2026'}},
{country:'belgium',flag:'🇧🇪',name:'Belgium',section:'be-employment-law',title:'GMMI indexed to €2,233.61 from 1 July 2026',effective:'2026-07-01',added:'2026-09-08',updated:'2026-10-04',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'On 1 July 2026 the guaranteed average minimum monthly income (GMMI) is indexed after the pivot index was exceeded at the end of June 2026, raising it from €2,189.81 (base amount from 1 April 2026) to €2,233.61 a month for workers aged 18 and over.',employer:['Raise any employee aged 18+ paid at or near the GMMI to at least €2,233.61 a month from 1 July 2026, and correct the July 2026 pay run if it was processed at the old amount.'],employee:['Workers on or near the guaranteed minimum get a further increase from 1 July 2026.'],note:'The 1 April 2026 step added €35 (non-indexed) to reach €2,189.81; the 1 July 2026 indexation brings it to €2,233.61 (CAO no. 43/18).',example:'',sourceUrl:'https://cnt-nar.be/sites/default/files/documents/fr/Tableau-Tabel-Montants%20CCT-CAO%20Bedragen-2026-07-01.pdf',sourceLabel:'Source: Nationale Arbeidsraad (NAR) - Tabel cao-bedragen bijgewerkt op 01.07.2026 (cao nr. 43/18)'}},
      {country:'belgium',flag:'🇧🇪',name:'Belgium',section:'be-reporting-upcoming',title:'"Loon-datatransfer" tool to replace DmfA',badge:'Voluntary from 2027',effective:'2027-01-01',added:'2026-09-08',category:'reporting',impact:'high',upcoming:true,detail:{lead:'As part of RSZ\'s e-gov modernisation, a new "loon-datatransfer" (wage data transfer) tool will be available for voluntary use and testing from 1 January 2027, become mandatory from 1 January 2028, and the DmfA submission itself will be abolished from 1 January 2030. RSZ began sending informational letters to employers about the transition from 28 May 2026.',employer:['Watch for RSZ\'s informational letters and confirm payroll software providers have a roadmap for the new tool well before the 2028 mandatory date.','Consider voluntary testing from 2027 rather than waiting for the 2028 deadline, given a full DmfA phase-out follows in 2030.'],employee:['None - this replaces the technical reporting channel between employer and RSZ, not payslip content.'],note:'',example:'',sourceUrl:'https://www.unizo.be/berichten/nieuws/informatiebrieven-rsz',sourceLabel:'Source: UNIZO - Nieuwe tool voor loon- en arbeidstijdgegevens'}},
      {country:'belgium',flag:'🇧🇪',name:'Belgium',section:'be-pay-transparency',title:'EU Pay Transparency Directive - Belgium misses 7 June 2026 deadline',badge:'Transposition delayed',effective:null,added:'2026-09-30',category:'reporting',impact:'high',upcoming:true,draft:true,detail:{lead:'Directive (EU) 2023/970 had to be transposed by 7 June 2026, and Belgium will not meet that deadline. The government has asked the European Commission not to open infringement proceedings for late transposition for six months.',employer:['Start building job-level pay-band documentation now - this groundwork is needed regardless of when the Belgian law lands.'],employee:['Specific national rights depend on the Belgian transposition law, which is not yet adopted.'],note:'',example:'',sourceUrl:'https://www.vbo-feb.be/nl/nieuws/faq-omzetting-loontransparantierichtlijn-uitgesteld-wat-nu/',sourceLabel:'Source: VBO FEB - FAQ omzetting loontransparantierichtlijn uitgesteld'}},
      {country:'bulgaria',flag:'🇧🇬',name:'Bulgaria',section:'bg-employment-law',title:'Minimum wage rises 12.6% to EUR 620.20',effective:'2026-01-01',added:'2026-09-08',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'The Council of Ministers set the minimum monthly wage at BGN 1,213 (EUR 620.20) from 1 January 2026, an increase of BGN 136 (12.6%). The minimum hourly wage is BGN 7.31 (EUR 3.74).',employer:['Raise any employee paid below EUR 620.20 a month (EUR 3.74 an hour) from the January 2026 pay run, and re-check minimum-wage-linked allowances.'],employee:['Workers on the minimum wage get a 12.6% increase from January 2026.'],note:'',example:'',sourceUrl:'https://www.bta.bg/en/news/bulgaria/1007805?download=1',sourceLabel:'Source: BTA - Cabinet Raises Minimum Wage by 12.6% to EUR 620.20 from January 1, 2026'}},
      {country:'bulgaria',flag:'🇧🇬',name:'Bulgaria',section:'bg-social-security',title:'Maximum insurable income rises to EUR 2,300; civil servants pay own contributions',effective:'2026-08-01',added:'2026-09-30',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'Under the 2026 State Social Insurance Budget Act, the maximum insurable income rose to EUR 2,300 and the minimum insurable income for self-employed persons to EUR 620.20 from 1 August 2026. From the same date, civil servants under the Civil Servants Act and employees under the Judiciary Act pay personal social security contributions under an 80:20 employer-to-employee ratio, changing to 60:40 from 1 January 2027.',employer:['Apply the EUR 2,300 maximum insurable income from the August 2026 payroll.','Public-sector employers: withhold the employee share for civil servants and judiciary staff (80:20 in 2026, 60:40 from 2027).'],employee:['Civil servants and judiciary staff see a personal social security deduction from August 2026.'],note:'',example:'',sourceUrl:'https://www.bta.bg/en/news/bulgaria/1177740-social-security-income-thresholds-increase-from-august-1-civil-servants-pay-own',sourceLabel:'Source: BTA - Social Security Income Thresholds Increase from August 1'}},
      {country:'croatia',flag:'🇭🇷',name:'Croatia',section:'hr-tax',title:'Municipality-set income tax rates published for 2026',effective:'2026-01-01',added:'2026-09-08',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'Income tax rates are set by each local government unit by decision, within limits in the Income Tax Act, published in Narodne novine and taking effect on 1 January of the following year. Porezna uprava published the updated table of 2026 rates, based on decisions published by 15 December, on 16 December 2025.',employer:['Apply the 2026 rate for each employee\'s municipality of residence from the Porezna uprava table - rates vary by location.'],employee:['Two employees on identical salaries in different municipalities can see different net pay.'],note:'',example:'',sourceUrl:'https://porezna-uprava.gov.hr/hr/stope-godisnjeg-poreza-na-dohodak-za-2026-godinu/8166',sourceLabel:'Source: Porezna uprava - Stope godišnjeg poreza na dohodak za 2026. godinu'}},
      {country:'croatia',flag:'🇭🇷',name:'Croatia',section:'hr-employment-law',title:'Minimum wage rises to €1,050, with state covering the difference for three months',effective:'2026-01-01',added:'2026-09-08',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'The Government set the gross minimum wage for 2026 at €1,050 a month, up from the current €970. Employers paying the minimum wage can receive the difference between €970 and €1,050 from the state for the first three months.',employer:['Raise any employee paid below €1,050 gross from the January 2026 pay run.','Check eligibility for the compensation covering the €970 to €1,050 difference for the first three months.'],employee:['Workers on the minimum wage get an €80 monthly increase from January 2026.'],note:'',example:'€1,050 - €970 = €80 a month per minimum-wage worker.',sourceUrl:'https://vlada.gov.hr/minimalna-bruto-placa-za-iducu-godinu-1-050-eura-uz-kompenzacijske-mjere-za-poslodavce/45248',sourceLabel:'Source: Vlada Republike Hrvatske - Minimalna bruto plaća za iduću godinu 1.050 eura'}},
      {country:'croatia',flag:'🇭🇷',name:'Croatia',section:'hr-reporting',title:'JOPPD form updated with new tax-exempt income codes',effective:'2026-01-01',added:'2026-09-08',category:'reporting',impact:'medium',upcoming:false,detail:{lead:'From 1 January 2026, a new version of the JOPPD form applies, adding new codes for tax-exempt receipts in field 15.1. The new version of the ePorezna support software is 1.0.40.',employer:['Update JOPPD-filing software to version 1.0.40 before filing 2026 reports.'],employee:['No direct impact - this is a technical update to employer reporting.'],note:'',example:'',sourceUrl:'https://porezna-uprava.gov.hr/hr/azuriranje-joppd-obrasca-u-sustavu-eporezna/8249',sourceLabel:'Source: Porezna uprava - Ažuriranje JOPPD obrasca u sustavu ePorezna'}},
      {country:'cyprus',flag:'🇨🇾',name:'Cyprus',section:'cy-tax',title:'Tax-free threshold rises to €22,000 under 2026 tax reform',effective:'2026-01-01',added:'2026-09-08',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'As of 1 January 2026, new personal income tax bands apply: 0% up to €22,000 (previously €19,500), 20% on €22,001-€32,000, 25% on €32,001-€42,000, 30% on €42,001-€72,000 and 35% above €72,000.',employer:['Load the 2026 PAYE bands into payroll software from the January 2026 pay run.'],employee:['Most employees see lower tax withholding from 2026 because of the higher tax-free threshold.'],note:'',example:'',sourceUrl:'https://taxsummaries.pwc.com/cyprus/individual/taxes-on-personal-income',sourceLabel:'Source: PwC Worldwide Tax Summaries - Cyprus, Taxes on personal income'}},
      {country:'cyprus',flag:'🇨🇾',name:'Cyprus',section:'cy-employment-law',title:'Minimum wage rises to €979 on hire and €1,088 after six months',effective:'2026-01-01',added:'2026-09-08',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'From 1 January 2026, the national minimum wage rises to €979 gross a month upon recruitment (from €900) and €1,088 gross after six months of continuous employment with the same employer (from €1,000).',employer:['Raise new hires to at least €979/month, and employees past six months\' continuous service to at least €1,088/month, from January 2026.'],employee:['The minimum rises by €79 on hire and €88 after six months.'],note:'',example:'',sourceUrl:'https://www.rsm.global/cyprus/insights/economic-and-corporate-insights/cyprus-minimum-wage-2026-new-rates-increases',sourceLabel:'Source: RSM Cyprus - Cyprus minimum wage 2026: new rates and increases'}},
      {country:'czechia',flag:'🇨🇿',name:'Czech Republic',section:'cz-employment-law',title:'Minimum wage rises to 22,400 Kč',effective:'2026-01-01',added:'2026-09-08',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'From 1 January to 31 December 2026, the minimum wage for a 40-hour working week is 22,400 Kč a month or 134.40 Kč an hour (MPSV communication No. 356/2025 Sb.). For shorter agreed hours it is pro-rated, e.g. 11,200 Kč a month for 20 hours a week.',employer:['Raise any employee below 22,400 Kč (134.40 Kč/hour, pro-rated for part-time) from the January 2026 pay run.'],employee:['Minimum-wage workers get a higher floor from January 2026.'],note:'',example:'',sourceUrl:'https://mpsv.gov.cz/minimalni-mzda',sourceLabel:'Source: MPSV - Minimální mzda'}},
      {country:'czechia',flag:'🇨🇿',name:'Czech Republic',section:'cz-wages-in-money',title:'Benefits that replace part of the wage lose their tax exemption',effective:'2026',added:'2026-09-30',updated:'2026-10-03',category:'payroll',impact:'high',upcoming:false,detail:{lead:'From 2026 leisure and health non-cash benefits stay tax-exempt only when they are given on top of the agreed wage. Benefits that replace part of the salary lose the exemption and are taxed as employment income.',employer:['Review pay packages where benefits replace part of the agreed wage: those benefits must be taxed as employment income.'],employee:['Benefits given in place of part of your salary are taxed like salary; benefits on top of your wage can stay tax-exempt.'],note:'',example:'',sourceUrl:'https://www.expats.cz/czech-news/article/vialto-partners-prague-how-czechia-s-2026-tax-laws-and-changes-will-hit-employees-and-companies',sourceLabel:'Source: Expats.cz - How Czechia\'s 2026 tax laws and changes will hit employees and companies'}},
      {country:'czechia',flag:'🇨🇿',name:'Czech Republic',section:'cz-benefits',title:'Sickness benefit reduction thresholds raised for 2026',effective:'2026-01-01',added:'2026-09-08',category:'payroll',impact:'low',upcoming:false,detail:{lead:'ČSSZ states that the reduction thresholds for the daily assessment base used for sickness insurance benefits rise in 2026: 1,633 Kč (counted at 90%), 2,449 Kč (60%) and 4,897 Kč (30%).',employer:['Use the 2026 thresholds when calculating wage compensation (náhrada mzdy) and sickness benefits.'],employee:['Sickness benefits for higher earners are calculated from higher thresholds.'],note:'',example:'',sourceUrl:'https://www.cssz.gov.cz/-/prehled-nejdulezitejsich-udaju-pro-socialni-zabezpeceni-v-roce-2026',sourceLabel:'Source: ČSSZ - Přehled nejdůležitějších údajů pro sociální zabezpečení v roce 2026'}},
      {country:'czechia',flag:'🇨🇿',name:'Czech Republic',section:'cz-reporting',title:'Jednotné měsíční hlášení zaměstnavatele (JMHZ) introduced',badge:'Phased from 1 Jan 2026',effective:'2026-01-01',added:'2026-09-08',category:'reporting',impact:'high',upcoming:false,detail:{lead:'Act No. 323/2025 Sb. on the single monthly employer report (JMHZ) took effect on 1 January 2026. It lets employers meet their reporting and record-keeping duties to several state authorities through one electronic submission. Employer obligations take effect in three main phases: 1 January 2026, 1 April 2026 and 1 July 2026.',employer:['Confirm payroll software supports JMHZ submissions and the obligations applying in each phase.'],employee:['No direct payslip impact.'],note:'',example:'',sourceUrl:'https://www.cssz.gov.cz/web/cz/co-je-jmhz-',sourceLabel:'Source: ČSSZ - Co je JMHZ'}},
      {country:'czechia',flag:'🇨🇿',name:'Czech Republic',section:'cz-reporting-upcoming',title:'EU Pay Transparency Directive - phased Labour Code amendment',badge:'Mostly from 1 Jan 2027',effective:'2027-01-01',added:'2026-09-08',category:'reporting',impact:'high',upcoming:true,draft:true,detail:{lead:'The draft amendment to the Labour Code, published on 27 March 2026, transposing the directive foresees phased entry into force: most provisions are expected to take effect from 1 January 2027, while regular pay-gap reporting, the related pay assessment and corrective measures, and employees\' right to request written pay information are expected from 1 January 2028.',employer:['Prepare objective pay structures for the 2027 core obligations, and pay-gap data for 2028 reporting.'],employee:['Right to request written information on own pay expected from 2028.'],note:'',example:'',sourceUrl:'https://www.ey.com/cs_cz/technical/tax/tax-alerts/2026/03/transparentnost-odmenovani-1-cast-novela-zakoniku-prace-zverejnena',sourceLabel:'Source: EY Czech Republic - Transparentnost odměňování, 1. část'}},
      {country:'denmark',flag:'🇩🇰',name:'Denmark',section:'dk-tax',title:'Topskat renamed mellemskat; new topskat and toptopskat added',effective:'2026-01-01',added:'2026-09-08',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'A tax reform introduces two new taxes from 2026 - topskat and toptopskat - and the former topskat is renamed mellemskat. For 2026: 7.5% mellemskat on personal income over 641,200 kr after AM-bidrag, 7.5% topskat over 777,900 kr, and 5% toptopskat over 2,592,700 kr.',employer:['Confirm payroll software applies the new three-tier structure in 2026 withholding.'],employee:['Income above 777,900 kr after AM-bidrag bears both mellemskat and topskat; above 2,592,700 kr, toptopskat applies as well.'],note:'',example:'',sourceUrl:'https://skat.dk/hjaelp/bundskat-mellemskat-topskat-og-toptopskat',sourceLabel:'Source: Skattestyrelsen - Bundskat, mellemskat, topskat og toptopskat'}},
      {country:'denmark',flag:'🇩🇰',name:'Denmark',section:'dk-employment-law',title:'Barsel rights strengthened for the self-employed',effective:'2026-01',added:'2026-09-08',category:'payroll',impact:'low',upcoming:false,detail:{lead:'Amendments to barselsloven passed by the Folketing on 29 April 2025 take effect in January 2026, letting self-employed people base their barselsdagpenge (parental leave benefit) on income from up to five years before starting their business, and allowing up to 3.5 hours of light administrative work per week during leave without losing the full benefit.',employer:['Mainly relevant to HR teams managing contractors or owner-directors - confirm any self-employed associate on leave understands the new 3.5-hour weekly work allowance.'],employee:['Barselsdagpenge can now be calculated from pre-business income up to five years back, helping newer founders qualify for a realistic benefit level.','Up to 3.5 hours a week of light business admin is now allowed during leave without forfeiting full barselsdagpenge.'],note:'',example:'',sourceUrl:'https://les.dk/da/news/nye-barselsregler-styrker-vilkaarene-selvstaendige-fra-2026',sourceLabel:'Source: Lund Elmer Sandager - Nye barselsregler for selvstændige fra 2026'}},
      {country:'estonia',flag:'🇪🇪',name:'Estonia',section:'ee-tax',title:'Uniform €700 monthly tax-free income for everyone',effective:'2026-01-01',added:'2026-09-08',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'The sliding "maksuküür" system is replaced by a uniform tax-free income of €700 a month (€8,400 a year) for everyone from 2026, one year later than originally planned. A separate rate applies to the tax-free income of people of retirement age.',employer:['Apply the flat €700 monthly tax-free amount from January 2026 payroll.'],employee:['Higher earners, who previously lost some or all tax-free income, now receive the full €700 a month.'],note:'',example:'',sourceUrl:'https://www.fin.ee/uudised/maksukuur-kaob-2026-aastal',sourceLabel:'Source: Rahandusministeerium - Maksuküür kaob 2026. aastal'}},
      {country:'estonia',flag:'🇪🇪',name:'Estonia',section:'ee-employment-law',title:'Minimum wage rises €60 to €946, effective from April',effective:'2026-04-01',added:'2026-09-08',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'The Government set the 2026 minimum wage (töötasu alammäär) at €946 a month and €5.67 an hour, raising it by €60 from 1 April 2026, as agreed in a collective agreement between the Estonian Trade Union Confederation and the Estonian Employers\' Confederation. The Ministry of Finance estimates about €9.7 million in additional 2026 tax revenue.',employer:['Raise any employee paid below €946/month (€5.67/hour) from the April 2026 pay run.'],employee:['Minimum-wage workers get a €60 monthly increase from April 2026.'],note:'',example:'€946 - €60 = €886, the previous monthly minimum.',sourceUrl:'https://www.mkm.ee/uudised/tootasu-alammaar-touseb-aprillist-946-euroni',sourceLabel:'Source: Majandus- ja Kommunikatsiooniministeerium - Töötasu alammäär tõuseb aprillist 946 euroni'}},
      {country:'estonia',flag:'🇪🇪',name:'Estonia',section:'ee-reporting-upcoming',title:'Data-based TSD replaces the tax declaration form',effective:'2027-04-01',added:'2026-09-08',category:'reporting',impact:'high',upcoming:true,detail:{lead:'The Tax and Customs Board (MTA) is moving to data-based reporting: the accountant will send transaction data to the tax authority, which calculates the taxes itself. MTA confirmed the new system takes effect on 1 April 2027.',employer:['Check with accounting and payroll software providers about readiness for data-based submission before April 2027.'],employee:['No direct impact on pay.'],note:'',example:'',sourceUrl:'https://www.raamatupidaja.ee/uudised/2025/01/20/mta-plaanib-raamatupidamiskirjendite-pohise-tsd-kasutuselevottu-2026-aasta-lopus',sourceLabel:'Source: Raamatupidaja.ee - Maksuamet muudab TSD süsteemi'}},
      {country:'estonia',flag:'🇪🇪',name:'Estonia',section:'ee-pay-transparency',title:'Pay Transparency Directive - recruitment rules being transposed, reporting postponed',badge:'Upcoming - transposition in progress',effective:null,added:'2026-09-30',category:'reporting',impact:'high',upcoming:true,draft:true,detail:{lead:'Estonia is transposing the directive\'s recruitment-related rules: pay or a pay range must be disclosed before the job interview, candidates may not be asked about previous pay, and employers may not prevent employees from discussing their pay. The more demanding obligations - structured pay systems and regular reporting by larger employers - are being delayed while Estonia seeks simplification.',employer:['State pay or a pay range in recruitment before interviews and remove salary-history questions.'],employee:['Candidates can see the offered pay range and cannot be asked about previous pay.'],note:'',example:'',sourceUrl:'https://mkm.ee/uudised/kkk-euroopa-liidu-palkade-labipaistvuse-direktiiv-ja-selle-rakendamine-eestis',sourceLabel:'Source: Majandus- ja Kommunikatsiooniministeerium - KKK: palkade läbipaistvuse direktiiv'}},
      {country:'estonia',flag:'🇪🇪',name:'Estonia',section:'ee-social-tax-minimum',title:'Minimum monthly social tax base rises to €886 for 2026',effective:'2026-01-01',added:'2026-10-06',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'For 2026 the Tax and Customs Board states that the minimum monthly social tax obligation is based on €886 (up from €820 in 2025), so the minimum social tax is €292.38 per month at the 33% rate.',employer:['Pay at least €292.38 of social tax per month for each employee in 2026, even if the wage paid is below €886.','Keep the 33% social tax rate and 1.6%/0.8% unemployment insurance rates for 2026 payroll (unchanged from 2025).'],employee:['No deduction from net pay; the minimum applies to the employer\'s social tax.'],note:'Taxation is cash-based: December 2025 wages paid in January 2026 are taxed at 2026 rates and declared on the January TSD.',example:'€886 x 33% = €292.38 minimum social tax per month.',sourceUrl:'https://www.emta.ee/en/private-client/taxes-and-payment/declaration-income/tax-rates',sourceLabel:'Source: Tax and Customs Board (EMTA) - Tax rates'}},
      {country:'estonia',flag:'🇪🇪',name:'Estonia',section:'ee-funded-pension-rate',title:'Second-pillar pension contribution of 2%, 4% or 6% applies from 2025',effective:'2025-01-01',added:'2026-10-06',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'Since 1 January 2025 employees in the funded pension (II pillar) can choose a contribution rate of 2%, 4% or 6%; the default stays 2% unless the person applies to the registrar for a higher rate. The employer withholds whatever rate the Funded Pension Registry shows.',employer:['Withhold the 2%, 4% or 6% funded pension contribution according to the Funded Pension Registry data for each employee.','Check the withholding obligation before payroll in December, April and August, since it can change on 1 January, 1 May and 1 September.'],employee:['Apply to the registrar by 30 November for a higher rate to apply from 1 January; the rate can be changed once a year.'],note:'EMTA recommends accountants use the registry\'s subscription query by personal identification code.',example:'',sourceUrl:'https://www.emta.ee/en/private-client/taxes-and-payment/declaration-income/tax-rates',sourceLabel:'Source: Tax and Customs Board (EMTA) - Tax rates'}},
      {country:'au',flag:'🇦🇺',name:'Australia',section:'au-sg-12',title:'Superannuation guarantee rate reaches 12%',effective:'2025-07-01',added:'2026-09-30',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'The superannuation guarantee (SG) percentage employers must contribute permanently increased to 12% from 1 July 2025.',employer:['Calculate SG contributions at 12% of ordinary time earnings for pay periods from 1 July 2025.'],employee:['Employer super contributions on your earnings are made at 12%.'],note:'',example:'An employee with AUD 1,000 of ordinary time earnings attracts AUD 120 of SG contributions (1,000 x 12%).',sourceUrl:'https://taxsummaries.pwc.com/australia/individual/other-taxes',sourceLabel:'Source: PwC Worldwide Tax Summaries - Australia, Individual - Other taxes'}},
      {country:'au',flag:'🇦🇺',name:'Australia',section:'au-payday-super',title:'Payday Super: SG contributions must reach funds within seven business days of payday',effective:'2026-07-01',added:'2026-09-30',category:'reporting',impact:'high',upcoming:false,detail:{lead:'From 1 July 2026 employers must ensure superannuation guarantee contributions reach employees\' funds within seven business days of payday.',employer:['Pay super with each pay run so funds receive it within seven business days of payday.','Late contributions expose the employer to the superannuation guarantee charge.'],employee:['Super contributions arrive in your fund in line with each payday.'],note:'Replaces the quarterly SG contribution system.',example:'',sourceUrl:'https://kpmg.com/xx/en/our-insights/gms-flash-alert/flash-alert-2025-268.html',sourceLabel:'Source: KPMG - Australia: Payday Superannuation legislation receives Royal Assent'}},
      {country:'id',flag:'🇮🇩',name:'Indonesia',section:'id-pph21-dtp',title:'Government-borne PPh 21 (DTP) extended to 2026 for employees earning up to IDR 10 million a month',effective:'2026-01',added:'2026-09-30',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'PMK-105, applicable from 31 December 2025, extends the Article 21 income tax borne by government (PPh 21 DTP) facility, first set by PMK-10 of 4 February 2025, to the January-December 2026 tax periods for employees in the footwear, textile and apparel, furniture, leather goods and tourism sectors.',employer:['Check the entity\'s KLU code registered in Coretax falls within an eligible sector.','Apply the facility to permanent employees with fixed and regular gross income not exceeding IDR 10 million per month, and non-permanent employees up to IDR 500,000 per day or IDR 10 million per month.','Pay the PPh 21 DTP amount in cash to the employee at the time of salary payment.'],employee:['Eligible employees receive the Article 21 tax amount in cash with their salary; any excess over annual tax payable is not refunded.'],note:'',example:'',sourceUrl:'https://www.rsm.global/indonesia/en/node/414',sourceLabel:'Source: RSM Indonesia - Client Alert 21 January 2026'}},
      {country:'in',flag:'🇮🇳',name:'India',section:'in-new-regime-2025',title:'New tax regime slabs revised; full rebate up to INR 12 lakh',badge:'FY 2025-26',effective:'2025-04-01',added:'2026-09-30',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'Under the alternate (new) personal tax regime, income up to INR 400,000 is taxed at 0%, rising through 5%, 10%, 15%, 20% and 25% bands to 30% above INR 2,400,000, and residents with total income not exceeding INR 1,200,000 receive a rebate of the lower of the tax or INR 60,000.',employer:['Compute TDS on salary for employees in the new regime using the revised slabs and the INR 60,000 rebate.'],employee:['Resident employees in the new regime with total income up to INR 12 lakh pay no income tax.'],note:'',example:'',sourceUrl:'https://taxsummaries.pwc.com/india/individual/taxes-on-personal-income',sourceLabel:'Source: PwC Worldwide Tax Summaries - India, Individual - Taxes on personal income'}},
      {country:'jp',flag:'🇯🇵',name:'Japan',section:'jp-unemployment-ins',title:'Employee unemployment insurance rate cut to 0.5%',effective:'2026-04',added:'2026-09-30',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'The fixed employee rate of unemployment insurance is 0.5% (previously 0.55%) from April 2026.',employer:['Update employee unemployment insurance withholding to 0.5% from April 2026 payroll.'],employee:['Unemployment insurance deduction falls from 0.55% to 0.5% of wages.'],note:'',example:'On monthly wages of JPY 400,000 the deduction falls from JPY 2,200 to JPY 2,000.',sourceUrl:'https://taxsummaries.pwc.com/japan/individual/other-taxes',sourceLabel:'Source: PwC Worldwide Tax Summaries - Japan, Individual - Other taxes'}},
      {country:'jp',flag:'🇯🇵',name:'Japan',section:'jp-child-support-levy',title:'Child and childcare support contribution added to health insurance premiums',effective:'2026-04',added:'2026-09-30',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'From April 2026 a child and childcare support contribution is introduced as an addition to health insurance; the employee share is 0.115% on a maximum of JPY 1.39 million of wages per month.',employer:['Add the child and childcare support contribution to health insurance deductions from April 2026.'],employee:['A new 0.115% deduction applies alongside health insurance, capped at JPY 1.39 million of monthly wages.'],note:'',example:'On monthly wages of JPY 400,000 the employee deduction is JPY 460.',sourceUrl:'https://taxsummaries.pwc.com/japan/individual/other-taxes',sourceLabel:'Source: PwC Worldwide Tax Summaries - Japan, Individual - Other taxes'}},
      {country:'kr',flag:'🇰🇷',name:'South Korea',section:'kr-np-9-5',title:'National Pension contribution rate rises from 9% to 9.5%',effective:'2026-01-01',added:'2026-09-30',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'The National Pension contribution rate rose from 9% to 9.5% on 1 January 2026, the first change since 1998, and will rise by 0.5 percentage points a year until reaching 13% in 2033.',employer:['Contribute 4.75% and withhold 4.75% from workplace subscribers from January 2026.','Plan for further 0.5-point annual increases through 2033.'],employee:['Pension deduction is 4.75% of salary in 2026.'],note:'',example:'On monthly salary of KRW 3,000,000 each side pays KRW 142,500 (4.75%).',sourceUrl:'https://gonggam.korea.kr/newsContentView.es?mid=a10214000000&section_id=&news_id=1dacfb8c-1c5e-4e2c-a283-2e42e0e678a5',sourceLabel:'Source: Korea.kr (K-Gonggam, Government of Korea) - National Pension rate rises to 9.5% from 2026'}},
      {country:'kr',flag:'🇰🇷',name:'South Korea',section:'kr-nhi-2026',title:'National Health Insurance premium including long-term care about 8.135%',effective:'2026-01-01',added:'2026-09-30',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'As of 1 January 2026 the National Health Insurance premium rate including long-term care insurance is approximately 8.135% of monthly wages, split equally at about 4.0674% each, with total monthly contribution capped at KRW 10,390,220.',employer:['Apply the 2026 NHI and long-term care rates to payroll from January 2026.'],employee:['Employee share is approximately 4.0674% of monthly wages.'],note:'',example:'',sourceUrl:'https://taxsummaries.pwc.com/republic-of-korea/individual/other-taxes',sourceLabel:'Source: PwC Worldwide Tax Summaries - Republic of Korea, Individual - Other taxes'}},
      {country:'my',flag:'🇲🇾',name:'Malaysia',section:'my-min-wage-1700',title:'Minimum wage raised to RM1,700 a month',effective:'2025-02-01',added:'2026-09-30',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'Malaysia raised the minimum wage from RM1,500 to RM1,700 per month (RM8.72 per hour), effective 1 February 2025 for employers with five or more employees and 1 August 2025 for employers with fewer than five.',employer:['Pay at least RM1,700 per month or RM8.72 per hour.','Employers with fewer than five employees must comply from 1 August 2025.'],employee:['Minimum monthly pay rises by RM200.'],note:'Domestic workers are excluded.',example:'',sourceUrl:'https://www.aseanbriefing.com/news/malaysias-new-minimum-wage-rate-for-2025-what-employers-and-workers-need-to-know/',sourceLabel:'Source: ASEAN Briefing - Malaysia\'s New Minimum Wage Rate for 2025'}},
      {country:'my',flag:'🇲🇾',name:'Malaysia',section:'my-epf-foreign',title:'2% EPF contributions for non-Malaysian employees',badge:'In force',effective:null,added:'2026-09-30',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'Non-Malaysian employees are subject to EPF at a flat 2% employer and 2% employee rate, with no wage limit.',employer:['Contribute 2% and deduct 2% of wages for non-Malaysian employees.'],employee:['Foreign employees have 2% of wages deducted for EPF.'],note:'',example:'On wages of RM5,000 the employer and employee each contribute RM100.',sourceUrl:'https://taxsummaries.pwc.com/malaysia/individual/other-taxes',sourceLabel:'Source: PwC Worldwide Tax Summaries - Malaysia, Individual - Other taxes'}},
      {country:'ph',flag:'🇵🇭',name:'Philippines',section:'ph-sss-15',title:'SSS contribution rate rises to 15%; MSC ceiling to PHP 35,000',effective:'2025-01-01',added:'2026-09-30',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'Under Republic Act No. 11199, SSS contributions rose from 14% to 15% on 1 January 2025, split 10% employer and 5% employee; the Monthly Salary Credit range moved to PHP 5,000-35,000 (from PHP 4,000-30,000).',employer:['Contribute 10% of the applicable Monthly Salary Credit and withhold 5% from the employee.','Apply the new MSC minimum of PHP 5,000 and maximum of PHP 35,000.'],employee:['Employee SSS share is 5% of the Monthly Salary Credit.'],note:'',example:'At the PHP 35,000 maximum MSC, the employer pays PHP 3,500 and the employee PHP 1,750 (total PHP 5,250).',sourceUrl:'https://www.forvismazars.com/ph/en/insights/hr-payroll-alerts/sss-contribution-rates-increased-to-15',sourceLabel:'Source: Forvis Mazars Philippines - SSS contribution rates increased to 15%'}},
      {country:'ph',flag:'🇵🇭',name:'Philippines',section:'ph-ncr-wage-order-28',title:'NCR minimum wage rises by PHP 60 to PHP 755 a day (Wage Order NCR-28)',effective:'2026-09-26',added:'2026-10-06',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'Wage Order No. NCR-28, issued on 7 September 2026 and published on 11 September 2026, grants a PHP 60 per day basic wage increase in the National Capital Region from 26 September 2026: non-agriculture PHP 695 to PHP 755 a day, and agriculture PHP 658 to PHP 718 a day. The same PHP 718 rate is listed for service and retail establishments employing 15 workers or fewer and manufacturing establishments regularly employing fewer than 10 workers.',employer:['Raise NCR employees paid below PHP 755 a day (PHP 718 in agriculture and the small service, retail and manufacturing categories) from 26 September 2026 in the daily rate used in payroll.','Check whether an exemption category applies and whether an exemption application is made; the NWPC site lists application forms for NCR-28.'],employee:['NCR minimum-wage earners receive PHP 60 more per day.'],note:'NWPC lists NCR-28 as the current NCR daily minimum wage (baseline PHP 695 under NCR-26). It also lists the earlier Wage Order No. NCR-27 (effective 25 July 2026, PHP 755 then PHP 780 from 20 January 2027) as subject to continuing litigation, with a notice that its implementation awaits a final resolution from the Pasig and Navotas courts. Confirm with the RTWPB-NCR which order applies to your establishment, especially for the January 2027 step.',example:'',sourceUrl:'https://nwpc.dole.gov.ph/regionlist/ncr/',sourceLabel:'Source: NWPC (DOLE) - National Capital Region current daily minimum wage rates'}},
      {country:'ph',flag:'🇵🇭',name:'Philippines',section:'ph-ncr-kasambahay-wage-2026',title:'NCR domestic worker minimum wage rises to PHP 7,800 a month',effective:'2026-02-07',added:'2026-10-06',category:'payroll',impact:'low',upcoming:false,detail:{lead:'Wage Order No. NCR-DW-06 raises the monthly minimum wage for domestic workers (kasambahay) in the National Capital Region by PHP 800, from PHP 7,000 to PHP 7,800, effective 7 February 2026.',employer:['Pay NCR household employers\' domestic workers at least PHP 7,800 a month from 7 February 2026.'],employee:['NCR domestic workers receive PHP 800 more per month.'],note:'NWPC states the effective date as 7 February 2026. NWPC pages give slightly different publication dates (21 January in a news item, 22 January on the rates page), so none is stated here.',example:'',sourceUrl:'https://nwpc.dole.gov.ph/rtwpb-ncr-wage-order-for-kasambahays-to-take-effect-on-february-07/',sourceLabel:'Source: NWPC (DOLE) - RTWPB-NCR wage order for kasambahays to take effect on February 07'}},
      {country:'sg',flag:'🇸🇬',name:'Singapore',section:'sg-cpf-senior-2026',title:'CPF rates rise for employees above 55 to 65',effective:'2026-01-01',added:'2026-09-30',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'From 1 January 2026 CPF contribution rates are 16% employer and 18% employee (34% total) for employees above 55 to 60, and 12.5% employer and 12.5% employee (25% total) for employees above 60 to 65.',employer:['Update CPF rate tables for employees aged above 55 to 65 from January 2026 wages.'],employee:['Employees above 55 to 65 see higher CPF deductions and employer contributions.'],note:'Different rates apply for different wage bands.',example:'',sourceUrl:'https://www.cpf.gov.sg/employer/employer-obligations/how-much-cpf-contributions-to-pay',sourceLabel:'Source: CPF Board - How much CPF contributions to pay'}},
      {country:'sg',flag:'🇸🇬',name:'Singapore',section:'sg-cpf-ow-ceiling',title:'CPF Ordinary Wage ceiling at SGD 8,000 a month',effective:'2026-01-01',added:'2026-09-30',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'From 1 January 2026 CPF is payable on monthly ordinary wages up to an OW ceiling of SGD 8,000, giving an annual ordinary wage ceiling of SGD 96,000 for 2026.',employer:['Cap ordinary wage CPF at SGD 8,000 per month; for employees 55 and below, maximum monthly contributions are SGD 1,360 employer and SGD 1,600 employee.'],employee:['CPF deduction on ordinary wages is capped at SGD 1,600 a month for employees 55 and below.'],note:'',example:'SGD 8,000 x 20% = SGD 1,600 employee; SGD 8,000 x 17% = SGD 1,360 employer.',sourceUrl:'https://taxsummaries.pwc.com/singapore/individual/other-taxes',sourceLabel:'Source: PwC Worldwide Tax Summaries - Singapore, Individual - Other taxes'}},
      {country:'th',flag:'🇹🇭',name:'Thailand',section:'th-min-wage-400',title:'THB 400 daily minimum wage for Bangkok, hotels and entertainment venues',effective:'2025-07-01',added:'2026-09-30',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'From 1 July 2025 the minimum daily wage is THB 400 in Bangkok and nationwide for type 2, 3 and 4 hotels under the Hotel Act and entertainment establishments under the Entertainment Place Act.',employer:['Pay at least THB 400 per day to covered workers from 1 July 2025; the new rates supersede lower contractual wages.'],employee:['Covered workers are entitled to at least THB 400 per day.'],note:'',example:'',sourceUrl:'https://www.tilleke.com/insights/thailand-raises-minimum-wage-for-bangkok-and-certain-businesses-nationwide/',sourceLabel:'Source: Tilleke & Gibbins - Thailand raises minimum wage for Bangkok and certain businesses nationwide'}},
      {country:'vn',flag:'🇻🇳',name:'Vietnam',section:'vn-rmw-2026',title:'Regional minimum wages rise about 7.2% under Decree 293/2025',effective:'2026-01-01',added:'2026-09-30',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'Decree No. 293/2025/ND-CP, effective 1 January 2026, sets monthly regional minimum wages at VND 5.31 million (Region I), 4.73 million (Region II), 4.14 million (Region III) and 3.7 million (Region IV), an increase of approximately 7.2%.',employer:['Adjust contracts and pay to at least the new regional minimum.','Review unemployment insurance contributions, whose salary cap is 20 times the regional minimum wage.'],employee:['Minimum monthly pay rises in all four regions.'],note:'',example:'Region I unemployment insurance salary cap: 20 x VND 5.31 million = VND 106.2 million.',sourceUrl:'https://www.bakermckenzie.com/en/insight/publications/2026/03/vietnam-change-to-the-regional-minimum-wage-in-2026',sourceLabel:'Source: Baker McKenzie - Vietnam: Change to the regional minimum wage in 2026'}},
      {country:'cn',flag:'🇨🇳',name:'China',section:'cn-reporting',title:'2026 social insurance contribution base declaration window opens',badge:'Declare 10 Jun - 25 Jul 2026',effective:'2026-07-25',added:'2026-09-29',category:'reporting',impact:'medium',upcoming:false,detail:{lead:'Beijing\'s Human Resources and Social Security Bureau opens the 2026 social insurance contribution base declaration window from 10 June to 25 July 2026. Employers declare each employee\'s 2026 contribution wage based on their average monthly wage in 2025, via the Social Insurance Contribution Management App, E-Tax China, or local tax service counters.',employer:['Declare each employee\'s 2026 contribution base within the 10 June - 25 July window using the employee\'s 2025 average monthly wage.','Flexibly employed individuals who miss the window have their base set to the prior year\'s amount by default.'],employee:['No direct action for standard employees - the employer declares on their behalf; flexibly employed individuals must self-declare.'],note:'Beijing-specific dates shown; other Chinese cities and provinces run similar annual declaration windows on their own local schedules.',example:'',sourceUrl:'https://english.beijing.gov.cn/workinginbeijing/laborrights/insurance/202606/t20260618_4706489.html',sourceLabel:'Source: Beijing Municipal Government - 2026 Social Insurance Contribution Base Declaration'}},
      {country:'cn',flag:'🇨🇳',name:'China',section:'cn-tax',title:'Jiangsu raises minimum wage tiers to RMB 2,660/2,430/2,180',effective:'2026-01-01',added:'2026-09-29',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'Jiangsu province raises its three-tier monthly minimum wage from RMB 2,490/2,260/2,010 to RMB 2,660/2,430/2,180 from 1 January 2026. Part-time hourly minimums rise from RMB 24/22/20 to RMB 25/23/21.',employer:['Update payroll to the applicable tier (I/II/III, by locality) for employees in Jiangsu from 1 January 2026.','Update part-time hourly rates to the new RMB 25/23/21 tiers.'],employee:['Minimum-wage employees in Jiangsu receive a RMB 170 monthly increase at every tier from January 2026.'],note:'China sets minimum wages at provincial level; check the applicable standard for each province where staff are employed.',example:'Tier I: RMB 2,660 - RMB 2,490 = RMB 170 per month.',sourceUrl:'https://chinajob.mohrss.gov.cn/h5/c/2026-01-12/480159.shtml',sourceLabel:'Source: Ministry of Human Resources and Social Security (MOHRSS) - Jiangsu 2026 minimum wage adjustment'}},
      {country:'tw',flag:'🇹🇼',name:'Taiwan',section:'tw-payroll',title:'Minimum wage rises to NT$29,500 a month; hourly rate to NT$196',effective:'2026-01-01',added:'2026-09-29',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'Taiwan\'s Ministry of Labor raises the monthly minimum wage from NT$28,590 to NT$29,500 and the hourly rate from NT$190 to NT$196 (both a 3.18% adjustment), effective 1 January 2026 - the 10th consecutive year of monthly minimum wage increases since 2016.',employer:['Raise any employee paid below NT$29,500/month or NT$196/hour to at least the new minimum from 1 January 2026.'],employee:['Minimum-wage employees receive a NT$910 monthly (NT$6 hourly) increase from January 2026.'],note:'',example:'NT$29,500 - NT$28,590 = NT$910 per month.',sourceUrl:'https://english.mol.gov.tw/21139/40790/87087/',sourceLabel:'Source: Ministry of Labor, Taiwan - 2026 Minimum Wage Announcement'}},
      {country:'tw',flag:'🇹🇼',name:'Taiwan',section:'tw-tax',title:'Standard deduction, exemption, and salary special deduction thresholds raised for 2026',badge:'Effective 2026 tax year',effective:'2026',added:'2026-09-29',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'Taiwan raises several individual income tax thresholds for the 2026 tax year to reflect cost-of-living changes: the standard deduction rises NT$5,000 to NT$136,000 for single filers (NT$10,000 to NT$272,000 for married joint filers), the personal exemption rises NT$4,000 to NT$101,000 (NT$151,500 for those 70+), and the special deduction for wage/salary earners and persons with disabilities rises from NT$218,000 to NT$227,000.',employer:['Update payroll withholding tax tables to the 2026 exemption and deduction thresholds.'],employee:['Slightly less income tax withheld in 2026 due to the higher exemption and deduction thresholds, even without a pay change.'],note:'',example:'',sourceUrl:'https://www.ocac.gov.tw/OCAC/Eng/Pages/Detail.aspx?nodeid=329&pid=81752008',sourceLabel:'Source: Overseas Community Affairs Council, Taiwan - 2026 Tax Threshold Adjustments'}},
      {country:'nz',flag:'🇳🇿',name:'New Zealand',section:'nz-tax',title:'Minimum wage rises to NZD $23.95 an hour',effective:'2026-04-01',added:'2026-09-29',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'The adult minimum wage rises from NZD $23.50 to $23.95 an hour from 1 April 2026, a 45-cent increase. The starting-out and training minimum wage rises from $18.80 to $19.16 an hour.',employer:['Raise any adult employee paid at or near $23.50/hour to at least $23.95 from the 1 April 2026 pay run.','Update starting-out and training wage rates to the new $19.16/hour floor.'],employee:['Minimum-wage employees receive a 45-cent hourly pay rise from 1 April 2026.'],note:'',example:'',sourceUrl:'https://www.employment.govt.nz/news-and-updates/minimum-wage-is-increasing-on-1-april-2026',sourceLabel:'Source: Employment New Zealand - Minimum wage increasing 1 April 2026'}},
      {country:'nz',flag:'🇳🇿',name:'New Zealand',section:'nz-kiwisaver',title:'KiwiSaver default contribution rate rises to 3.5%',effective:'2026-04-01',added:'2026-09-29',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'The default KiwiSaver employee and matching employer contribution rate rises from 3% to 3.5% from 1 April 2026, applying to all pay days from that date. Employees who want to keep contributing at 3% can apply to Inland Revenue for a temporary rate reduction, which employers can choose to match.',employer:['Update payroll systems to deduct and match KiwiSaver contributions at the new 3.5% default rate from the first pay day on or after 1 April 2026.','Where an employee has an approved temporary rate reduction, you may choose to match their reduced rate instead of the 3.5% default.','From 1 April 2026, make employer contributions for 16- and 17-year-old employees who are KiwiSaver members, if they meet the other eligibility criteria.'],employee:['Default KiwiSaver contributions rise from 3% to 3.5% of pay (both employee and matching employer share) unless a different rate is chosen or a temporary reduction is approved.'],note:'',example:'',sourceUrl:'https://www.ird.govt.nz/kiwisaver-changes',sourceLabel:'Source: Inland Revenue, New Zealand - KiwiSaver changes'}},
      {country:'hk',flag:'🇭🇰',name:'Hong Kong',section:'hk-tax',title:'Salaries tax allowances raised from year of assessment 2026/27',badge:'Effective YA 2026/27',effective:'2026-04-01',added:'2026-09-29',category:'payroll',impact:'low',upcoming:false,detail:{lead:'The 2026-27 Budget raises salaries tax allowances from the year of assessment 2026/27 onwards: basic allowance to HK$145,000, married person\'s allowance to HK$290,000, and child allowance (1st to 9th child) to HK$140,000 per child.',employer:['No payroll withholding action - Hong Kong salaries tax is assessed by the Inland Revenue Department rather than withheld by employers.'],employee:['Higher basic, married person\'s and child allowances reduce salaries tax from YA 2026/27.'],note:'A separate one-off 100% salaries tax reduction, capped at HK$3,000 per case, applies to YA 2025/26.',example:'',sourceUrl:'https://www.ird.gov.hk/eng/tax/budget.htm',sourceLabel:'Source: Inland Revenue Department, Hong Kong - 2026-27 Budget Tax Measures'}},
      {country:'hk',flag:'🇭🇰',name:'Hong Kong',section:'hk-minimum-wage',title:'Statutory minimum wage rises to HK$43.1 an hour',effective:'2026-05-01',added:'2026-09-29',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'The Statutory Minimum Wage (SMW) rate is raised to HK$43.1 per hour with effect from 1 May 2026, under the Government\'s new annual review mechanism, which uses a formula to review the SMW rate. The monthly monetary cap on the requirement to record employees\' total hours worked rises in tandem to HK$17,600.',employer:['Pay all covered employees at least HK$43.1 per hour from 1 May 2026.','Record total hours worked for employees earning below HK$17,600 per month.'],employee:['Covered employees are entitled to at least HK$43.1 per hour from 1 May 2026.'],note:'',example:'',sourceUrl:'https://www.labour.gov.hk/eng/news/mwo.htm',sourceLabel:'Source: Labour Department, Hong Kong - Statutory Minimum Wage'}},
      {country:'hk',flag:'🇭🇰',name:'Hong Kong',section:'hk-mpf',title:'Abolition of MPF offsetting against severance and long service payments',effective:'2025-05-01',added:'2026-09-29',category:'payroll',impact:'high',upcoming:false,detail:{lead:'From the transition date of 1 May 2025, employers can no longer use accrued benefits from their mandatory MPF contributions to offset severance payments (SP) or long service payments (LSP) attributable to service on or after that date. A grandfathering arrangement applies to employees employed before the transition date.',employer:['For employment from 1 May 2025 onward (post-transition portion), pay SP/LSP in full without offsetting MPF accrued benefits.','For employees employed before 1 May 2025, split SP/LSP into a pre-transition portion (based on wages and service at 1 May 2025) and a post-transition portion.','Accrued benefits from employer MPF contributions may still offset the pre-transition portion, but not the post-transition portion.'],employee:['SP/LSP attributable to service from 1 May 2025 can no longer be reduced by the employer\'s MPF contributions.'],note:'The HK$390,000 combined cap on SP/LSP continues to apply; any excess is deducted from the post-transition portion.',example:'An employee hired in 2015 and dismissed in 2027: the pre-transition portion (service to 1 May 2025) may be offset by accrued benefits from employer MPF contributions; the post-transition portion (service from 1 May 2025) must be paid in full.',sourceUrl:'https://www.labour.gov.hk/eng/news/aoa.htm',sourceLabel:'Source: Labour Department, Hong Kong - Abolition of MPF offsetting arrangement'}},
      {country:'bd',flag:'🇧🇩',name:'Bangladesh',section:'bd-tax',title:'Tax-free threshold of BDT 400,000 for FY 2026/27, rising to BDT 450,000 from FY 2027/28',badge:'FY 2026/27 (from 1 Jul 2026)',effective:'2026-07-01',added:'2026-09-29',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'For FY 2026/27 the general individual tax-free threshold is BDT 400,000 (BDT 450,000 for women and seniors; BDT 525,000 for persons with disabilities), with income above it taxed in progressive bands starting at 10%. The general threshold rises to BDT 450,000 for FY 2027/28 and FY 2028/29, when a 35% top slab applies. Where total income exceeds the tax-free limit, minimum tax is BDT 5,000 (BDT 1,000 for new taxpayers).',employer:['Apply the BDT 400,000 general threshold and the applicable higher thresholds when computing salary tax withholding for FY 2026/27.','Plan for the BDT 450,000 threshold and 35% top slab from FY 2027/28.'],employee:['No tax on income up to the applicable threshold; the first taxable band is 10%.'],note:'Figures from PwC Worldwide Tax Summaries; the NBR website was not reachable for verification.',example:'',sourceUrl:'https://taxsummaries.pwc.com/bangladesh/individual/taxes-on-personal-income',sourceLabel:'Source: PwC Worldwide Tax Summaries - Bangladesh: Taxes on personal income'}},
      {country:'bd',flag:'🇧🇩',name:'Bangladesh',section:'bd-withholding-return-quarterly',title:'Withholding tax return filed quarterly instead of monthly',effective:'2025-07-01',added:'2026-10-06',category:'reporting',impact:'medium',upcoming:false,detail:{lead:'The Finance Ordinance 2025, issued with effect from 1 July 2025, requires the withholding income tax return to be submitted quarterly instead of monthly. The deadline is the 25th of the month following the end of each quarter, with no option for time extensions.',employer:['File the withholding income tax return once per quarter, by the 25th of the month after quarter-end, instead of monthly.','Reconcile tax withheld across the quarter before filing, since no time extension is available.'],employee:[],note:'Source is the KPMG Bangladesh seminar booklet on the Finance Ordinance 2025, a professional source; it warns the Ordinance may be amended, and the NBR text was not located. The booklet does not say which payments the return covers, and deposit of withheld tax is a separate obligation.',example:'',sourceUrl:'https://assets.kpmg.com/content/dam/kpmg/bd/pdf/TaxUpdate/Salient_features_of_Finance_Ordinance_June_2025.pdf',sourceLabel:'Source: KPMG Bangladesh - Salient features of Finance Ordinance 2025'}},
      {country:'eg',flag:'🇪🇬',name:'Egypt',section:'eg-minimum-wage',title:'Private-sector minimum wage raised to EGP 7,000',effective:'2025-03-01',added:'2026-09-30',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'The National Wages Council raised the private-sector minimum wage from EGP 6,000 to EGP 7,000, effective 1 March 2025.',employer:['Pay at least EGP 7,000 per month to private-sector workers.','Periodic allowance of at least 3% of the insurance subscription wage and not less than EGP 250 per month.','Part-time workers: net hourly wage of at least EGP 28.'],employee:['Minimum monthly wage of EGP 7,000.'],note:'',example:'',sourceUrl:'https://moic.gov.eg/news/1998',sourceLabel:'Source: Ministry of Planning, Economic Development and International Cooperation - First meeting of the National Wages Council'}},
      {country:'eg',flag:'🇪🇬',name:'Egypt',section:'eg-insurable-wage',title:'Social insurance minimum and maximum insurable wage for 2026',effective:'2026-01-01',added:'2026-09-30',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'Insurable wage limits rise 15% each year through 2028. For 2026 the minimum is EGP 2,700 and the maximum EGP 16,700 per month.',employer:['Employer contribution: 18.75% of the social insurance salary.'],employee:['Employee contribution: 11% of the social insurance salary.'],note:'',example:'Employee at the 2026 maximum: 16,700 x 11% = EGP 1,837 per month.',sourceUrl:'https://taxsummaries.pwc.com/egypt/individual/other-taxes',sourceLabel:'Source: PwC Worldwide Tax Summaries - Egypt, Individual, Other taxes'}},
      {country:'eg',flag:'🇪🇬',name:'Egypt',section:'eg-insurable-wage-2027',title:'Insurable wage limits rise again in 2027',effective:'2027-01-01',added:'2026-09-30',category:'payroll',impact:'medium',upcoming:true,detail:{lead:'Under the scheduled annual increases, the minimum insurable wage becomes EGP 3,200 and the maximum EGP 19,300 per month in 2027.',employer:['18.75% employer contribution applies up to EGP 19,300.'],employee:['11% employee contribution applies up to EGP 19,300.'],note:'',example:'Employee at the 2027 maximum: 19,300 x 11% = EGP 2,123 per month.',sourceUrl:'https://taxsummaries.pwc.com/egypt/individual/other-taxes',sourceLabel:'Source: PwC Worldwide Tax Summaries - Egypt, Individual, Other taxes'}},
      {country:'il',flag:'🇮🇱',name:'Israel',section:'il-minimum-wage',title:'Minimum wage rises to NIS 6,443.85',effective:'2026-04-01',added:'2026-09-30',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'From 1 April 2026 the monthly minimum wage is NIS 6,443.85.',employer:['Hourly minimum NIS 35.4 (182-hour month) or NIS 34.64 (186-hour month).','Daily minimum NIS 297.4 (5-day week) or NIS 257.75 (6-day week).'],employee:['Monthly minimum wage NIS 6,443.85.'],note:'',example:'',sourceUrl:'https://www.btl.gov.il/English%20Homepage/Mediniyut/GeneralInformation/Pages/MinimumWage.aspx',sourceLabel:'Source: National Insurance Institute of Israel - Minimum Wage, General Information'}},
      {country:'il',flag:'🇮🇱',name:'Israel',section:'il-national-insurance',title:'National insurance and health tax thresholds',badge:'Current rates',effective:null,added:'2026-09-30',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'Resident employee contributions use a reduced rate on the first ILS 7,703 per month and a full rate up to the ILS 51,910 monthly maximum.',employer:['National insurance: 4.51% up to ILS 7,703, then 7.6% up to ILS 51,910.'],employee:['National insurance: 1.04% up to ILS 7,703, then 7% up to ILS 51,910.','Health tax: 3.23% up to ILS 7,703, then 5.17% up to ILS 51,910.'],note:'',example:'Employee national insurance on ILS 7,703: 7,703 x 1.04% = ILS 80.11.',sourceUrl:'https://taxsummaries.pwc.com/israel/individual/other-taxes',sourceLabel:'Source: PwC Worldwide Tax Summaries - Israel, Individual, Other taxes'}},
      {country:'lb',flag:'🇱🇧',name:'Lebanon',section:'lb-nssf-ceilings',title:'NSSF contribution ceilings raised',effective:'2025-08',added:'2026-09-30',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'The NSSF maternity and sickness ceiling rose to LL 120 million per month in August 2025, and the family benefit ceiling was revised to LL 18 million in July 2025.',employer:['Maternity and sickness: 8% on up to LL 120 million per month.','Family benefits: 6% on up to LL 18 million per month.','End-of-service indemnity: 5% of total annual earnings, no ceiling.'],employee:['Medical scheme: 3% on up to LL 120 million per month.'],note:'The previous monthly ceiling, set in April 2024, was LL 90 million.',example:'Employer maternity and sickness at the ceiling: 120,000,000 x 8% = LL 9,600,000 per month.',sourceUrl:'https://taxsummaries.pwc.com/lebanon/individual/other-taxes',sourceLabel:'Source: PwC Worldwide Tax Summaries - Lebanon, Individual, Other taxes'}},
      {country:'lb',flag:'🇱🇧',name:'Lebanon',section:'lb-minimum-wage-2025',title:'Official minimum wage raised to LL 28 million a month (Decree 699)',effective:'2025-08-01',added:'2026-10-06',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'Decree No. 699 of 18 July 2025 (Official Gazette No. 32, 24 July 2025) sets the new official minimum wage for employees and workers covered by the Labour Law. In NSSF Memorandum No. 801 of 1 August 2025, the NSSF applies a minimum monthly wage of LL 28,000,000 and a minimum daily wage of LL 1,300,000 for calculating employers\' contributions from 1 August 2025.',employer:['Raise employees paid below LL 28,000,000 a month (LL 1,300,000 a day) to the new minimum.','Calculate NSSF contributions on at least the new minimum wage from 1 August 2025.'],employee:['Minimum-wage employees under the Labour Law are entitled to LL 28 million a month.'],note:'NSSF Memorandum No. 801 first set the sickness and maternity ceiling at LL 140 million, but Memorandum No. 805 of 22 August 2025 (under Decree No. 887) replaced it with LL 120 million.',example:'',sourceUrl:'https://www.cnss.gov.lb/59-%d9%83%d8%b1%d9%83%d9%8a-%d8%a2%d9%84%d9%8a%d9%91%d8%a9-%d8%a7%d8%ad%d8%aa%d8%b3%d8%a7%d8%a8-%d8%a7%d8%b4%d8%aa%d8%b1%d8%a7%d9%83%d8%a7%d8%aa-%d8%a7%d9%84%d8%b6%d9%85%d8%a7%d9%86-%d8%a8%d8%b9/',sourceLabel:'Source: NSSF Lebanon - How NSSF contributions are calculated after the minimum wage rise to LL 28 million (7 August 2025)'}},
      {country:'ma',flag:'🇲🇦',name:'Morocco',section:'ma-income-tax-bands',title:'Income tax schedule revised by 2025 Finance Bill',effective:'2025-01-01',added:'2026-09-30',updated:'2026-10-03',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'The 2025 Finance Bill raised the tax-exempt first bracket from MAD 30,000 to MAD 40,000 and cut the top marginal rate from 38% to 37%.',employer:['Withhold using the revised scale: exempt up to MAD 40,000, top marginal rate 37%.'],employee:['Annual net income up to MAD 40,000 is exempt.'],note:'',example:'',sourceUrl:'https://taxsummaries.pwc.com/morocco/individual/significant-developments',sourceLabel:'Source: PwC Worldwide Tax Summaries - Morocco, Individual, Significant developments'}},
      {country:'ma',flag:'🇲🇦',name:'Morocco',section:'ma-dependant-deduction',title:'Family dependant deduction increased',badge:'2026 Finance Bill',effective:'2026-01-01',added:'2026-09-30',updated:'2026-10-03',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'The 2026 Finance Bill raised the annual deduction per dependant from MAD 500 to MAD 600, up to six dependants.',employer:['Apply MAD 600 per dependant per year in withholding calculations.'],employee:['Maximum annual benefit rises from MAD 3,000 to MAD 3,600.'],note:'',example:'6 dependants x MAD 600 = MAD 3,600 per year.',sourceUrl:'https://taxsummaries.pwc.com/morocco/individual/significant-developments',sourceLabel:'Source: PwC Worldwide Tax Summaries - Morocco, Individual, Significant developments'}},
      {country:'pk',flag:'🇵🇰',name:'Pakistan',section:'pk-salary-surcharge',title:'Surcharge on salary income abolished',badge:'Finance Act 2026',effective:'2026-07-01',added:'2026-09-30',updated:'2026-10-03',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'The Finance Act 2026 revised salaried tax slabs to reduce the burden, keeping the 35% top rate, and abolished the surcharge on salary income exceeding PKR 10 million.',employer:['Stop applying the surcharge when withholding tax on salary income above PKR 10 million.'],employee:['The surcharge continues to apply to non-salaried individuals and AOPs.'],note:'',example:'',sourceUrl:'https://taxsummaries.pwc.com/pakistan/individual/significant-developments',sourceLabel:'Source: PwC Worldwide Tax Summaries - Pakistan, Individual, Significant developments'}},
      {country:'sa',flag:'🇸🇦',name:'Saudi Arabia',section:'sa-gosi-annuity',title:'Annuity contribution rises to 10% for new-system GOSI members',effective:'2026-07',added:'2026-09-30',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'Under the new Social Insurance Law (Royal Decree M/273), in force from 3 July 2024, the pension rate for employees hired after that date rises by 0.5% on each side every July through 2028.',employer:['Annuity rate for new-system employees: 10% from July 2026, 10.5% from July 2027, 11% from July 2028.'],employee:['Same annuity rate as employer: 10% from July 2026.','Employees with prior contribution history under the previous laws keep their existing rates.'],note:'Source is a consultancy article; GOSI\'s own site did not return readable content.',example:'',sourceUrl:'https://www.silberson.com/2025/09/saudi-social-insurance-law-2025/',sourceLabel:'Source: Silberson - Saudi Arabia Social Insurance Law 2025 Key Changes'}},
      {country:'sa',flag:'🇸🇦',name:'Saudi Arabia',section:'sa-gosi-annuity-2027',title:'Next annuity step to 10.5%',effective:'2027-07',added:'2026-09-30',category:'payroll',impact:'medium',upcoming:true,detail:{lead:'The annuity contribution for employees hired after 3 July 2024 is scheduled to rise to 10.5% on each side in July 2027.',employer:['10.5% annuity contribution for new-system employees from July 2027.'],employee:['10.5% annuity contribution from July 2027.'],note:'Source is a consultancy article.',example:'',sourceUrl:'https://www.silberson.com/2025/09/saudi-social-insurance-law-2025/',sourceLabel:'Source: Silberson - Saudi Arabia Social Insurance Law 2025 Key Changes'}},
      {country:'tn',flag:'🇹🇳',name:'Tunisia',section:'tn-cnss-unemployment',title:'CNSS rates rise for new unemployment insurance fund',effective:'2025-01-01',added:'2026-09-30',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'Finance Law 2025 added a 0.5% employer and employee contribution to finance the new Unemployment Insurance Fund for Economic Reasons.',employer:['Employer CNSS rate rises from 16.57% to 17.07%.'],employee:['Employee CNSS rate rises from 9.18% to 9.68%.'],note:'',example:'',sourceUrl:'https://taxsummaries.pwc.com/tunisia/individual/other-taxes',sourceLabel:'Source: PwC Worldwide Tax Summaries - Tunisia, Individual, Other taxes'}},
      {country:'tn',flag:'🇹🇳',name:'Tunisia',section:'tn-income-tax-bands',title:'New progressive income tax scale',effective:'2025-01-01',added:'2026-09-30',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'A new eight-band scale applies from 1 January 2025, replacing the 2024 scale.',employer:['Withhold at: 0% to TND 5,000; 15% to 10,000; 25% to 20,000; 30% to 30,000; 33% to 40,000; 36% to 50,000; 38% to 70,000; 40% above 70,000.'],employee:['Annual income up to TND 5,000 is taxed at 0%.'],note:'',example:'',sourceUrl:'https://taxsummaries.pwc.com/tunisia/individual/taxes-on-personal-income',sourceLabel:'Source: PwC Worldwide Tax Summaries - Tunisia, Individual, Taxes on personal income'}},
      {country:'tn',flag:'🇹🇳',name:'Tunisia',section:'tn-solidarity-contribution',title:'Social Solidarity Contribution rises to 1%',effective:'2027-01',added:'2026-09-30',category:'payroll',impact:'medium',upcoming:true,detail:{lead:'The 0.5% Social Solidarity Contribution applies through fiscal year 2026 and is returns to 1% from January 2027.',employer:['Update withholding for the 1% rate from 2027.'],employee:['Certain low-income earners are exempt.'],note:'',example:'',sourceUrl:'https://taxsummaries.pwc.com/tunisia/individual/taxes-on-personal-income',sourceLabel:'Source: PwC Worldwide Tax Summaries - Tunisia, Individual, Taxes on personal income'}},
      {country:'tr',flag:'🇹🇷',name:'Turkey',section:'tr-ssi-limits',title:'Social security base limits for 2026',effective:'2026-01-01',added:'2026-09-30',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'From 1 January 2026 the social security salary base is a minimum of TRY 33,030.00 and a maximum of TRY 297,270.00 per month.',employer:['Employer SSI: 20.75%, reducible to 16.75% (5% in manufacturing) if conditions are met.','Unemployment insurance: 2%, up to TRY 297,270.00.'],employee:['Employee SSI: 14%.','Unemployment insurance: 1%.'],note:'',example:'Employee SSI at the minimum base: 33,030.00 x 14% = TRY 4,624.20 per month.',sourceUrl:'https://taxsummaries.pwc.com/turkey/individual/other-taxes',sourceLabel:'Source: PwC Worldwide Tax Summaries - Turkey, Individual, Other taxes'}},
      {country:'qa',flag:'🇶🇦',name:'Qatar',section:'qa-employment-law',title:'Minister of Labour Decision No. 50 of 2026 sets fixed WPS wage due dates',effective:'2026-09-09',added:'2026-09-29',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'Minister of Labour Decision No. 50 of 2026, published in the Official Gazette on 8 September 2026 and effective 9 September 2026, amends the Wage Protection System (WPS) rules: wages of monthly- or annually-paid employees are due on the first day of each calendar month, other workers are paid every two weeks, and employers must transfer wages to a bank or financial institution in Qatar within seven days of the due date via the WPS.',employer:['Pay monthly/annual-salary employees\' wages due on the 1st of each calendar month and transfer them through the WPS within seven days of that date.','Realign payroll calendars and bank instruction timelines to the fixed due date.','Failure to comply with the WPS rules may result in fines and suspension of Ministry of Labour services.'],employee:['Wages now have a fixed due date - the first day of each calendar month for monthly-paid employees.'],note:'',example:'',sourceUrl:'https://vialtopartners.com/regional-alerts/qatar-employment-tax-new-wage-payment-deadlines',sourceLabel:'Source: Vialto Partners - Qatar: New wage payment deadlines'}},
      {country:'qa',flag:'🇶🇦',name:'Qatar',section:'qa-labour-law-9-2026',title:'Qatar Labour Law amended: Ministry can suspend services of employers over wage violations',effective:'2026-06-25',added:'2026-10-06',category:'payroll',impact:'low',upcoming:false,detail:{lead:'Law No. 9 of 2026 (dated 11 June 2026, published in Official Gazette No. 11 on 25 June 2026) amends the Labour Law (Law No. 14 of 2004). New Article 146 bis lets the Minister of Labour suspend all or some of an employer\'s applications and transactions with the Ministry for a breach of the law, and extend the suspension to the employer\'s related establishments where the breach is repeated in the same year or collective disputes arise from late payment of wages. A worker harmed by a breach of Article 66 (reported by law firms as the wage-payment provision) may ask to change employer or end the contract, with the employer bearing the cost of return to the worker\'s home country.',employer:['Pay wages on time: late wages in a collective dispute can lead to suspension of Ministry of Labour transactions, extended to related establishments.','The suspension does not cover attestation of employment contracts or renewal of work licences and residence permits of the workers of the establishments concerned.','Under new Article 146 bis/1 the Minister may publish the names of establishments that repeatedly breach certain provisions, including Article 66.'],employee:['A worker affected by an employer\'s breach of Article 66 can request a change of employer or end the contract, with return travel costs borne by the employer.'],note:'Official text read on the Al Meezan Qatar legal portal (Arabic), which marks displayed articles as non-official; the Official Gazette copy governs. The law says only that it is published in the Official Gazette, so the 25 June 2026 effective date is the publication date. Law firms report that ministerial decisions are expected, and the law changes no wage rates or filings.',example:'',sourceUrl:'https://www.almeezan.qa/LawPage.aspx?id=10448&language=ar',sourceLabel:'Source: Al Meezan (Qatar Legal Portal) - Law No. 9 of 2026 amending the Labour Law'}},
      {country:'kw',flag:'🇰🇼',name:'Kuwait',section:'kw-insurance',title:'Social security contributions for Kuwaiti nationals: employer 11.5%, employee 10.5%',badge:'Current rates',effective:null,added:'2026-09-29',category:'payroll',impact:'low',upcoming:false,detail:{lead:'Social security contributions apply to Kuwaiti national employees. The employer contributes 11.5% and the employee 8% of monthly salary up to a ceiling of KWD 2,750, and employees pay an additional 2.5% supplementary contribution (on salary up to KWD 1,500), for a total employee rate of 10.5%.',employer:['Contribute 11.5% of monthly salary for Kuwaiti national employees, up to the KWD 2,750 monthly ceiling.','Withhold the employee\'s 8% basic contribution and 2.5% supplementary contribution and remit them to the Public Institution for Social Security.'],employee:['Kuwaiti nationals contribute 8% basic plus 2.5% supplementary (10.5% total), subject to the applicable ceilings.'],note:'Expatriate workers are not covered by the social security scheme; they are generally entitled to end-of-service indemnity under Kuwait Labour Law.',example:'',sourceUrl:'https://taxsummaries.pwc.com/kuwait/individual/other-taxes',sourceLabel:'Source: PwC Worldwide Tax Summaries - Kuwait, Individual - Other taxes'}},
      {country:'kw',flag:'🇰🇼',name:'Kuwait',section:'kw-wage-payment-system',title:'Central Bank launches Kuwait Wage Payment System (KWPS) for private-sector wages',effective:'2026-09-28',added:'2026-10-06',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'On 28 September 2026 the Central Bank of Kuwait (CBK) announced the launch of the Kuwait Wage Payment System (KWPS), a national platform for processing and monitoring wage transfers for private-sector employees through local banks so that wages are disbursed electronically. CBK manages the system technically and operationally, while the Public Authority for Manpower oversees employers\' compliance with the KWPS provisions.',employer:['Expect private-sector wage transfers to be processed and monitored through the KWPS via local banks; ask your bank and the Public Authority for Manpower how your payroll file must be submitted.','The system lets supervisory authorities monitor wage disbursement in real time and detect non-compliance early, so late or missing wage payments become visible to the regulator.'],employee:['Private-sector wages are paid electronically through local banks and tracked on a national platform.'],note:'The press release announces the launch only; it does not state employer deadlines, file formats or penalties, so none are stated here. It is the third system under phase II of the Kuwait National Payments System project.',example:'',sourceUrl:'https://www.cbk.gov.kw/en/cbk-news/announcements-and-press-releases/press-releases/2026/09/202609280825-cbk-launches-kuwait-wage-payment-system-kwps',sourceLabel:'Source: Central Bank of Kuwait - CBK Launches Kuwait Wage Payment System (KWPS)'}},
      {country:'bh',flag:'🇧🇭',name:'Bahrain',section:'bh-pension',title:'Employer social insurance contribution for Bahraini nationals rises to 18%',effective:'2026-01-01',added:'2026-09-29',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'Under the 2022 social insurance reform, the employer contribution rate for Bahraini nationals increases by 1% to 18% effective 1 January 2026, while the employee share remains 8%, for a combined total of 22% of pensionable salary. The annual increase continues through 2028.',employer:['Apply the 18% employer contribution for Bahraini nationals from the January 2026 payroll.','Plan for further annual 1% increases through 2028.'],employee:['Employee share unchanged at 8% of pensionable salary.'],note:'',example:'On BHD 1,000 pensionable salary: employer BHD 180 (18%), employee BHD 80 (8%), total BHD 220 (22%).',sourceUrl:'https://vialtopartners.com/regional-alerts/bahrain-social-security-employer-contribution-rate-increase-and-extended-wages-protection-system',sourceLabel:'Source: Vialto Partners - Bahrain: Employer contribution rate increase and extended Wages Protection System'}},
      {country:'bh',flag:'🇧🇭',name:'Bahrain',section:'bh-reporting',title:'Enhanced WPS: Wages Responsible Person due 1 Feb 2026, filings deadline end of Q1 2026',badge:'Deadlines Feb-Mar 2026',effective:'2026-02-01',added:'2026-09-29',category:'reporting',impact:'medium',upcoming:false,detail:{lead:'Bahrain\'s Labour Market Regulatory Authority (LMRA) has extended the deadline for enhanced Wages Protection System (WPS) filings to the end of Q1 2026, and employers must appoint a Wages Responsible Person (WRP) by 1 February 2026.',employer:['Appoint a Wages Responsible Person (WRP) by 1 February 2026.','Complete enhanced WPS filings by the end of Q1 2026.'],employee:['No direct change to pay; wages are processed under the enhanced WPS.'],note:'',example:'',sourceUrl:'https://vialtopartners.com/regional-alerts/bahrain-social-security-employer-contribution-rate-increase-and-extended-wages-protection-system',sourceLabel:'Source: Vialto Partners - Bahrain: Employer contribution rate increase and extended Wages Protection System'}},
      {country:'om',flag:'🇴🇲',name:'Oman',section:'om-tax',title:'Mandatory performance-based annual increments for Omani private-sector workers',badge:'Ministerial Resolution 317/2025',effective:'2026-01-01',added:'2026-09-29',updated:'2026-10-03',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'Oman\'s Ministerial Resolution 317/2025 sets a minimum periodic increment for Omani workers in the private sector, paid annually on 1 January based on performance (the resolution has been in force since 28 July 2025; the first increments are due on 1 January 2026): 5% of basic salary for excellent, 4% very good, 3% good, 2% acceptable, and no increment for poor. Workers must have been appointed for at least six months in the establishment.',employer:['Award the minimum increment (2-5% of basic salary by rating) to eligible Omani workers each 1 January.','Complete performance evaluations before the increment date.','An administrative fine of RO 50 applies per violation, multiplied by the number of workers involved.'],employee:['Omani workers with at least six months\' service receive an annual increment of 2-5% of basic salary depending on performance rating.'],note:'Applies to Omani workers in the private sector.',example:'On a basic salary of RO 800 with a very good rating: increment RO 32 (4%).',sourceUrl:'https://www.omanobserver.om/article/1174098/oman/minimum-periodic-increment-for-omani-workers-in-pvt-sector',sourceLabel:'Source: Oman Observer - Minimum periodic increment for Omani workers in private sector'}},
      {country:'om',flag:'🇴🇲',name:'Oman',section:'om-insurance',title:'Sick leave and unusual leave insurance starts; expat work-injury cover deferred to 2028',effective:'2026-07-19',added:'2026-09-29',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'Sultani Decree No. 60/2025, issued 13 July 2025, amends the Social Protection Law: the sick leave and unusual leaves insurance scheme takes effect on 19 July 2026 (postponed by one year), while work injuries insurance for non-Omani workers is delayed from 19 July 2026 to 19 July 2028.',employer:['Prepare for the sick leave and unusual leaves insurance scheme from 19 July 2026.','Do not begin work injury insurance contributions for non-Omani workers before 19 July 2028.'],employee:['Sick leave and unusual leaves insurance applies from 19 July 2026.'],note:'',example:'',sourceUrl:'https://knowledge.dlapiper.com/dlapiperknowledge/globalemploymentlatestdevelopments/2025/social-protection-law-under-sultani-decree-no.-60-2025',sourceLabel:'Source: DLA Piper - Social Protection Law under Sultani Decree No. 60/2025'}},
      {country:'pa',flag:'🇵🇦',name:'Panama',section:'pa-tax',title:'New minimum wage rates under Executive Decree No. 13 of 31 December 2025',effective:'2026-01-16',added:'2026-09-29',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'Executive Decree No. 13 of 31 December 2025, published in Official Gazette No. 30438 on 6 January 2026, sets new minimum wage rates effective 16 January 2026, differentiated by economic activity, occupation, company size and region (Region 1 and Region 2). It repeals Executive Decree No. 01 of 10 January 2024.',employer:['Update payroll to the new minimum wage rates from 16 January 2026.','Check the rate for each employee\'s activity, occupation, company size and region in the decree.'],employee:['Minimum wage depends on activity, occupation, company size and region.'],note:'',example:'',sourceUrl:'https://www.ey.com/es_ce/technical/tax/tax-alerts/panama-salario-minimo-2026',sourceLabel:'Source: EY Tax Alert - Panamá: Salario mínimo 2026'}},
      {country:'pa',flag:'🇵🇦',name:'Panama',section:'pa-insurance',title:'Law 462 phases in higher employer social security contributions through 2029',badge:'Phased: 1 Mar 2027 and 1 Mar 2029',effective:'2027-03-01',added:'2026-09-29',category:'payroll',impact:'medium',upcoming:true,detail:{lead:'Law No. 462, enacted on 18 March 2025, reforms Panama\'s social security system. The employer contribution is 13.25% until 28 February 2027, rises to 14.25% from 1 March 2027, and to 15.25% from 1 March 2029. The employee contribution remains fixed at 9.75% of gross salary.',employer:['Apply the 13.25% employer contribution until 28 February 2027.','Increase the employer contribution to 14.25% from 1 March 2027.','Increase the employer contribution to 15.25% from 1 March 2029.'],employee:['Employee social security contribution remains 9.75% of gross salary.'],note:'',example:'On a B/. 1,000 monthly salary: employee contribution B/. 97.50 (9.75%); employer contribution B/. 132.50 (13.25%) until 28 Feb 2027, B/. 142.50 (14.25%) from 1 Mar 2027 and B/. 152.50 (15.25%) from 1 Mar 2029.',sourceUrl:'https://fmm.com.pa/panama-social-security-reform-2025-key-highlights-of-law-no-462/',sourceLabel:'Source: Fábrega Molino - Panama Social Security Reform 2025: Key Highlights of Law No. 462'}},
      {country:'do',flag:'🇩🇴',name:'Dominican Republic',section:'do-tax',title:'TSS raises social security contribution caps',effective:'2026-02-01',added:'2026-09-29',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'The Tesorería de la Seguridad Social (TSS) sets new contribution caps for the Contributory Regime from 1 February 2026, following the private-sector wage increase in Resolution CNS-01-2025, using a minimum wage reference of RD$23,223.00: Work Risk Insurance RD$92,892.00, Family Health Insurance RD$232,230.00, and Old Age, Disability and Survivor Insurance RD$464,460.00.',employer:['Apply the new contribution caps for Work Risk, Family Health and pension insurance from 1 February 2026.'],employee:['Health and pension contributions are calculated up to the new higher caps.'],note:'',example:'',sourceUrl:'https://presidencia.gob.do/noticias/tss-informa-nuevos-topes-de-cotizacion-del-regimen-contributivo-del-sdss',sourceLabel:'Source: Presidencia de la República Dominicana - TSS nuevos topes de cotización'}},
      {country:'do',flag:'🇩🇴',name:'Dominican Republic',section:'do-minimum-wage-2026',title:'Private-sector minimum wage up 8% from 1 February 2026 (large firms RD$29,988)',effective:'2026-02-01',added:'2026-10-06',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'From 1 February 2026 the minimum wage of private-sector workers in micro, small, medium and large companies rose 8%, as approved by the Comite Nacional de Salarios: RD$29,988.00 a month in large companies, RD$27,489.60 in medium, RD$18,421.20 in small and RD$16,993.20 in micro companies.',employer:['Raise unsectorised private-sector employees below the new monthly minimum for their company size from the February 2026 pay run.','Update any pay scales or allowances that reference the minimum wage.'],employee:['Minimum-wage workers receive the 8% increase from 1 February 2026; the Labour Ministry puts the rise between February 2025 and February 2026 at 20% nominal.'],note:'Sector minimums (free zones, hotels, casinos, restaurants) are set by separate resolutions and apply from 1 June 2026. Security guards in private guard companies and field workers have their own minimums, not covered here.',example:'',sourceUrl:'https://mt.gob.do/ministerio-de-trabajo-llama-a-empresarios-a-cumplir-con-el-pago-del-aumento-del-8-del-salario-minimo/',sourceLabel:'Source: Ministerio de Trabajo (Dominican Republic) - Ministerio de Trabajo llama a empresarios a cumplir con el pago del aumento del 8% del salario minimo'}},
      {country:'do',flag:'🇩🇴',name:'Dominican Republic',section:'do-minimum-wage-sectors-2026',title:'Free-zone, hotel and restaurant minimum wages rise from 1 June 2026',effective:'2026-06-01',added:'2026-10-06',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'Resolutions CNS-03-2025 and CNS-04-2025 of the Comite Nacional de Salarios set 2026 sector minimums valid from 1 June 2026: free zones RD$20,875.00 a month; hotels and casinos RD$21,840.00 (151 workers or more) or RD$18,409.30 (150 or fewer); food and beverage establishments RD$21,000.00 (151 or more) or RD$17,701.25 (150 or fewer).',employer:['Move free-zone, hotel, casino and restaurant staff below these monthly minimums up to them from 1 June 2026.'],employee:['Sector minimum-wage workers receive the new rates from 1 June 2026.'],note:'Source is an EY Central America tax alert dated 3 March 2026 (professional source) summarising Resolutions CNS-03-2025 (30 April 2025) and CNS-04-2025 (26 May 2025); the resolution texts were not fetched.',example:'',sourceUrl:'https://www.ey.com/es_ce/technical/tax/tax-alerts/republica-dominicana-salario-minimo-2026',sourceLabel:'Source: EY Central America - Republica Dominicana: salario minimo 2026'}},
      {country:'gt',flag:'🇬🇹',name:'Guatemala',section:'gt-tax',title:'New minimum wages by sector take effect under Acuerdo Gubernativo 256-2025',effective:'2026-01-01',added:'2026-09-29',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'Guatemala\'s Ministry of Labour and Social Welfare sets new minimum wages by economic activity and jurisdiction under Acuerdo Gubernativo 256-2025, effective 1 January 2026. In Guatemala department (C1): non-agricultural Q131.58/day (Q4,002.28/month). Rest of country (C2): non-agricultural Q125.49/day.',employer:['Update payroll to the applicable 2026 minimum wage by economic activity (agricultural, non-agricultural, export/maquila) and jurisdiction (C1 Guatemala department vs. C2 rest of country) from 1 January 2026.'],employee:['Minimum wage varies by sector and region - check the applicable rate for your specific economic activity and jurisdiction.'],note:'',example:'',sourceUrl:'https://dca.gob.gt/noticias-guatemala-diario-centro-america/gobierno-fija-nuevos-salarios-minimos-para-2026/',sourceLabel:'Source: Diario de Centro América - Gobierno fija nuevos salarios mínimos para 2026'}},
      {country:'gt',flag:'🇬🇹',name:'Guatemala',section:'gt-igss',title:'Social security contribution rates: employer 12.67%, employee 4.83%',badge:'Current rates',effective:null,added:'2026-09-29',category:'payroll',impact:'low',upcoming:false,detail:{lead:'Employers in Guatemala contribute 12.67% of monthly payroll and employees 4.83% of monthly salary toward social security.',employer:['Contribute 12.67% of monthly payroll.','Withhold 4.83% of each employee\'s monthly salary and remit it with the employer contribution.'],employee:['Social security deduction: 4.83% of monthly salary.'],note:'',example:'On a Q10,000 monthly salary: employer Q1,267 (12.67%); employee Q483 (4.83%).',sourceUrl:'https://taxsummaries.pwc.com/guatemala/individual/other-taxes',sourceLabel:'Source: PwC Worldwide Tax Summaries - Guatemala, Individual - Other taxes'}},
      {country:'bo',flag:'🇧🇴',name:'Bolivia',section:'bo-tax',title:'National minimum wage set at Bs 3,300 under Decreto Supremo 5516',badge:'Effective 1 Jan 2026 (retroactive)',effective:'2026-01-01',added:'2026-09-29',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'Bolivia\'s Decreto Supremo 5516 sets the Salario Mínimo Nacional at Bs 3,300, retroactive to 1 January 2026. The adjustment applies where the basic salary is below Bs 3,300, which must be leveled to at least that amount, and employers may not neutralise the increase by reducing rights, bonuses or other pay components.',employer:['Raise any basic salary below Bs 3,300 to the new minimum, retroactive to 1 January 2026.','Do not reduce bonuses or other remuneration components to offset the increase.'],employee:['Workers with a basic salary below Bs 3,300 are leveled up to the new minimum from 1 January 2026.'],note:'',example:'',sourceUrl:'https://mintrabajo.gob.bo/index.php/nota_prensa/la-paz-32/',sourceLabel:'Source: Ministerio de Trabajo, Empleo y Previsión Social, Bolivia'}},
      {country:'bo',flag:'🇧🇴',name:'Bolivia',section:'bo-insurance',title:'Employer social charges of 17.21% of gross salary',badge:'Current rates',effective:null,added:'2026-09-29',category:'payroll',impact:'low',upcoming:false,detail:{lead:'Employer social tax charges in Bolivia are 17.21% of gross salary in general. Separately, RC-IVA is a 13% tax on employee income that employers withhold through payroll.',employer:['Pay employer social charges of 17.21% of gross salary.','Withhold RC-IVA (13% tax on employee income) through payroll and remit it to the tax authority.'],employee:['RC-IVA at 13% applies to employee income and is withheld through payroll.'],note:'',example:'For 10 employees earning Bs 3,300/month each (Bs 33,000 total payroll), employer social charges are Bs 5,679.30 (17.21%).',sourceUrl:'https://taxsummaries.pwc.com/bolivia/corporate/other-taxes',sourceLabel:'Source: PwC Worldwide Tax Summaries - Bolivia, Corporate - Other taxes'}},
      {country:'sv',flag:'🇸🇻',name:'El Salvador',section:'sv-minimum-wage',title:'Minimum wage rises 12% across all sectors',effective:'2025-06-01',added:'2026-09-30',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'El Salvador raised the minimum wage by 12% from 1 June 2025, with rates set by decree for agriculture, industry, commerce, services, and textile and apparel manufacturing.',employer:['Apply the 12% higher minimum wage for the relevant sector from 1 June 2025.'],employee:['Minimum wage workers receive a 12% increase from 1 June 2025.'],note:'',example:'',sourceUrl:'https://diario.elmundo.sv/economia/el-salario-minimo-por-sector-economico-a-partir-del-1-de-junio',sourceLabel:'Source: Diario El Mundo - El salario mínimo por sector económico a partir del 1 de junio'}},
      {country:'sv',flag:'🇸🇻',name:'El Salvador',section:'sv-insurance',title:'ISSS (social security) and AFP (pension) contribution rates',badge:'Current rates',effective:null,added:'2026-09-29',category:'payroll',impact:'low',upcoming:false,detail:{lead:'ISSS social security contributions are 3% (employee) and 7.5% (employer) on salaries up to USD 1,000/month, capped at USD 30 and USD 75 respectively for higher salaries. AFP pension contributions are 7.25% (employee) and 8.75% (employer).',employer:['ISSS: 7.5% of salary, maximum USD 75/month per employee.','AFP: 8.75% of salary.','Withhold employee ISSS (3%, max USD 30) and AFP (7.25%) and remit them monthly.'],employee:['ISSS: 3% of salary, maximum USD 30/month.','AFP: 7.25% of salary.'],note:'',example:'On a USD 1,500 monthly salary: ISSS employee USD 30, employer USD 75; AFP employee USD 108.75, employer USD 131.25. Totals: employee USD 138.75, employer USD 206.25.',sourceUrl:'https://taxsummaries.pwc.com/el-salvador/individual/other-taxes',sourceLabel:'Source: PwC Worldwide Tax Summaries - El Salvador, Individual - Other taxes'}},
      {country:'ar',flag:'🇦🇷',name:'Argentina',section:'ar-smvm',title:'Minimum wage (SMVM) monthly schedule Sep 2026 to Apr 2027',effective:'2026-09-01',added:'2026-09-30',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'Resolución 4/2026 of the Consejo Nacional del Empleo, la Productividad y el Salario Mínimo, Vital y Móvil sets monthly increases to the minimum wage from September 2026 to April 2027.',employer:['Monthly SMVM: $383.800 from 1 Sep 2026, $391.200 from 1 Oct 2026, $398.800 from 1 Nov 2026, $406.400 from 1 Dec 2026.','Continues at $414.200 (Jan 2027), $422.000 (Feb 2027), $429.600 (Mar 2027) and $437.000 (Apr 2027).','Hourly SMVM rises from $1.919 (Sep 2026) to $2.185 (Apr 2027).'],employee:['Applies to workers under Law 20.744, agricultural workers and public administration employees.'],note:'',example:'',sourceUrl:'https://www.argentina.gob.ar/normativa/nacional/norma-429565/texto',sourceLabel:'Source: Argentina.gob.ar - Resolución 4/2026 (texto original)'}},
      {country:'ar',flag:'🇦🇷',name:'Argentina',section:'ar-ganancias-deductions',title:'Income tax withholding: 2026 personal deductions (Jan-Jun period)',effective:'2026-01-01',added:'2026-09-30',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'ARCA published the Article 30 personal deductions for withholding on remuneration received January to June 2026, updated by INDEC CPI under article 71 of Ley 27.743.',employer:['Apply the updated deductions under Resolución General 4.003 when computing monthly withholding.','Annualised (to December 2026) ganancia no imponible: $5.151.802,50; deducción especial (Art. 30 c) ap. 2): $24.728.652,02.','Accumulated January amount of ganancia no imponible: $429.316,88.'],employee:['Family deductions to December 2026: spouse $4.851.964,66; child $2.446.863,48.'],note:'',example:'',sourceUrl:'https://www.afip.gob.ar/gananciasYBienes/ganancias/personas-humanas-sucesiones-indivisas/deducciones/documentos/Deducciones-personales-art-30-ene-a-jun-2026.pdf',sourceLabel:'Source: ARCA - Deducciones del artículo 30, período enero a junio 2026'}},
      {country:'br',flag:'🇧🇷',name:'Brazil',section:'br-minimum-wage',title:'National minimum wage R$1,621 for 2026',effective:'2026-01-01',added:'2026-09-30',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'Decreto nº 12.797/2025 sets the national minimum wage at R$1.621,00 from 1 January 2026.',employer:['Update salaries at the minimum to R$1.621,00 from January 2026 payroll.','Domestic employers must update contracts manually in eSocial Doméstico before closing monthly payroll; the system does not apply the adjustment automatically.'],employee:['Workers paid the minimum wage receive R$1.621,00 per month.'],note:'',example:'',sourceUrl:'https://www.gov.br/esocial/pt-br/noticias/novo-salario-minimo-2026-veja-como-registrar-o-reajuste-no-esocial-domestico',sourceLabel:'Source: gov.br eSocial - Novo salário mínimo 2026: veja como registrar o reajuste no eSocial Doméstico'}},
      {country:'br',flag:'🇧🇷',name:'Brazil',section:'br-inss-2026',title:'INSS employee contribution bands for 2026',effective:'2026-01',added:'2026-09-30',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'Portaria Interministerial MPS/MF nº 13 of 09/01/2026 updates the progressive INSS contribution table for employees, domestic employees and casual workers from competência January 2026.',employer:['Withhold 7.5% up to R$1.621,00; 9% from R$1.621,01 to R$2.902,84; 12% from R$2.902,85 to R$4.354,27; 14% from R$4.354,28 to R$8.475,55.','R$8.475,55 is the top of the contribution base.'],employee:['Rates apply progressively to each band of salary.'],note:'',example:'Salary R$3.000,00: 7.5% x 1.621,00 = 121,58; 9% x 1.281,84 = 115,37; 12% x 97,16 = 11,66; total about R$248,61.',sourceUrl:'https://www.gov.br/inss/pt-br/direitos-e-deveres/inscricao-e-contribuicao/tabela-de-contribuicao-mensal',sourceLabel:'Source: INSS (gov.br) - Tabela de contribuição mensal'}},
      {country:'br',flag:'🇧🇷',name:'Brazil',section:'br-irpf-reduction',title:'IRPF withholding reduction: zero tax up to R$5,000 per month',effective:'2026-01',added:'2026-09-30',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'Lei nº 15.270 of 26 November 2025 introduces a monthly IRPF reduction from January 2026 that brings tax to zero on taxable income up to R$5.000,00 and phases out at R$7.350,00.',employer:['Monthly table 2026: exempt up to R$2.428,80; 7.5% / 15% / 22.5% bands; 27.5% above R$4.664,68 (deduction R$908,73).','Up to R$5.000,00: reduction of up to R$312,89 so that tax due is zero.','R$5.000,01 to R$7.350,00: reduction = R$978,62 - (0,133145 x monthly taxable income).'],employee:['Employees earning up to R$5.000,00 taxable per month have no IRPF withheld.'],note:'',example:'Taxable income R$6.000,00: reduction = 978,62 - 0,133145 x 6.000 = 978,62 - 798,87 = R$179,75.',sourceUrl:'https://www.gov.br/receitafederal/pt-br/assuntos/meu-imposto-de-renda/tabelas/2026',sourceLabel:'Source: Receita Federal (gov.br) - Tributação de 2026'}},
      {country:'cl',flag:'🇨🇱',name:'Chile',section:'cl-imm',title:'Ingreso mínimo mensual raised to $553.553',effective:'2026-05-01',added:'2026-09-30',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'Ley N°21.830 (Diario Oficial 22.06.2026) sets the monthly minimum income from 1 May 2026.',employer:['Workers aged 18 to 65: $553.553.','Workers under 18 or over 65: $412.938.','Non-remunerative purposes: $356.815.'],employee:['Minimum monthly income for workers aged 18 to 65 is $553.553.'],note:'',example:'',sourceUrl:'https://www.dt.gob.cl/portal/1628/w3-article-60141.html',sourceLabel:'Source: Dirección del Trabajo - ¿Cuál es el valor del ingreso mínimo mensual?'}},
      {country:'cl',flag:'🇨🇱',name:'Chile',section:'cl-pension-employer',title:'Pension reform: new employer contribution phase-in',effective:'2025-08',added:'2026-09-30',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'Law N°21.735 (pension reform) creates an employer-funded contribution starting with August 2025 remuneration, rising gradually to 8.5% of taxable salary by 2033.',employer:['From August 2025 payroll: additional 1% of taxable salary.','Of the 1%, 0.1% goes to the worker\'s individual AFP account and 0.9% to the Seguro Social Previsional.','Declarations due by the 13th of each month when filed electronically.'],employee:['Contribution is paid by the employer and is not deducted from salary.'],note:'',example:'',sourceUrl:'https://previsionsocial.gob.cl/empleadores-nueva-cotizacion-establecida-en-la-reforma-de-pensiones-rige-a-partir-de-la-remuneracion-de-agosto-de-2025/',sourceLabel:'Source: Subsecretaría de Previsión Social - Empleadores: nueva cotización rige a partir de la remuneración de agosto de 2025'}},
      {country:'co',flag:'🇨🇴',name:'Colombia',section:'co-minimum-wage',title:'2026 minimum wage $1.750.905 set on a transitional basis',badge:'Decreto 159 of 19 Feb 2026',effective:'2026-02-19',added:'2026-09-30',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'Decreto 159 of 19 February 2026 sets the 2026 monthly minimum wage at $1.750.905 (a 23% increase) on a transitional basis after the Consejo de Estado order of 12 February 2026 concerning Decreto 1469 of 2025.',employer:['Pay at least $1.750.905 per month.','The decree applies from its publication until judgment in Consejo de Estado case 11001-03-25-000-2026-00004-00.'],employee:['Monthly minimum wage: $1.750.905.'],note:'Provisional: Decreto 159 applies transitionally until the Consejo de Estado rules on the nullity case against Decreto 1469 of 2025, so the amount may change.',example:'',sourceUrl:'https://www.cancilleria.gov.co/normograma/compilacion/docs/decreto_0159_2026.htm',sourceLabel:'Source: Cancillería de Colombia (normograma) - Decreto 159 de 2026'}},
      {country:'co',flag:'🇨🇴',name:'Colombia',section:'co-sunday-surcharge',title:'Sunday and holiday surcharge rises to 90%, 100% from July 2027',effective:'2026-07-01',added:'2026-09-30',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'Ley 2466 de 2025 (Article 179) raises the surcharge for work on Sundays and holidays to 100% in stages.',employer:['80% from 1 July 2025.','90% from 1 July 2026.','Full 100% from 1 July 2027.'],employee:['Sunday and holiday work is paid with the surcharge over ordinary salary.'],note:'',example:'',sourceUrl:'https://www.alcaldiabogota.gov.co/sisjur/normas/Norma1.jsp?i=181933',sourceLabel:'Source: Alcaldía de Bogotá (Régimen Legal) - Ley 2466 de 2025'}},
      {country:'co',flag:'🇨🇴',name:'Colombia',section:'co-night-work',title:'Night work now starts at 7:00 p.m.',badge:'Law of 25 Jun 2025',effective:'2025-06-25',added:'2026-09-30',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'Ley 2466 de 2025 (Article 160) defines night work as work performed between 7:00 p.m. and 6:00 a.m. the following day.',employer:['Apply night-work treatment to hours worked from 7:00 p.m. to 6:00 a.m.','Law published in Diario Oficial No. 53160 of 25 June 2025.'],employee:['Hours from 7:00 p.m. count as night work.'],note:'',example:'',sourceUrl:'https://www.alcaldiabogota.gov.co/sisjur/normas/Norma1.jsp?i=181933',sourceLabel:'Source: Alcaldía de Bogotá (Régimen Legal) - Ley 2466 de 2025'}},
      {country:'cr',flag:'🇨🇷',name:'Costa Rica',section:'cr-minimum-wage',title:'Private-sector minimum wages up 1.63% for 2026',effective:'2026-01-01',added:'2026-09-30',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'Decree No. 45303-MTSS sets private-sector minimum wages from 1 January 2026 with a general increase of 1.63%.',employer:['General increase of 1.63% for unskilled workers.','Minimums range from ¢12,436.41 per day (unskilled) to ¢796,921.00 per month (university licentiate).'],employee:['Differentiated increases apply to domestic work and certain specialised occupations.'],note:'',example:'',sourceUrl:'https://www.bdo.cr/en-gb/insights/2025/increase-in-minimum-wages-for-2026',sourceLabel:'Source: BDO Costa Rica - Increase in minimum wages for 2026'}},
      {country:'cr',flag:'🇨🇷',name:'Costa Rica',section:'cr-ivm-2026',title:'CCSS pension (IVM) contributions rise: employer 5.58%, employee 4.33%',badge:'Scheduled step, planned to 31 Dec 2028',effective:'2026-01-01',added:'2026-10-06',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'From 1 January 2026 the CCSS Invalidity, Old Age and Death (IVM) contributions rise under the gradual 1.00% increase every 3 years in Transitory XI of the IVM Regulation: employer 5.42% to 5.58% and employee 4.17% to 4.33%, with the state contribution at 1.75% (total IVM 11.66%). Total employer charges become 26.83% and total employee charges 10.83% (37.66% combined), with the rates planned to apply until 31 December 2028.',employer:['Apply the new IVM rates from the first pay period of 2026; the other components of the employer-employee contributions are unchanged.','Update payroll to total employer charges of 26.83% of gross salary.'],employee:['Employee total social charges are 10.83% of gross salary, of which IVM is 4.33%.'],note:'Source is an EY Central America tax alert dated 15 December 2025 (professional source); the CCSS site could not be retrieved.',example:'',sourceUrl:'https://www.ey.com/es_ce/technical/tax/tax-alerts/costa-rica-aumento-en-cuotas-obrero-patronales-aplicable-desde-enero-20261',sourceLabel:'Source: EY Central America - Costa Rica: aumento en cuotas obrero patronales aplicable desde enero 2026'}},
      {country:'cr',flag:'🇨🇷',name:'Costa Rica',section:'cr-salary-tax-2026',title:'2026 salary tax bands: exempt up to CRC 918,000 a month',effective:'2026-01-01',added:'2026-10-06',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'Executive Decree No. 45333-H (La Gaceta No. 229, 5 December 2025) sets the 2026 income tax bands for employees: 0% up to CRC 918,000 (CRC 922,000 in 2025), 10% above that up to CRC 1,347,000, 15% up to CRC 2,364,000, 20% up to CRC 4,727,000 and 25% above. The monthly tax credits are CRC 1,710 per child and CRC 2,590 for a spouse.',employer:['Load the 2026 bands and credits into salary tax withholding from January 2026.','Apply the CRC 1,710 per-child and CRC 2,590 spouse credits where the employee claims them.'],employee:['The tax-free monthly salary threshold falls slightly from CRC 922,000 to CRC 918,000 because of the -0.38% CPI variation.'],note:'Source is an EY Central America tax alert dated 11 December 2025 (professional source); the Hacienda site was not retrievable. The 2026 tax period is the calendar year.',example:'',sourceUrl:'https://www.ey.com/es_ce/technical/tax/tax-alerts/costa-rica-ministerio-de-hacienda-establecio-los-tramos-del-impuesto-sobre-la-renta-para-el-periodo-fiscal-2026',sourceLabel:'Source: EY Central America - Costa Rica: Ministerio de Hacienda estableció los tramos del impuesto sobre la renta para el periodo fiscal 2026'}},
      {country:'ec',flag:'🇪🇨',name:'Ecuador',section:'ec-sbu',title:'Salario básico unificado USD 482 for 2026',effective:'2026-01-01',added:'2026-09-30',updated:'2026-10-03',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'The Consejo Nacional de Trabajo y Salarios agreed by consensus to set the 2026 unified basic wage at USD 482.',employer:['Pay at least USD 482 per month in 2026.'],employee:['Basic wage is USD 482 per month.'],note:'',example:'',sourceUrl:'https://www.trabajo.gob.ec/despues-de-casi-una-decada-hay-consenso-gobierno-empleadores-y-trabajadores-acuerdan-fijar-el-salario-basico-unificado-de-2026-en-usd-482-no-hay-imposicion-hay-union/',sourceLabel:'Source: Ministerio del Trabajo - Acuerdan fijar el Salario Básico Unificado de 2026 en USD 482'}},
      {country:'ec',flag:'🇪🇨',name:'Ecuador',section:'ec-income-tax-2026',title:'2026 personal income tax table: zero-rate band to USD 12,208',badge:'Tax year 2026',effective:'2026-01-01',added:'2026-09-30',updated:'2026-10-03',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'The 2026 personal income tax table taxes annual income up to USD 12,208 at 0%, with a top rate of 37% on income from USD 109,956.',employer:['Use the 2026 table when computing employee withholding.'],employee:['0% on annual income up to USD 12,208.','37% top rate from USD 109,956.'],note:'',example:'',sourceUrl:'https://taxsummaries.pwc.com/ecuador/individual/taxes-on-personal-income',sourceLabel:'Source: PwC Worldwide Tax Summaries - Ecuador, Individual, Taxes on personal income'}},
      {country:'ec',flag:'🇪🇨',name:'Ecuador',section:'ec-rdep-annex-2026',title:'RDEP withholding annex for 2025 due by 7 February 2026',badge:'Annual filing',effective:'2026-01',added:'2026-10-06',category:'reporting',impact:'medium',upcoming:false,detail:{lead:'The Tax Service (SRI) reminded employers, individuals and companies, that the Anexo de Retenciones en la Fuente bajo Relación de Dependencia for fiscal year 2025 must be filed by 7 February 2026, with the date set by the ninth digit of the RUC.',employer:['File the annex online with the SRI for each prior fiscal year, on the date set by the ninth RUC digit.','After filing, give each employee Form 107, the document supporting the withholdings made.'],employee:['Form 107 supports the personal income tax return.'],note:'The annex is annual, so the same cycle is expected for fiscal year 2026.',example:'',sourceUrl:'https://www.lexis.com.ec/noticias/empresas-deben-entregar-hasta-el-7-de-febrero-el-anexo-del-impuesto-a-la-renta-de-sus-trabajadores',sourceLabel:'Source: LEXIS Noticias - Empresas deben entregar hasta el 7 de febrero el anexo del Impuesto a la Renta'}},
      {country:'mx',flag:'🇲🇽',name:'Mexico',section:'mx-minimum-wage',title:'2026 minimum wages: 315.04 general, 440.87 northern border',effective:'2026-01-01',added:'2026-09-30',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'CONASAMI raised daily minimum wages from 1 January 2026.',employer:['General minimum wage: from 278.80 to 315.04 pesos per day (6.5% plus a 17.01-peso recovery amount).','Zona Libre de la Frontera Norte: from 419.88 to 440.87 pesos per day (5%).'],employee:['Professional minimum wages for 61 occupations rise in line with their zone.'],note:'',example:'',sourceUrl:'https://www.gob.mx/conasami/articulos/incremento-a-los-salarios-minimos-para-2026?idiom=es',sourceLabel:'Source: CONASAMI (gob.mx) - Incremento a los Salarios Mínimos para 2026'}},
      {country:'mx',flag:'🇲🇽',name:'Mexico',section:'mx-40-hour-week',title:'Working week cut from 48 to 40 hours, 2027-2030',effective:'2027-01-01',added:'2026-09-30',category:'payroll',impact:'high',upcoming:true,detail:{lead:'The reform reduces the maximum working week gradually: 46 hours in 2027, 44 in 2028, 42 in 2029 and 40 in 2030.',employer:['2026 is a transition period; the first reduction to 46 hours applies in 2027.','Overtime limit of up to 12 hours paid at double and 4 at triple.'],employee:['The reduction may not imply any reduction of salaries, benefits or other labour rights.','Minors cannot work overtime.'],note:'',example:'',sourceUrl:'https://www.gob.mx/stps/documentos/reduccion-de-la-jornada-laboral-a-40-horas-preguntas-frecuentes?state=published',sourceLabel:'Source: STPS (gob.mx) - Reducción de la jornada laboral a 40 horas: preguntas frecuentes'}},
      {country:'pe',flag:'🇵🇪',name:'Peru',section:'pe-rmv',title:'Minimum wage (RMV) rises to S/ 1,230, then S/ 1,300',effective:'2026-10-01',added:'2026-09-30',category:'payroll',impact:'medium',upcoming:true,detail:{lead:'Decreto Supremo Nº 015-2026-TR raises the RMV for private-sector workers from S/ 1,130.00 to S/ 1,300.00 in two tranches.',employer:['First tranche: RMV S/ 1,230.00 from 1 October 2026.','Second tranche of S/ 70.00 to be set by a further supreme decree in the first half of 2027.'],employee:['Private-sector minimum wage rises by S/ 170.00 in total.'],note:'',example:'S/ 1,130.00 + S/ 100.00 = S/ 1,230.00; + S/ 70.00 = S/ 1,300.00.',sourceUrl:'https://busquedas.elperuano.pe/dispositivo/EX/2559163-1',sourceLabel:'Source: El Peruano - Decreto Supremo que incrementa la Remuneración Mínima Vital'}},
      {country:'pe',flag:'🇵🇪',name:'Peru',section:'pe-uit-2026',title:'UIT set at S/ 5,500 for 2026',effective:'2026-01-01',added:'2026-09-30',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'Decreto Supremo N.º 301-2025-EF sets the 2026 UIT at S/ 5,500, up S/ 150 from S/ 5,350, affecting fifth-category (employment) income tax thresholds.',employer:['Fifth-category withholding threshold of 7 UIT = S/ 38,500.','Minimum for integral annual remuneration (RIA) agreements: S/ 11,000 (2 UIT).'],employee:['Additional personal deductible expenses up to S/ 16,500 (3 UIT).'],note:'',example:'7 x S/ 5,500 = S/ 38,500.',sourceUrl:'https://www.ey.com/es_pe/insights/tax/nuevo-valor-uit-como-impacta',sourceLabel:'Source: EY Perú - Nuevo valor de la UIT 2026: ¿cómo impacta este aumento a las empresas?'}},
      {country:'uy',flag:'🇺🇾',name:'Uruguay',section:'uy-smn',title:'National minimum wage $24.572, then $25.383 from July 2026',effective:'2026-07-01',added:'2026-09-30',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'Under the decree of 26 December 2025, the Salario Mínimo Nacional rose in two steps during 2026.',employer:['From 1 January 2026: $24.572 per month (4.1% increase).','From 1 July 2026: $25.383 per month (additional 3.3%).','Daily wage = monthly amount / 25; hourly wage = monthly amount / 200.'],employee:['Minimum monthly wage from July 2026: $25.383.'],note:'',example:'Hourly from July 2026: 25.383 / 200 = $126,92.',sourceUrl:'https://www.gub.uy/ministerio-trabajo-seguridad-social/comunicacion/noticias/salario-minimo-nacional-24572-desde-1o-enero-2026',sourceLabel:'Source: MTSS (gub.uy) - Salario Mínimo Nacional: $ 24.572 desde el 1.º de enero de 2026'}},
      {country:'uy',flag:'🇺🇾',name:'Uruguay',section:'uy-irpf-2026',title:'IRPF 2026 monthly withholding scale with BPC $6.864',effective:'2026-01',added:'2026-09-30',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'BPS Comunicado R 5/2026 sets the 2026 monthly IRPF values using a BPC of $6.864, effective January 2026.',employer:['Monthly scale: 0% up to $48.048 (7 BPC); 10% to $68.640; 15% to $102.960; 24% to $205.920; 25% to $343.200; 27% to $514.800; 31% to $789.360; 36% above.','Deduction rate: 14% for nominal income up to $102.960, 8% above.'],employee:['Monthly deduction per minor child: $11.440.'],note:'',example:'7 BPC = 7 x 6.864 = $48.048.',sourceUrl:'https://www.bps.gub.uy/23860/2026---comunicado-r-5---valores-escalas-irpf-2026.html',sourceLabel:'Source: BPS - Comunicado R 5/2026, Valores y escalas IRPF 2026'}},
      {country:'switzerland',flag:'🇨🇭',name:'Switzerland',section:'ch-geneva-minwage',title:'Geneva minimum wage rises to CHF 24.59/hour',effective:'2026-01-01',added:'2026-10-01',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'From 1 January 2026 the Geneva cantonal gross minimum hourly wage is CHF 24.59, up from CHF 24.48, indexed to the Geneva consumer price index.',employer:['Pay at least CHF 24.59 gross per hour to employees working in Geneva from 1 January 2026.','Agriculture and floriculture: separate minimum of CHF 18.07 per hour from 2026.'],employee:['Gross hourly minimum increases from CHF 24.48 to CHF 24.59.'],note:'The amount is adjusted annually to the cost of living based on the Geneva consumer price index.',example:'Increase per hour: CHF 24.59 - CHF 24.48 = CHF 0.11.',sourceUrl:'https://www.ge.ch/actualite/salaire-minimum-genevois-2026-etablira-2459-fr-heure-1-10-2025',sourceLabel:'Source: République et canton de Genève - Le salaire minimum genevois 2026 s\'établira à 24.59 fr. de l\'heure'}},
      {country:'switzerland',flag:'🇨🇭',name:'Switzerland',section:'ch-13th-ahv',title:'First 13th AHV old-age pension paid in December 2026',effective:'2026-12',added:'2026-10-01',category:'payroll',impact:'low',upcoming:true,detail:{lead:'The 13th AHV pension is paid for the first time in December 2026 to around 2.6 million pensioners, equal to one-twelfth of the old-age pensions paid during the year.',employer:['No change to AHV wage contribution rates is set out for its financing; Parliament approved a 0.4 percentage-point VAT increase from 2028, subject to a popular vote on 29 November 2026 (not yet enacted).'],employee:['Old-age pension recipients receive a supplement in December equal to one-twelfth of annual old-age pensions.'],note:'VAT financing still requires approval in the 29 November 2026 vote.',example:'',sourceUrl:'https://www.bsv.admin.ch/de/umsetzung-13-ahv-rente',sourceLabel:'Source: Federal Social Insurance Office (BSV) - Umsetzung 13. AHV-Rente'}},
      {country:'switzerland',flag:'🇨🇭',name:'Switzerland',section:'ch-socsec-2026',title:'2026 social insurance rates: AHV/IV/EO 10.6%, ALV 2.2% up to CHF 148,200',effective:'2026-01-01',added:'2026-10-01',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'For 2026 the AHV/IV/EO contribution totals 10.60% (5.30% each for employer and employee), and ALV is 1.10% each on income up to CHF 148,200.',employer:['AHV/IV/EO: 5.30% of salary (AHV 4.35%, IV 0.7%, EO 0.25%).','ALV: 1.10% on income up to CHF 148,200.','BVG: age-credit rates apply to the coordinated salary between CHF 26,460 and CHF 90,720.'],employee:['AHV/IV/EO: 5.30% (AHV 4.35%, IV 0.7%, EO 0.25%); ALV: 1.10% up to CHF 148,200.'],note:'',example:'Monthly salary CHF 8,000: AHV/IV/EO employee share 5.30% = CHF 424; ALV 1.10% = CHF 88.',sourceUrl:'https://sozialversicherungen.admin.ch/de/d/6877/download',sourceLabel:'Source: Federal Social Insurance Office (BSV) - Synoptische Tabelle 2026, Beitrags- und Prämiensätze'}},
      {country:'ae',flag:'🇦🇪',name:'United Arab Emirates',section:'ae-emirati-minwage',title:'AED 6,000 minimum monthly wage for Emiratis in the private sector',effective:'2026-01-01',added:'2026-10-01',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'MoHRE requires a minimum monthly wage of AED 6,000 for Emiratis employed in the private sector from 1 January 2026, with salaries of existing Emirati staff to be adjusted by 30 June 2026.',employer:['Apply the AED 6,000 monthly wage to Emirati work permits issued, renewed or amended from 1 January 2026.','Adjust salaries of Emiratis hired before 2026 to at least AED 6,000 by 30 June 2026.','From 1 July 2026, underpaid Emiratis are excluded from Emiratisation quota counts and new work permits may be suspended.'],employee:['Emirati private-sector employees are entitled to a minimum monthly wage of AED 6,000.'],note:'',example:'',sourceUrl:'https://kpmg.com/xx/en/our-insights/gms-flash-alert/2026/flash-alert-2026-006.html',sourceLabel:'Source: KPMG GMS Flash Alert 2026-006 - United Arab Emirates'}},
      {country:'ae',flag:'🇦🇪',name:'United Arab Emirates',section:'ae-emiratisation-2026',title:'Emiratisation H1 2026 target and AED 10,000 monthly contribution',badge:'Deadline 30 June 2026',effective:'2026-06-30',added:'2026-10-01',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'Private-sector companies with 50 or more employees had to add 1% Emiratis in skilled roles by 30 June 2026 (2% annual target); financial contributions apply from 1 July 2026.',employer:['Financial contribution from 1 July 2026: AED 10,000 per month (AED 120,000 per year) for each unfilled Emirati position.','Companies with outstanding Emiratisation results can join the Emiratisation Partners Club (discounts of up to 80% on MoHRE service fees).'],employee:[],note:'MoHRE directs employers to the Nafis platform for recruiting Emirati jobseekers.',example:'Two unfilled positions: 2 x AED 120,000 = AED 240,000 per year.',sourceUrl:'https://www.wam.ae/en/article/c0uqocb-mohre-reaffirms-june-deadline-for-private-sector',sourceLabel:'Source: WAM (Emirates News Agency) - MoHRE reaffirms June 30 deadline for H1 private sector Emiratisation targets'}},
      {country:'za',flag:'🇿🇦',name:'South Africa',section:'za-nmw-2026',title:'National Minimum Wage rises to R30.23 per hour',effective:'2026-03-01',added:'2026-10-01',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'Employment and Labour Minister Nomakhosazana Meth raised the National Minimum Wage from R28.79 to R30.23 for each ordinary hour worked, binding from 1 March 2026.',employer:['Pay at least R30.23 per ordinary hour from 1 March 2026.','EPWP workers: minimum rises from R15.16 to R16.62 per hour.'],employee:['Hourly minimum increases by R1.44.'],note:'',example:'8 ordinary hours x R30.23 = R241.84 per day.',sourceUrl:'https://www.sanews.gov.za/node/79404',sourceLabel:'Source: SAnews (GCIS) - National Minimum Wage to rise to R30.23 per hour from March'}},
      {country:'za',flag:'🇿🇦',name:'South Africa',section:'za-paye-2027',title:'PAYE brackets and rebates adjusted for 2027 tax year',effective:'2026-03-01',added:'2026-10-01',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'SARS rates for the 2027 tax year (1 March 2026 - 28 February 2027) start at 18% on taxable income up to R245 100 and reach 45% above R1 878 600.',employer:['Apply updated withholding tables from 1 March 2026.'],employee:['Primary rebate R17 820; secondary (65+) R9 765; tertiary (75+) R3 249.','Tax threshold under 65: R99 000.'],note:'',example:'',sourceUrl:'https://www.sars.gov.za/tax-rates/income-tax/rates-of-tax-for-individuals/',sourceLabel:'Source: SARS - Rates of Tax for Individuals'}},
      {country:'ng',flag:'🇳🇬',name:'Nigeria',section:'ng-paye-nta',title:'Nigeria Tax Act: new PAYE bands and rent relief',effective:'2026-01-01',added:'2026-10-01',category:'payroll',impact:'high',upcoming:false,detail:{lead:'The Nigeria Tax Act takes effect on 1 January 2026 with six bands: first N800,000 at 0%, then 15%, 18%, 21%, 23% and 25% above N50,000,000.',employer:['Recompute PAYE: next N2,200,000 at 15%, next N9,000,000 at 18%, next N13,000,000 at 21%, next N25,000,000 at 23%, above N50,000,000 at 25%.'],employee:['Consolidated relief allowance replaced by rent relief of 20% of annual rent, capped at N500,000.'],note:'',example:'Taxable income N3,000,000: N800,000 x 0% + N2,200,000 x 15% = N330,000.',sourceUrl:'https://taxsummaries.pwc.com/nigeria/individual/significant-developments',sourceLabel:'Source: PwC Worldwide Tax Summaries - Nigeria, Individual, Significant developments'}},
      {country:'ke',flag:'🇰🇪',name:'Kenya',section:'ke-nssf-2026',title:'NSSF maximum monthly contribution set at KES 6,480',effective:'2026-02-01',added:'2026-10-01',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'From 1 February 2026 employers deduct a maximum monthly NSSF contribution of KES 6,480 from employees and match the same amount.',employer:['Match employee NSSF deduction up to KES 6,480 per month.'],employee:['Maximum monthly NSSF deduction KES 6,480.'],note:'',example:'Maximum combined monthly contribution: KES 6,480 x 2 = KES 12,960.',sourceUrl:'https://taxsummaries.pwc.com/kenya/individual/other-taxes',sourceLabel:'Source: PwC Worldwide Tax Summaries - Kenya, Individual, Other taxes'}},
      {country:'ng',flag:'🇳🇬',name:'Nigeria',section:'ng-ntaa-annual-returns',title:'Edo State: employer annual tax returns due 31 January under NTAA 2025',effective:'2026-01-31',added:'2026-10-01',category:'reporting',impact:'medium',upcoming:false,detail:{lead:'Citing the Nigeria Tax Administration Act (NTAA) 2025, the Edo State Internal Revenue Service required employers to file 2026 annual tax returns not later than 31 January 2026.',employer:['Edo State employers file annual returns (Tax Forms H1 and H3) by 31 January 2026.','Non-compliance attracts an administrative penalty of N1,000,000 or imprisonment for a term not exceeding three years.'],employee:['Individual taxable persons file by 31 March 2026; late filing attracts N100,000 in the first month and N50,000 for each subsequent month.'],note:'This is an Edo State (EIRS) notice and applies to employers and taxable persons in Edo State; other states administer PAYE for their own residents.',example:'',sourceUrl:'https://eirs.gov.ng/notice-of-demand-for-employers-employees-to-file-annual-paye-individual-tax-returns/',sourceLabel:'Source: Edo State Internal Revenue Service - Notice of demand for employers and employees to file annual PAYE and individual tax returns'}},
      {country:'ke',flag:'🇰🇪',name:'Kenya',section:'ke-fa2026-gratuity',title:'Finance Act 2026: gratuity exemption limited to 31% of emoluments',effective:'2026-07-01',added:'2026-10-01',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'From 1 July 2026, gratuity qualifies for tax exemption only if the contract of service is for at least three continuous years (or an extension of a three-year contract) and the gratuity does not exceed 31% of emoluments earned in that period.',employer:['Confirm the contract runs at least three continuous years before treating gratuity as exempt in PAYE.','Tax any gratuity above 31% of emoluments for the contract period through PAYE.'],employee:['Gratuity within the 31% limit on qualifying three-year contracts is tax-exempt.'],note:'',example:'',sourceUrl:'https://www.kra.go.ke/finance-act-2026-what-it-means-for-you',sourceLabel:'Source: Kenya Revenue Authority - Finance Act 2026: what it means for you'}},
      {country:'ke',flag:'🇰🇪',name:'Kenya',section:'ke-fa2026-return-deadline',title:'Individual income tax returns due by end of fourth month',effective:'2027-01-01',added:'2026-10-01',category:'reporting',impact:'low',upcoming:true,detail:{lead:'From 1 January 2027, individual taxpayers will be required to file income tax returns by the last day of the fourth month after the end of the year of income.',employer:['Expect staff on calendar-year income to file by 30 April from 1 January 2027.'],employee:['File the annual individual return by the last day of the fourth month after the year of income ends (30 April for calendar-year filers).'],note:'',example:'',sourceUrl:'https://www.kra.go.ke/finance-act-2026-what-it-means-for-you',sourceLabel:'Source: Kenya Revenue Authority - Finance Act 2026: what it means for you'}},
      {country:'ug',flag:'🇺🇬',name:'Uganda',section:'ug-paye-2026-bands',title:'Income Tax (Amendment) Act 2026: PAYE tax-free threshold rises to UGX 335,000 a month',effective:'2026-07-01',added:'2026-10-06',category:'payroll',impact:'high',upcoming:false,detail:{lead:'The Income Tax (Amendment) Act 2026, assented to on 20 August 2026, applies from 1 July 2026 and raises the resident-individual tax-free threshold from UGX 2,820,000 to UGX 4,020,000 a year (UGX 235,000 to UGX 335,000 a month) and adds a 25% band before the 30% rate.',employer:['Apply the new annual scale: nil to UGX 4,020,000; 20% to UGX 4,920,000; UGX 180,000 plus 25% to UGX 5,820,000; UGX 405,000 plus 30% above that; plus 10% on income over UGX 120,000,000.','Re-run July and August 2026 payroll on the new bands and reconcile any over-withheld PAYE with the Uganda Revenue Authority.'],employee:['Employees earning up to UGX 335,000 a month no longer pay PAYE; those above UGX 5,820,000 a year save UGX 165,000 a year.'],note:'The Act was assented to after the start date, so it applies retroactively to 1 July 2026. Source is a Ugandan law firm (KAA), matched by MRT Tax and by an Onyango Advocates summary of the same bands; the Act text and URA page could not be read.',example:'Annual chargeable income UGX 4,920,000: 20% x UGX 900,000 = UGX 180,000.',sourceUrl:'https://www.kaa.co.ug/kaa-tax-alert-income-tax-amendment-act-2026/',sourceLabel:'Source: Kampala Associated Advocates - KAA Tax Alert: Income Tax (Amendment) Act 2026'}},
      {country:'tz',flag:'🇹🇿',name:'Tanzania',section:'tz-minwage-2026',title:'New private-sector minimum wage order in force from 1 January 2026',effective:'2026-01-01',added:'2026-10-06',category:'payroll',impact:'high',upcoming:false,detail:{lead:'Government Notice No. 605A of 2025 (Labour Institutions (Minimum Wage for Private Sector) Order) took effect on 1 January 2026 and replaced the 2022 wage order with new sector and sub-sector minimum wages.',employer:['Raise any private-sector pay below the new sector minimum; employers paying more must keep paying the higher wage.','Employers in sectors with no wage board must pay at least TZS 175,000 a month, up from TZS 150,000.'],employee:['Employees also gain a leave travel allowance once every two years of continuous service and a subsistence allowance when sent to work outside their workstation.'],note:'Rates differ by sector and sub-sector; check the table in the Wage Order for the exact minimum. Source is a law firm (Clyde & Co), corroborated by ALN Tanzania (published 13 October 2025) and Daily News; the Government Notice itself could not be reached.',example:'',sourceUrl:'https://www.clydeco.com/en/insights/2026/02/introduction-of-a-new-wage-order-in-tanzania',sourceLabel:'Source: Clyde & Co - Introduction of a New Wage Order in Tanzania'}},
      {country:'gh',flag:'🇬🇭',name:'Ghana',section:'gh-minwage-2026',title:'National daily minimum wage rises to GHS 21.77',effective:'2026-01-01',added:'2026-10-06',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'The National Tripartite Committee raised Ghana\'s national daily minimum wage by nine per cent, from GHS 19.97 to GHS 21.77, for 1 January to 31 December 2026.',employer:['Check that no employee is paid below GHS 21.77 per day.','The SSNIT minimum insurable earning for 2026 also rose, following the minimum wage increase.'],employee:['Statutory floor for daily pay is GHS 21.77 from 1 January 2026.'],note:'Announced by the National Tripartite Committee (Finance Minister\'s statement reported by the Ghanaian Times, 11 November 2025) as valid 1 January to 31 December 2026; the Fair Wages and Salaries Commission notice was not read. SSNIT\'s 2026 notice confirms the minimum wage rose but does not state the amount.',example:'',sourceUrl:'https://ghanaiantimes.com.gh/govt-approves-9-pay-rise-for-public-sector-workers-minimum-wage-up-to-gh%C2%A221-77/',sourceLabel:'Source: Ghanaian Times - Govt approves 9% pay rise for public sector workers, minimum wage up to GH¢21.77'}},
      {country:'gh',flag:'🇬🇭',name:'Ghana',section:'gh-paye-act1178',title:'Income Tax (Amendment) Act 2026: new monthly PAYE bands, first GHS 588 tax-free',effective:'2026-09-01',added:'2026-10-06',category:'payroll',impact:'high',upcoming:false,detail:{lead:'GRA says the Income Tax (Amendment) Act 2026 (Act 1178) took effect on 1 September 2026 and published new monthly PAYE bands for resident individuals: first GHS 588 at 0%, then 5%, 10%, 17.5%, 25%, 30% and 35% on income above GHS 50,000 a month.',employer:['Recompute PAYE with the monthly bands: next GHS 80 at 5%, next GHS 100 at 10%, next GHS 2,900 at 17.5%, next GHS 16,000 at 25%, next GHS 30,332 at 30%, above GHS 50,000 at 35%.','Apply the new bands to payroll from 1 September 2026 and correct any September PAYE already run on the old bands.'],employee:['Annual equivalent: first GHS 7,056 is tax-free.'],note:'Effective date and bands come from GRA\'s own notice on Act 1178 and its PAYE page (year of assessment 2026); the Act text was not read, so check the Act and any GRA guidance for transitional treatment.',example:'Monthly chargeable income GHS 1,000: GHS 80 x 5% + GHS 100 x 10% + GHS 232 x 17.5% = GHS 54.60.',sourceUrl:'https://gra.gov.gh/domestic-tax/tax-types/paye/',sourceLabel:'Source: Ghana Revenue Authority - Pay As You Earn (PAYE)'}},
      {country:'gh',flag:'🇬🇭',name:'Ghana',section:'gh-ssnit-2026',title:'SSNIT maximum monthly contribution raised to GHS 9,315',effective:'2026-01-01',added:'2026-10-06',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'From 1 January 2026 the maximum insurable earning for SSNIT is GHS 69,000 (up from GHS 61,000) and the minimum is GHS 587.80 (up from GHS 539.19), so the maximum and minimum contributions payable are GHS 9,315.00 and GHS 79.40.',employer:['Update the SSNIT insurable earnings cap to GHS 69,000 and the floor to GHS 587.80 in payroll.','Pay the right contributions: maximum GHS 9,315.00 and minimum GHS 79.40 from 1 January 2026.'],employee:['Pensionable earnings above GHS 69,000 do not attract further SSNIT contributions in 2026.'],note:'SSNIT says the cap was adjusted with the National Pensions Regulatory Authority under section 63(3) of the National Pensions Act 2008 (Act 766), and the floor followed the rise in the National Daily Minimum Wage.',example:'',sourceUrl:'https://www.ssnit.org.gh/wp-content/uploads/2026/01/Public-Notice-Min-Max-Insurable.pdf',sourceLabel:'Source: SSNIT - Public Notice: Maximum and Minimum Insurable Earnings for 2026'}},
      {country:'id',flag:'🇮🇩',name:'Indonesia',section:'id-pp49-minwage',title:'Government Regulation 49/2025 changes the minimum wage formula for 2026',badge:'Applies to 2026 wages',effective:'2026',added:'2026-10-01',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'Government Regulation No. 49 of 2025 replaced the previous wage-setting framework after a Constitutional Court decision. The alpha coefficient used in the formula now ranges between 0.5 and 0.9, compared with the previous cap of 0.3, and sectoral minimum wages have been reintroduced in some regions.',employer:['Check the 2026 provincial (UMP) and regency/city (UMK) minimum wage decrees for each work location.','Check whether a sectoral minimum wage applies to your industry (for example construction, energy, high-tech manufacturing); it can exceed the standard UMP or UMK.'],employee:['Minimum wage floors for 2026 are set under the new formula with a higher alpha range.'],note:'',example:'',sourceUrl:'https://www.rsm.global/indonesia/en/node/415',sourceLabel:'Source: RSM Indonesia - PP 49/2025 minimum wage regulation'}},
      {country:'th',flag:'🇹🇭',name:'Thailand',section:'th-sso-ceiling',title:'Social Security Fund wage ceiling rises to THB 17,500 (max contribution THB 875)',effective:'2026-01-01',added:'2026-10-01',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'From 1 January 2026 the maximum monthly wage used to calculate Social Security Fund contributions is THB 17,500 for 2026-2028, rising to THB 20,000 for 2029-2031 and THB 23,000 from 2032.',employer:['Calculate employer contributions on wages up to THB 17,500; the maximum is THB 875 per month in 2026-2028 (THB 1,000 in 2029-2031; THB 1,150 from 2032).','Update payroll systems for the new base.'],employee:['Employee maximum contribution is also THB 875 per month in 2026-2028.'],note:'',example:'',sourceUrl:'https://kpmg.com/th/en/home/insights/2026/01/th-tax-news-flash-issue-157.html',sourceLabel:'Source: KPMG Thailand - Tax News Flash Issue 157 (January 2026)'}},
      {country:'vn',flag:'🇻🇳',name:'Vietnam',section:'vn-pit-brackets-2026',title:'Resident employment income taxed in five brackets (5% to 35%) for 2026',badge:'2026 tax year',effective:'2026-01-01',added:'2026-10-01',updated:'2026-10-03',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'For 2026 Vietnam taxes resident employment income at five progressive rates: 5% up to VND 120 million a year, 10% from 120 to 360 million, 20% from 360 to 720 million, 30% from 720 to 1,200 million and 35% above 1,200 million.',employer:['Update PIT withholding tables to the five-bracket schedule.'],employee:['Annual brackets equate to monthly bands of VND 10, 30, 60 and 100 million.'],note:'',example:'VND 120 million / 12 = VND 10 million per month at the 5% top of the first band.',sourceUrl:'https://taxsummaries.pwc.com/vietnam/individual/taxes-on-personal-income',sourceLabel:'Source: PwC Worldwide Tax Summaries - Vietnam, Individual, Taxes on personal income'}},
      {country:'vn',flag:'🇻🇳',name:'Vietnam',section:'vn-pit-deductions-2026',title:'Personal deduction VND 15.5 million and dependant deduction VND 6.2 million a month',badge:'2026 tax year',effective:'2026-01-01',added:'2026-10-01',updated:'2026-10-03',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'Resident individuals get an automatic personal deduction of VND 15.5 million per month, and VND 6.2 million per registered dependant per month.',employer:['Apply VND 15.5 million personal deduction in monthly withholding.','Apply VND 6.2 million per dependant where the employee has registered qualifying dependants with documentation.'],employee:['Register dependants with supporting documents to claim the deduction.'],note:'',example:'An employee with two registered dependants: 15.5 + 2 x 6.2 = VND 27.9 million of deductions per month.',sourceUrl:'https://taxsummaries.pwc.com/vietnam/individual/deductions',sourceLabel:'Source: PwC Worldwide Tax Summaries - Vietnam, Individual, Deductions'}},
      {country:'in',flag:'🇮🇳',name:'India',section:'in-labour-codes-2025',title:'Four Labour Codes in force from 21 November 2025',effective:'2025-11-21',added:'2026-10-01',category:'payroll',impact:'high',upcoming:false,detail:{lead:'The Code on Wages 2019, the Industrial Relations Code 2020, the Code on Social Security 2020 and the Occupational Safety, Health and Working Conditions Code 2020 took effect on 21 November 2025. They introduce a standardised definition of wages and extend gratuity to fixed-term employees after one year of service (against five years for full-time employees).',employer:['Review salary structures and contracts against the new uniform definition of wages.','Provide gratuity to fixed-term employees who complete one year of service.','Watch for final central and state rules, which were yet to be notified.'],employee:['Fixed-term employees become eligible for gratuity after one year of service.'],note:'The Employees\' Provident Funds and Miscellaneous Provisions Act, 1952 had not yet been repealed per the cited source; final central and state rules were still to be notified at the time of that article (December 2025).',example:'',sourceUrl:'https://kpmg.com/in/en/blogs/2025/12/implementation-of-labour-codes-what-changes-and-road-ahead.html',sourceLabel:'Source: KPMG India - Implementation of labour codes: What changes and road ahead'}},
      {country:'in',flag:'🇮🇳',name:'India',section:'in-income-tax-act-2025',title:'Income-tax Act, 2025 replaces the 1961 Act from 1 April 2026',effective:'2026-04-01',added:'2026-10-01',category:'reporting',impact:'medium',upcoming:false,detail:{lead:'The Income-tax Act, 2025 applies to tax years starting from 1 April 2026 and completely replaces the old law. For individuals with business income whose accounts do not require audit, the return due date is 31 August of the year immediately following the relevant year, and revised returns may be filed by 31 March.',employer:['Update payroll and tax-filing calendars and references for tax years starting 1 April 2026.'],employee:['Individuals with business income and no audit requirement file returns by 31 August following the relevant year.'],note:'Summary is from PwC Worldwide Tax Summaries; the government site was not used.',example:'',sourceUrl:'https://taxsummaries.pwc.com/india/individual/significant-developments',sourceLabel:'Source: PwC Worldwide Tax Summaries - India, Individual - Significant developments'}},
      {country:'tr',flag:'🇹🇷',name:'Turkey',section:'tr-income-tax-brackets-2026',title:'Employment income tax brackets for 2026',effective:'2026-01-01',added:'2026-10-01',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'For 2026 the progressive employment income tax scale runs from 15% up to 40% on annual taxable income above TRY 5,300,000.',employer:['Apply the 2026 employment income scale when calculating income tax on employee earnings.'],employee:['Up to TRY 190,000: 15%.','TRY 190,000 to 400,000: TRY 28,500 plus 20% of the excess.','TRY 400,000 to 1,500,000: TRY 70,500 plus 27% of the excess.','TRY 1,500,000 to 5,300,000: TRY 367,500 plus 35% of the excess.','Over TRY 5,300,000: TRY 1,697,500 plus 40% of the excess.'],note:'Non-employment income is taxed on different bracket thresholds.',example:'Annual taxable income of TRY 300,000: 28,500 + (300,000 - 190,000) x 20% = TRY 50,500.',sourceUrl:'https://taxsummaries.pwc.com/turkey/individual/taxes-on-personal-income',sourceLabel:'Source: PwC Worldwide Tax Summaries - Turkey, Individual, Taxes on personal income'}},
      {country:'pk',flag:'🇵🇰',name:'Pakistan',section:'pk-salary-slabs-2026',title:'New salaried-individual tax slabs with 35% top rate from Rs 7 million',effective:'2026-07-01',added:'2026-10-01',category:'payroll',impact:'medium',upcoming:false,detail:{lead:'The Finance Act 2026, enacted on 27 June 2026, reduced tax rates for salaried individuals in the First Schedule with effect from 1 July 2026. Income up to Rs 600,000 is untaxed, and the 35% rate now applies only to taxable income above Rs 7,000,000 (previously it applied from Rs 4,100,000).',employer:['Update salary withholding (section 149) to the new slabs: 1% over Rs 600,000; Rs 6,000 + 11% over Rs 1,200,000; Rs 116,000 + 20% over Rs 2,200,000; Rs 316,000 + 25% over Rs 3,200,000; Rs 541,000 + 29% over Rs 4,100,000; Rs 976,000 + 32% over Rs 5,600,000; Rs 1,424,000 + 35% over Rs 7,000,000.'],employee:['Tax falls for salaries above Rs 2,200,000 a year; the surcharge no longer applies to income taxed under the salaried slabs.'],note:'The same slabs appear in the withholding rate card section of the KPMG brief (section 149, salary). KPMG states amendments are effective from 01 July 2026 unless otherwise provided.',example:'Annual salary of Rs 4,100,000: tax is Rs 541,000 under the new slabs (Rs 616,000 under the previous rates).',sourceUrl:'https://assets.kpmg.com/content/dam/kpmgsites/pk/pdf/2026/07/A%20Brief%20of%20Finance%20Act%202026.pdf.coredownload.inline.pdf',sourceLabel:'Source: KPMG Taseer Hadi & Co. - A Brief of Finance Act, 2026 (July 2026)'}},
      {country:'pk',flag:'🇵🇰',name:'Pakistan',section:'pk-bps-2026',title:'Federal civil-servant Basic Pay Scales 2026 and 7% ad-hoc relief allowance',effective:'2026-07-01',added:'2026-10-01',category:'payroll',impact:'low',upcoming:false,detail:{lead:'This applies to federal government civil servants only and is not a private-sector payroll rule. By Office Memorandum dated 21 July 2026, the Ministry of Finance approved revised Basic Pay Scales and allowances effective 1 July 2026 for federal civil employees paid from civil and defence estimates. BPS-2026 replaces BPS-2022 and merges the earlier ad-hoc relief allowances; a new Ad-hoc Relief Allowance-2026 of 7% of running basic pay applies from 1 July 2026 until further orders.',employer:['Federal payroll units: fix pay in BPS-2026 point to point from the stage held on 30 June 2026.','Stop the Ad-hoc Relief Allowances of 2022 (15%) and 2025 (10%), which cease on 1 July 2026, and pay the 7% allowance instead.','Annual increment remains admissible on 1 December each year.'],employee:['The Ad-hoc Relief Allowance-2026 is subject to income tax.'],note:'Applies to federal government civil employees, not to the private sector.',example:'',sourceUrl:'https://www.finance.gov.pk/circulars/REVISION_OF_BASIC_PAY_SCALES_2026.pdf',sourceLabel:'Source: Government of Pakistan Ministry of Finance - Office Memorandum, Revision of Basic Pay Scales and Allowances of Civil Servants 2026'}},
    ];

    // Date the sources were last checked (also read by scripts/build-pages.mjs and scripts/validate.mjs).
    const LAST_VERIFIED = new Date('2026-10-01T00:00:00Z');

    // "New" and "Updated" labels: an entry is labelled when it was added (or, for "Updated", given an
    // `updated` date) in the FRESH_DAYS up to and including LAST_VERIFIED (later dates are not labelled). Entries already on the site at launch
    // (on or before FRESH_LABELS_AFTER) are never labelled. scripts/build-pages.mjs applies the same rule.
    const FRESH_LABELS_AFTER = '2026-10-03';
    const FRESH_DAYS = 14;

    // Payroll impact rating (also used by scripts/build-pages.mjs; keep the wording in step).
    const IMPACT = {
      high: 'High: a new process, system, filing or calculation method',
      medium: 'Medium: new rates, thresholds or bands to load and check',
      low: 'Low: little or no payroll configuration needed'
    };
    function freshnessOf(item){
      const from = new Date(LAST_VERIFIED.getTime() - (FRESH_DAYS - 1) * 864e5).toISOString().slice(0, 10);
      const to = LAST_VERIFIED.toISOString().slice(0, 10);
      const recent = d => typeof d === 'string' && d > FRESH_LABELS_AFTER && d >= from && d <= to;
      if(recent(item.added)) return 'new';
      if(recent(item.updated)) return 'updated';
      return null;
    }

    // UI Functions
    function showView(viewId){
      document.querySelectorAll('[id^="view-"]').forEach(el => el.classList.add('hidden'));
      document.getElementById(viewId).classList.remove('hidden');
      document.querySelectorAll('.nav-link').forEach(link => link.classList.remove('active'));
      const navLink = document.querySelector(`.nav-link[data-view="${viewId}"]`);
      if(navLink) navLink.classList.add('active');

      if(viewId === 'view-changelog') renderChangelog();
    }

    function showChangelogNav(){
      document.querySelectorAll('[id^="view-"]').forEach(el => el.classList.add('hidden'));
      document.getElementById('view-changelog').classList.remove('hidden');
      document.querySelectorAll('.nav-link').forEach(link => link.classList.remove('active'));
      const changelogLink = document.querySelector('.nav-link[data-view="view-changelog"]');
      if(changelogLink) changelogLink.classList.add('active');
    }

    function goToCountry(country){
      if(!isKnownCountry(country)) return;
      state = {countries: [country], region: countryToRegion[country] || null, filter: 'all', when: 'all', search: ''};
      showChangelogNav();
      updateState();
      window.scrollTo({top: 0, behavior: 'smooth'});
    }

    function performSearch(term){
      const q = (term || '').trim();
      if(!q) return;
      state.search = q.toLowerCase();
      showChangelogNav();
      updateState();
      window.scrollTo({top: 0, behavior: 'smooth'});
    }

    let currentChangelogItems = [];
    // Category labels come from the shared map in filters.js; only the non-category filter is added here.
    const FILTER_LABELS = Object.assign({}, PayrollFilters.CATEGORY_LABELS, {'high-impact': 'High impact'});
    // Changelog filter state. Mirrored in the address bar only (never in browser storage).
    let state = {countries: [], region: null, filter: 'all', when: 'all', search: ''};

    // Write the state to the address bar: omit empty params; bare path when nothing is set.
    function writeUrl(){
      const parts = [];
      if(state.countries.length) parts.push('countries=' + PayrollFilters.serializeCountries(state.countries));
      if(state.region) parts.push('region=' + encodeURIComponent(state.region));
      if(state.filter && state.filter !== 'all') parts.push('filter=' + encodeURIComponent(state.filter));
      if(state.when && state.when !== 'all') parts.push('when=' + encodeURIComponent(state.when));
      if(state.search) parts.push('q=' + encodeURIComponent(state.search));
      const url = window.location.pathname + (parts.length ? '?' + parts.join('&') : '') + (window.location.hash || '');
      try { history.replaceState(null, '', url); } catch(e) { /* ignore (e.g. file://) */ }
    }

    function updateState(){
      renderChangelog();
      writeUrl();
    }

    // Country to region mapping
    const countryToRegion = {
      'norway': 'europe', 'finland': 'europe', 'sweden': 'europe', 'denmark': 'europe', 'czechia': 'europe',
      'uk': 'europe', 'belgium': 'europe', 'germany': 'europe', 'greece': 'europe', 'ireland': 'europe',
      'netherlands': 'europe', 'austria': 'europe', 'hungary': 'europe', 'france': 'europe', 'spain': 'europe',
      'portugal': 'europe', 'poland': 'europe', 'lithuania': 'europe', 'estonia': 'europe', 'slovenia': 'europe',
      'slovakia': 'europe', 'romania': 'europe', 'bulgaria': 'europe', 'latvia': 'europe', 'cyprus': 'europe',
      'malta': 'europe', 'luxembourg': 'europe', 'italy': 'europe', 'croatia': 'europe', 'switzerland': 'europe',
      'in': 'apac', 'jp': 'apac', 'sg': 'apac', 'au': 'apac', 'kr': 'apac', 'th': 'apac', 'id': 'apac', 'ph': 'apac', 'my': 'apac', 'vn': 'apac',
      'cn': 'apac', 'tw': 'apac', 'nz': 'apac', 'hk': 'apac', 'bd': 'apac',
      'sa': 'menat', 'eg': 'menat', 'il': 'menat', 'tr': 'menat', 'ma': 'menat', 'tn': 'menat', 'lb': 'menat', 'pk': 'menat',
      'qa': 'menat', 'kw': 'menat', 'bh': 'menat', 'om': 'menat', 'ae': 'menat',
      'br': 'latam', 'mx': 'latam', 'ar': 'latam', 'co': 'latam', 'cl': 'latam', 'pe': 'latam', 'ec': 'latam', 'uy': 'latam', 'cr': 'latam',
      'pa': 'latam', 'do': 'latam', 'gt': 'latam', 'bo': 'latam', 'sv': 'latam',
      'za': 'africa', 'ng': 'africa', 'ke': 'africa', 'gh': 'africa', 'tz': 'africa', 'ug': 'africa'
    };

    function renderRegionCoverage(){
      const el = document.getElementById('region-coverage');
      if(!el) return;
      const counts = {europe: 0, apac: 0, menat: 0, latam: 0, africa: 0};
      Object.values(countryToRegion).forEach(r => { if(counts[r] !== undefined) counts[r]++; });
      const regions = [
        {key: 'europe', label: 'Europe', blurb: 'Western, Northern, Southern, and Eastern Europe.'},
        {key: 'apac', label: 'APAC', blurb: 'Asia-Pacific, from India to Australia.'},
        {key: 'menat', label: 'MENAT', blurb: 'Middle East, North Africa, and Turkey.'},
        {key: 'latam', label: 'LATAM', blurb: 'Latin America, from Mexico to the Southern Cone.'},
        {key: 'africa', label: 'Africa', blurb: 'Sub-Saharan Africa, from Nigeria to South Africa.'}
      ];
      el.innerHTML = regions.map(r => `
        <div class="region-coverage-card" data-reveal-item>
          <div class="icon"><img src="design/assets/icons/globe-bold.svg" width="24" height="24" alt=""></div>
          <span class="region-coverage-count">${counts[r.key]}</span>
          <h3><span class="swatch swatch-${r.key}"></span>${r.label}</h3>
          <p>${escapeHtml(r.blurb)}</p>
        </div>
      `).join('');
    }

    const COUNTRY_ISO = {
      austria:'040', belgium:'056', bulgaria:'100', croatia:'191', cyprus:'196', czechia:'203', denmark:'208', estonia:'233',
      finland:'246', france:'250', germany:'276', greece:'300', hungary:'348', ireland:'372', italy:'380', latvia:'428',
      lithuania:'440', luxembourg:'442', malta:'470', netherlands:'528', norway:'578', poland:'616', portugal:'620',
      romania:'642', slovakia:'703', slovenia:'705', spain:'724', sweden:'752', uk:'826',
      au:'036', id:'360', in:'356', jp:'392', kr:'410', my:'458', ph:'608', sg:'702', th:'764', vn:'704',
      cn:'156', tw:'158', nz:'554', hk:'344', bd:'050',
      sa:'682', eg:'818', il:'376', tr:'792', ma:'504', tn:'788', lb:'422', pk:'586', qa:'634', kw:'414', bh:'048', om:'512',
      br:'076', mx:'484', ar:'032', co:'170', cl:'152', pe:'604', ec:'218', uy:'858', cr:'188', pa:'591', do:'214',
      gt:'320', bo:'068', sv:'222',
      switzerland:'756', ae:'784', za:'710', ng:'566', ke:'404', gh:'288', tz:'834', ug:'800'
    };
    // Too small for the 110m outline data; drawn as dots instead.
    const SMALL_COUNTRY_POINTS = { malta:[14.4,35.9], sg:[103.82,1.35], hk:[114.17,22.32], bh:[50.55,26.07] };

    function entriesText(n){ return n === 1 ? '1 entry' : `${n} entries`; }

    // Accessible list alternative to the map: every covered country, most entries first.
    function renderCoverageList(){
      const el = document.getElementById('coverage-list');
      if(!el) return;
      const counts = PayrollFilters.coverageDepth(CHANGES);
      const info = {};
      CHANGES.forEach(c => { if(!info[c.country]) info[c.country] = {name: c.name, flag: c.flag}; });
      const rows = Object.keys(countryToRegion).filter(code => info[code]).map(code => ({code, n: counts[code] || 0, name: info[code].name, flag: info[code].flag || ''}));
      rows.sort((x, y) => y.n - x.n || x.name.localeCompare(y.name));
      el.innerHTML = rows.map(r => `<li><a href="countries/${escapeHtml(PayrollFilters.slugify(r.name))}.html">${escapeHtml(r.flag)} ${escapeHtml(r.name)} — ${entriesText(r.n)}</a></li>`).join('');
    }

    async function renderCoverageMap(){
      const box = document.getElementById('coverage-map');
      if(!box) return;
      if(!window.d3 || !window.topojson){ box.hidden = true; return; }
      let world;
      try {
        world = await d3.json('vendor/countries-110m.json');
      } catch(e){ box.hidden = true; return; }
      const tip = document.getElementById('coverage-map-tip');
      const back = document.getElementById('coverage-map-back');
      const names = {};
      document.querySelectorAll('select.country-selector option').forEach(o => {
        if(o.value) names[o.value] = o.textContent.replace(/^\S+\s/, '').trim();
      });
      const counts = PayrollFilters.coverageDepth(CHANGES);
      const depthClass = code => PayrollFilters.depthClass(counts[code] || 0);
      const byIso = {};
      Object.entries(COUNTRY_ISO).forEach(([code, iso]) => { if(countryToRegion[code]) byIso[iso] = code; });

      const width = 960, height = 470;
      const projection = d3.geoNaturalEarth1().fitExtent([[8, 8], [width - 8, height - 8]], {type: 'Sphere'});
      const path = d3.geoPath(projection);
      const features = topojson.feature(world, world.objects.countries).features
        .filter(f => f.properties.name !== 'Antarctica');
      const svg = d3.select(box).insert('svg', ':first-child')
        .attr('viewBox', `0 0 ${width} ${height}`).attr('preserveAspectRatio', 'xMidYMid meet');
      const layer = svg.append('g');

      let lastPointer = 'mouse';
      box.addEventListener('pointerdown', e => { lastPointer = e.pointerType; }, true);
      const touch = () => lastPointer === 'touch' || lastPointer === 'pen' || window.matchMedia('(hover: none)').matches;
      const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const narrow = () => box.clientWidth < 700;
      let k = 1, focusedRegion = null, tipCode = null;

      const entriesLabel = code => `${names[code] || code}, ${entriesText(counts[code] || 0)}`;
      const label = entriesLabel;
      const placeTip = (x, y, code) => {
        const r = box.getBoundingClientRect();
        tip.textContent = touch() ? label(code) + ' · tap again to open' : label(code);
        tip.hidden = false;
        const half = tip.offsetWidth / 2 + 6;
        tip.style.left = Math.min(Math.max(x - r.left, half), r.width - half) + 'px';
        tip.style.top = Math.max(y - r.top, 34) + 'px';
        tip.hidden = false;
        tipCode = code;
      };
      const tipAtEl = (el, code) => { const b = el.getBoundingClientRect(); placeTip(b.left + b.width / 2, b.top + b.height / 2, code); };
      const hideTip = () => { tip.hidden = true; tipCode = null; };

      const covered = features.filter(f => byIso[f.id]).map(f => ({f, code: byIso[f.id]}));
      const drawn = new Set(covered.map(d => d.code));
      const points = Object.entries(SMALL_COUNTRY_POINTS)
        .filter(([code]) => countryToRegion[code] && !drawn.has(code))
        .map(([code, lonlat]) => ({code, xy: projection(lonlat)}));
      // Tiny countries get an invisible, constant-size tap target at their centroid.
      const tiny = covered.filter(d => { const [[x0, y0], [x1, y1]] = path.bounds(d.f); return Math.max(x1 - x0, y1 - y0) < 14; })
        .map(d => ({code: d.code, xy: path.centroid(d.f)}));

      // Overseas territories (e.g. French Guiana) would stretch a region's box; use each country's largest polygon.
      const mainlandBounds = f => {
        if(f.geometry.type !== 'MultiPolygon') return path.bounds(f);
        const polys = f.geometry.coordinates.map(c => ({type: 'Polygon', coordinates: c}));
        return path.bounds(polys.reduce((a, b) => path.area(b) > path.area(a) ? b : a));
      };

      function zoomTo(region){
        focusedRegion = region;
        let t = d3.zoomIdentity;
        if(region){
          const xs = [], ys = [];
          covered.filter(d => countryToRegion[d.code] === region).forEach(d => { const b = mainlandBounds(d.f); xs.push(b[0][0], b[1][0]); ys.push(b[0][1], b[1][1]); });
          points.filter(d => countryToRegion[d.code] === region).forEach(d => { xs.push(d.xy[0]); ys.push(d.xy[1]); });
          const x0 = Math.min(...xs), x1 = Math.max(...xs), y0 = Math.min(...ys), y1 = Math.max(...ys);
          const kk = Math.min(10, 0.9 / Math.max((x1 - x0) / width, (y1 - y0) / height));
          t = d3.zoomIdentity.translate(width / 2, height / 2).scale(kk).translate(-(x0 + x1) / 2, -(y0 + y1) / 2);
        }
        k = t.k;
        back.hidden = !region;
        hideTip();
        (reduceMotion ? layer : layer.transition().duration(600)).attr('transform', t.toString());
        sizeMarkers();
      }

      function sizeMarkers(){
        const unit = width / Math.max(box.clientWidth, 1) / k;
        layer.selectAll('.dot').attr('r', Math.max(4 / k, 5 * unit));
        layer.selectAll('.hit').attr('r', 11 * unit);
      }

      function activate(el, code){
        if(!touch()){ goToCountry(code); return; }
        const region = countryToRegion[code];
        if(narrow() && focusedRegion !== region){ zoomTo(region); return; }
        if(tipCode === code){ goToCountry(code); return; }
        tipAtEl(el, code);
      }

      const wire = sel => sel
        .attr('tabindex', 0).attr('role', 'link')
        .attr('aria-label', d => label(d.code))
        .on('mousemove', (e, d) => { if(!touch()) placeTip(e.clientX, e.clientY, d.code); })
        .on('mouseleave', () => { if(!touch()) hideTip(); })
        .on('focus', (e, d) => { if(!touch()) tipAtEl(e.currentTarget, d.code); })
        .on('blur', () => { if(!touch()) hideTip(); })
        .on('click', (e, d) => { e.stopPropagation(); activate(e.currentTarget, d.code); })
        .on('keydown', (e, d) => { if(e.key === 'Enter' || e.key === ' '){ e.preventDefault(); goToCountry(d.code); } });

      layer.append('g').selectAll('path')
        .data(features.filter(f => !byIso[f.id]))
        .join('path').attr('class', 'land').attr('d', path);

      wire(layer.append('g').selectAll('path')
        .data(covered)
        .join('path').attr('class', d => `covered ${depthClass(d.code)}`).attr('d', d => path(d.f)));

      wire(layer.append('g').selectAll('circle')
        .data(points)
        .join('circle').attr('class', d => `dot ${depthClass(d.code)}`)
        .attr('cx', d => d.xy[0]).attr('cy', d => d.xy[1]));

      wire(layer.append('g').selectAll('circle')
        .data(tiny.concat(points))
        .join('circle').attr('class', 'hit')
        .attr('cx', d => d.xy[0]).attr('cy', d => d.xy[1]));

      svg.on('click', () => hideTip());
      back.addEventListener('click', () => zoomTo(null));
      let resizeTimer;
      window.addEventListener('resize', () => { clearTimeout(resizeTimer); resizeTimer = setTimeout(sizeMarkers, 150); });
      sizeMarkers();
    }

    function renderProofLine(){
      const upcoming = CHANGES.filter(c => c.upcoming).length;
      const setText = (id, value) => { const el = document.getElementById(id); if(el) el.textContent = value; };
      setText('proof-line', `${CHANGES.length} tracked changes · ${upcoming} upcoming · updated every two weeks · free, always`);
      setText('stat-countries', Object.keys(countryToRegion).length);
      setText('stat-changes', CHANGES.length);
      setText('stat-upcoming', upcoming);
    }

    function isKnownCountry(code){
      return typeof code === 'string' && Object.prototype.hasOwnProperty.call(countryToRegion, code);
    }

    function initializeFromURL(){
      renderProofLine();
      renderRegionCoverage();
      renderCoverageList();
      renderCoverageMap();
      const search = window.location.search || '';
      // Handles ?countries= and legacy ?country= (via readSelection); unknown values are dropped.
      const initial = PayrollFilters.readUrlState(search, countryToRegion);
      state = {countries: initial.countries, region: initial.region, filter: initial.filter, when: initial.when, search: (initial.search || '').trim().toLowerCase()};
      if(/[?&](countries|country|filter|region|when|q)=/.test(search) || window.location.hash === '#changelog'){
        showChangelogNav();
        renderChangelog();
      } else {
        renderCountryPicker();
      }
      if(search) writeUrl(); // rewrites ?country= to ?countries= and strips invalid values
    }

    if(document.readyState === 'loading'){
      document.addEventListener('DOMContentLoaded', initializeFromURL);
    } else {
      initializeFromURL();
    }

    function escapeHtml(s){
      return String(s == null ? '' : s)
        .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
    }

    // Status chip (In force / Upcoming / Draft / Ongoing) followed by the date formatted from `effective`.
    function statusChip(item){
      const key = PayrollFilters.statusOf(item, LAST_VERIFIED.toISOString().slice(0, 10));
      const date = PayrollFilters.formatEffective(item.effective);
      return `<span class="status-chip status-${key}"><span class="visually-hidden">Status: </span>${escapeHtml(PayrollFilters.STATUS_LABELS[key])}</span>` +
        (date ? `<span class="status-date">${escapeHtml(date)}</span>` : '');
    }

    const LAST_VERIFIED_LABEL = LAST_VERIFIED.toLocaleDateString('en-GB', {day: 'numeric', month: 'long', year: 'numeric', timeZone: 'UTC'});
    const footerVerified = document.getElementById('footer-verified');
    if(footerVerified) footerVerified.textContent = LAST_VERIFIED_LABEL;

    function renderDetail(item){
      const d = item.detail;
      if(!d) return '<p class="detail-empty">No further detail recorded for this item yet.</p>';

      const employerList = d.employer && d.employer.length
        ? `<div class="detail-box employer"><div class="detail-who">For the employer</div><ul>${d.employer.map(x => `<li>${escapeHtml(x)}</li>`).join('')}</ul></div>`
        : '';
      const employeeList = d.employee && d.employee.length
        ? `<div class="detail-box employee"><div class="detail-who">For the employee</div><ul>${d.employee.map(x => `<li>${escapeHtml(x)}</li>`).join('')}</ul></div>`
        : '';

      return `
        ${d.lead ? `<p class="detail-lead">${PayrollFilters.highlight(d.lead, state.search)}</p>` : ''}
        ${(employerList || employeeList) ? `<div class="detail-actions">${employerList}${employeeList}</div>` : ''}
        ${d.example ? `<div class="detail-example"><span class="detail-example-label">In practice</span>${escapeHtml(d.example)}</div>` : ''}
        ${d.note ? `<p class="detail-note">${escapeHtml(d.note)}</p>` : ''}
        <p class="detail-verified">Payroll impact: ${escapeHtml(IMPACT[item.impact] || '')} · Last verified ${LAST_VERIFIED_LABEL}</p>
        ${d.sourceUrl ? `<a class="detail-source" href="${escapeHtml(d.sourceUrl)}" target="_blank" rel="noopener">${escapeHtml(d.sourceLabel || 'Source')} ↗</a>` : ''}
      `;
    }

    function toggleDetail(index){
      const card = document.querySelector(`.item-card[data-index="${index}"]`);
      if(!card) return;
      const panel = card.querySelector('.item-detail');
      const isOpen = card.classList.toggle('open');
      if(isOpen && panel && !panel.dataset.loaded){
        panel.innerHTML = renderDetail(currentChangelogItems[index]);
        panel.dataset.loaded = '1';
      }
    }

    // CP5 print: expand every filtered card before printing, restore afterwards.
    let printOpened = [];
    function printSummary(){
      const parts = [];
      const picked = state.countries.filter(isKnownCountry).map(countryName);
      parts.push(picked.length ? picked.join(', ') : 'All countries');
      if(state.region) parts.push(regionLabel(state.region));
      if(state.filter && state.filter !== 'all') parts.push(FILTER_LABELS[state.filter] || state.filter);
      if(state.when && state.when !== 'all') parts.push(PayrollFilters.WHEN_LABELS[state.when] || state.when);
      if(state.search) parts.push('Search: "' + state.search + '"');
      const date = new Date().toLocaleDateString('en-GB', {day: 'numeric', month: 'long', year: 'numeric'});
      return 'Intelligent Payroll — ' + parts.join(' · ') + ' — printed ' + date;
    }
    function beforePrint(){
      const header = document.getElementById('print-header');
      if(header) header.textContent = printSummary();
      printOpened = [];
      document.querySelectorAll('.item-card').forEach(card => {
        const panel = card.querySelector('.item-detail');
        const item = currentChangelogItems[Number(card.dataset.index)];
        if(panel && item && !panel.dataset.loaded){
          panel.innerHTML = renderDetail(item);
          panel.dataset.loaded = '1';
        }
        if(!card.classList.contains('open')){ card.classList.add('open'); printOpened.push(card); }
      });
    }
    function afterPrint(){
      printOpened.forEach(card => card.classList.remove('open'));
      printOpened = [];
    }
    window.addEventListener('beforeprint', beforePrint);
    window.addEventListener('afterprint', afterPrint);

    function regionLabel(r){
      return ({europe: 'Europe', apac: 'APAC', menat: 'MENAT', latam: 'LATAM', africa: 'Africa'})[r] || '';
    }

    // Display label for a country code, taken from CHANGES (never from the URL).
    function countryLabel(code){
      const item = CHANGES.find(c => c.country === code);
      return item ? item.flag + ' ' + item.name : code;
    }

    function currentFilteredChanges(){
      return PayrollFilters.applyFilters(CHANGES, state, countryToRegion);
    }

    function updateExportButton(n){
      const btn = document.getElementById('export-csv');
      if(!btn) return;
      btn.disabled = n === 0;
      btn.setAttribute('aria-label', 'Export ' + n + ' change' + (n === 1 ? '' : 's') + ' as CSV');
    }

    // Object URL of the last export. Revoked late (FileSaver.js practice): revoking immediately can cancel
    // the download in Firefox/Safari. A new export revokes any URL still pending.
    const CSV_URL_TTL_MS = 40000;
    const csvExport = {url: null, timer: null};
    function revokeCsvUrl(){
      if(csvExport.timer) clearTimeout(csvExport.timer);
      if(csvExport.url) URL.revokeObjectURL(csvExport.url);
      csvExport.url = null; csvExport.timer = null;
    }

    function exportCsv(){
      const items = currentFilteredChanges();
      if(items.length === 0) return;
      revokeCsvUrl();
      const link = document.querySelector('link[rel="canonical"]');
      const site = link ? link.href : '';
      const csv = PayrollFilters.toCsv(items, site, LAST_VERIFIED.toISOString().slice(0, 10));
      const blob = new Blob([csv], {type: 'text/csv;charset=utf-8'});
      const url = URL.createObjectURL(blob);
      const d = new Date();
      const pad = v => String(v).padStart(2, '0');
      const a = document.createElement('a');
      a.href = url;
      a.download = PayrollFilters.csvFilename(d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()));
      document.body.appendChild(a);
      a.click();
      a.remove();
      csvExport.url = url;
      csvExport.timer = setTimeout(revokeCsvUrl, CSV_URL_TTL_MS);
    }

    function renderChangelog(){
      const list = document.getElementById('changelog-list');
      const filtered = currentFilteredChanges();
      updateExportButton(filtered.length);
      const filter = state.filter || 'all';
      const region = state.region;
      const search = state.search;
      const picked = state.countries;
      const country = picked.length === 1 ? picked[0] : null;
      currentChangelogItems = filtered;

      document.querySelectorAll('.region-tab').forEach(btn => btn.classList.remove('active'));
      if(region){
        const regionBtn = [...document.querySelectorAll('.region-tab')].find(b => b.dataset.region === region);
        if(regionBtn) regionBtn.classList.add('active');
      }

      document.querySelectorAll('.filter-btn').forEach(btn => btn.classList.remove('active'));
      const filterBtn = [...document.querySelectorAll('.filter-btn')].find(b => b.dataset.filter === (filter || 'all'));
      if(filterBtn) filterBtn.classList.add('active');

      const when = state.when || 'all';
      document.querySelectorAll('.when-btn').forEach(btn => {
        const on = btn.dataset.when === when;
        btn.classList.toggle('active', on);
        btn.setAttribute('aria-pressed', on ? 'true' : 'false');
      });

      const searchInput = document.getElementById('search-input');
      if(searchInput) searchInput.value = search || '';

      // Banner lists every active constraint so users can see why results are limited.
      let bannerText = '';
      if(search || picked.length){
        bannerText = search
          ? `Showing results for "<strong>${escapeHtml(search)}</strong>"`
          : 'Showing changes';
        if(picked.length) bannerText += `${search ? ' in' : ' for'} <strong>${escapeHtml(picked.map(countryLabel).join(', '))}</strong>`;
        if(region) bannerText += ` in <strong>${escapeHtml(regionLabel(region))}</strong>`;
        if(filter !== 'all') bannerText += ` (filter: <strong>${escapeHtml(FILTER_LABELS[filter] || filter)}</strong>)`;
        if(when !== 'all') bannerText += ` (timing: <strong>${escapeHtml(PayrollFilters.WHEN_LABELS[when] || when)}</strong>)`;
        if(search || picked.length > 1) bannerText += ` (${filtered.length} ${search ? 'match' + (filtered.length === 1 ? '' : 'es') : 'change' + (filtered.length === 1 ? '' : 's')})`;
      }
      const banner = bannerText
        ? `<div class="filter-banner">
             <span>${bannerText}</span>
             <a href="#" class="filter-clear" data-action="clear-filter">Clear ✕</a>
           </div>`
        : '';

      const countryTotal = country ? CHANGES.filter(c => c.country === country).length : 0;
      const partial = (country && !search && countryTotal > 0 && countryTotal < 2)
        ? `<div class="partial-notice">Partial coverage: we currently track ${countryTotal} change for this country. Know of another? <a href="suggest.html">Tell us</a>.</div>`
        : '';

      const outsideRegion = filtered.length === 0 && region && picked.length > 0 && !picked.some(c => countryToRegion[c] === region);
      const emptyState = outsideRegion
        ? `<div class="detail-empty">
             <p>None of your selected countries (${escapeHtml(picked.map(countryLabel).join(', '))}) are in ${escapeHtml(regionLabel(region))}.</p>
             <p class="empty-actions"><a href="#" data-action="show-region">Show all of ${escapeHtml(regionLabel(region))}</a> · <a href="#" data-action="show-countries">Show my countries in all regions</a></p>
           </div>`
        : filtered.length === 0
        ? `<p class="detail-empty">No changes match${search ? ` "${escapeHtml(search)}"` : ' this filter'}. Try a different term or clear the filter.</p>`
        : '';

      list.innerHTML = banner + partial + emptyState + filtered.map((item, i) => `
        <div class="item-card" data-index="${i}">
          <button type="button" class="item-header" data-action="toggle-detail" aria-expanded="false">
            <div>
              <strong>${escapeHtml(item.flag)} ${escapeHtml(item.name)}</strong><br/>
              <span class="item-title">${PayrollFilters.highlight(item.title, state.search)}</span>
            </div>
            <span class="item-header-right">
              ${freshnessOf(item) === 'new' ? '<span class="badge fresh">New</span>' : freshnessOf(item) === 'updated' ? '<span class="badge fresh">Updated</span>' : ''}${item.impact === 'high' ? '<span class="badge impact-high" title="A new process, system, filing or calculation method">High impact</span>' : ''}${statusChip(item)}${item.badge ? '<span class="badge-note">' + escapeHtml(item.badge) + '</span>' : ''}
              <span class="item-chevron" aria-hidden="true"></span>
            </span>
          </button>
          <div class="item-detail"></div>
        </div>
      `).join('');
      renderCountryPicker();
    }

    // Multi-country picker: checkbox list grouped by region, chips and summary count.
    // Codes and labels come from countryToRegion/CHANGES only, never from the URL.
    function renderCountryPicker(){
      const listEl = document.getElementById('country-picker-list');
      const chipsEl = document.getElementById('country-chips');
      const summaryEl = document.getElementById('country-picker-summary');
      const picked = state.countries;
      const atCap = picked.length >= PayrollFilters.MAX_COUNTRIES;
      const capAttrs = ' disabled aria-describedby="country-cap-hint"';
      if(listEl){
        // Preserve scroll position and keyboard focus (by value) across the re-render.
        const scrollTop = listEl.scrollTop || 0;
        const active = document.activeElement;
        const focusValue = active && active.classList && active.classList.contains('country-check') ? active.value : null;
        listEl.innerHTML = ['europe', 'apac', 'menat', 'latam', 'africa'].map(r => {
          const codes = Object.keys(countryToRegion).filter(c => countryToRegion[c] === r)
            .sort((a, b) => countryName(a).localeCompare(countryName(b)));
          return `<fieldset class="country-group"><legend>${escapeHtml(regionLabel(r))}</legend>${codes.map(c => {
            const on = picked.includes(c);
            return `<label class="country-option"><input type="checkbox" class="country-check" name="countries" value="${escapeHtml(c)}"${on ? ' checked' : ''}${!on && atCap ? capAttrs : ''}> ${escapeHtml(countryLabel(c))}</label>`;
          }).join('')}</fieldset>`;
        }).join('');
        listEl.scrollTop = scrollTop;
        applyCountryFilter();
        if(focusValue && typeof listEl.querySelectorAll === 'function'){
          const box = [...listEl.querySelectorAll('input.country-check')].find(b => b.value === focusValue);
          if(box && typeof box.focus === 'function') box.focus();
        }
      }
      const capHint = document.getElementById('country-cap-hint');
      if(capHint){
        const capText = `Maximum ${PayrollFilters.MAX_COUNTRIES} countries selected`;
        if(capHint.textContent !== capText) capHint.textContent = capText; // avoid re-announcing (role=status)
        capHint.hidden = !atCap;
      }
      if(chipsEl){
        // Only rewrite when the markup changed, so the aria-live region is not re-announced on unrelated filter clicks.
        const chipsHtml = picked.length
          ? picked.filter(isKnownCountry).map(c => `<span class="chip">${escapeHtml(countryLabel(c))} <button type="button" class="chip-remove" data-action="remove-country" data-country="${escapeHtml(c)}" aria-label="Remove ${escapeHtml(countryName(c))}">×</button></span>`).join('')
            + '<button type="button" class="chip-clear" data-action="clear-countries">Clear countries</button>'
          : '';
        // The last rendered markup is cached on the element itself, so it does not depend on script order.
        if(chipsHtml !== chipsEl.renderedChipsHtml){ chipsEl.innerHTML = chipsHtml; chipsEl.renderedChipsHtml = chipsHtml; }
      }
      if(summaryEl) summaryEl.textContent = picked.length ? `Countries (${picked.length})` : 'Countries';
    }

    function focusAfterChipChange(code){
      const chipsEl = document.getElementById('country-chips');
      let target = null;
      if(code && chipsEl && typeof chipsEl.querySelectorAll === 'function')
        target = [...chipsEl.querySelectorAll('button.chip-remove')].find(b => b.dataset && b.dataset.country === code) || null;
      if(!target) target = document.getElementById('country-picker-summary');
      if(target && typeof target.focus === 'function') target.focus();
    }

    function countryName(code){
      const item = CHANGES.find(c => c.country === code);
      return item ? item.name : code;
    }

    // Type-to-filter: hide non-matching options with a class (no inline styles under the CSP).
    function applyCountryFilter(){
      const input = document.getElementById('country-filter');
      const listEl = document.getElementById('country-picker-list');
      if(!input || !listEl || typeof listEl.querySelectorAll !== 'function') return;
      const term = String(input.value || '').trim().toLowerCase();
      listEl.querySelectorAll('.country-group').forEach(group => {
        let shown = 0;
        group.querySelectorAll('label').forEach(label => {
          const match = !term || label.textContent.toLowerCase().includes(term);
          label.classList.toggle('is-hidden', !match);
          if(match) shown++;
        });
        group.classList.toggle('is-hidden', shown === 0);
      });
    }

    function setCountryPicked(code, on){
      if(!isKnownCountry(code)) return;
      const has = state.countries.includes(code);
      if(on && !has){
        if(state.countries.length >= PayrollFilters.MAX_COUNTRIES){ renderCountryPicker(); return; }
        state.countries = [...state.countries, code];
      } else if(!on && has){
        state.countries = state.countries.filter(c => c !== code);
      } else return;
      updateState();
    }

    function filterChanges(type){
      state.filter = type || 'all';
      updateState();
    }

    function setWhen(when){
      state.when = PayrollFilters.WHENS.includes(when) ? when : 'all';
      updateState();
    }

    function clearFilter(){
      state = {countries: [], region: null, filter: 'all', when: 'all', search: ''};
      updateState();
    }

    // Empty-state escapes: drop one side of a country/region intersection that matched nothing.
    function showWholeRegion(){
      state.countries = [];
      updateState();
    }

    function showCountriesAllRegions(){
      state.region = null;
      updateState();
    }

    function selectRegion(region){
      state.region = Object.values(countryToRegion).includes(region) ? region : null;
      updateState();
    }

    // Event handling. The page has no inline handlers because the content security policy forbids them.
    document.addEventListener('click', e => {
      const t = e.target;
      if (!(t instanceof Element)) return;
      // A click outside an open country picker closes it; other handlers still run and focus is not moved.
      const openPicker = document.getElementById('country-picker');
      if (openPicker && openPicker.open && !t.closest('#country-picker')) openPicker.open = false;
      const nav = t.closest('a.nav-link[data-view]');
      if (nav) { e.preventDefault(); showView(nav.dataset.view); return; }
      const tab = t.closest('.region-tab[data-region]');
      if (tab) { selectRegion(tab.dataset.region); return; }
      const filterBtn = t.closest('.filter-btn[data-filter]');
      if (filterBtn) { filterChanges(filterBtn.dataset.filter); return; }
      const whenBtn = t.closest('.when-btn[data-when]');
      if (whenBtn) { setWhen(whenBtn.dataset.when); return; }
      const scroll = t.closest('[data-scroll-to]');
      if (scroll) {
        e.preventDefault();
        const target = document.querySelector(scroll.dataset.scrollTo);
        if (target) target.scrollIntoView({behavior: 'smooth'});
        return;
      }
      const action = t.closest('[data-action]');
      if (!action) return;
      if (action.dataset.action === 'close-picker') {
        e.preventDefault();
        const picker = document.getElementById('country-picker');
        const summary = document.getElementById('country-picker-summary');
        if (picker) picker.open = false;
        if (summary) summary.focus();
      }
      else if (action.dataset.action === 'export-csv') { e.preventDefault(); exportCsv(); }
      else if (action.dataset.action === 'print') { e.preventDefault(); window.print(); }
      else if (action.dataset.action === 'clear-filter') { e.preventDefault(); clearFilter(); }
      else if (action.dataset.action === 'show-region') { e.preventDefault(); showWholeRegion(); }
      else if (action.dataset.action === 'show-countries') { e.preventDefault(); showCountriesAllRegions(); }
      else if (action.dataset.action === 'remove-country') {
        // Focus the next chip, else the previous one, else the picker summary (the chip is re-rendered away).
        const code = action.dataset.country;
        const shown = state.countries.filter(isKnownCountry);
        const i = shown.indexOf(code);
        const next = i < 0 ? null : (shown[i + 1] || shown[i - 1] || null);
        setCountryPicked(code, false);
        focusAfterChipChange(next);
      }
      else if (action.dataset.action === 'clear-countries') { state.countries = []; updateState(); focusAfterChipChange(null); }
      else if (action.dataset.action === 'toggle-detail') {
        const card = action.closest('.item-card');
        if (card) toggleDetail(Number(card.dataset.index));
      }
    });

    document.addEventListener('change', e => {
      const t = e.target;
      if (t instanceof HTMLSelectElement && t.classList.contains('country-selector')) {
        goToCountry(t.value);
        t.value = '';
      } else if (t instanceof HTMLInputElement && t.classList.contains('country-check') && t.closest('#country-picker-list')) {
        setCountryPicked(t.value, t.checked);
      }
    });

    document.addEventListener('input', e => {
      const t = e.target;
      if (t instanceof HTMLInputElement && t.id === 'country-filter') applyCountryFilter();
    });

    // Escape inside the open country picker closes it and returns focus to its summary.
    document.addEventListener('keydown', e => {
      if (e.key !== 'Escape') return;
      const picker = document.getElementById('country-picker');
      const t = e.target;
      if (picker && picker.open && t instanceof Element && t.closest('#country-picker')) {
        e.preventDefault();
        picker.open = false;
        const summary = document.getElementById('country-picker-summary');
        if (summary) summary.focus();
      }
    });

    // CP6: keep the open picker panel on screen; align it to the summary's right edge near the viewport edge.
    function alignPickerPanel() {
      const picker = document.getElementById('country-picker');
      const summary = document.getElementById('country-picker-summary');
      if (!picker || !summary || !picker.open) return;
      // Three states: default (left-aligned under the button), panel-align-right, or
      // panel-align-row (neither fits: the panel anchors to the filter row's left edge).
      const rect = summary.getBoundingClientRect();
      const panelW = Math.min(320, window.innerWidth - 32);
      const fitsLeft = rect.left + panelW <= window.innerWidth - 16;
      const fitsRight = !fitsLeft && rect.right - panelW >= 16;
      picker.classList.toggle('panel-align-right', fitsRight);
      picker.classList.toggle('panel-align-row', !fitsLeft && !fitsRight);
    }
    const pickerEl = document.getElementById('country-picker');
    if (pickerEl) pickerEl.addEventListener('toggle', alignPickerPanel);
    window.addEventListener('resize', alignPickerPanel);

    document.addEventListener('submit', e => {
      const f = e.target;
      if (f instanceof HTMLFormElement && f.classList.contains('search-form')) {
        e.preventDefault();
        performSearch(document.getElementById('search-input').value);
      }
    });
